    private static JLabel small(String text) {
        JLabel l = new JLabel(text);
        l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setAlignmentX(Component.LEFT_ALIGNMENT);
        return l;
    }

    private static JPanel labeled(String text, JComponent c) {
        JPanel p = vbox();
        p.setOpaque(false);
        p.setAlignmentX(Component.LEFT_ALIGNMENT);
        p.add(small(text));
        p.add(Box.createVerticalStrut(3));
        c.setAlignmentX(Component.LEFT_ALIGNMENT);
        p.add(c);
        return p;
    }

    private static JTextField field() {
        JTextField f = new JTextField();
        styleField(f);
        return f;
    }

    private static void styleField(JTextField f) {
        f.setBackground(FIELD_BG);
        f.setForeground(Color.WHITE);
        f.setCaretColor(Color.WHITE);
        f.setBorder(new CompoundBorder(BorderFactory.createLineBorder(new Color(17, 17, 17)), new EmptyBorder(4, 6, 4, 6)));
        f.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        f.setAlignmentX(Component.LEFT_ALIGNMENT);
    }

    private static JCheckBox check(String text, boolean on) {
        JCheckBox c = new JCheckBox(text, on);
        c.setOpaque(false);
        c.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        c.setFocusPainted(false);
        c.setAlignmentX(Component.LEFT_ALIGNMENT);
        return c;
    }

    private static JComboBox<String> combo(String[] values) {
        JComboBox<String> c = new JComboBox<>(values);
        c.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        c.setAlignmentX(Component.LEFT_ALIGNMENT);
        return c;
    }

    private static JButton button(String text) {
        JButton b = new JButton(text);
        b.setBackground(new Color(40, 40, 40));
        b.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        b.setFont(FontManager.getRunescapeBoldFont());
        b.setFocusPainted(false);
        b.setBorderPainted(false);
        b.setMargin(new Insets(4, 9, 4, 9));
        b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        b.setAlignmentX(Component.LEFT_ALIGNMENT);
        return b;
    }

    /** One item line: icon, name (with suggestions from the game's item list), amount, remove. */
    private final class ItemRow {
        final JPanel panel = new JPanel(new BorderLayout(6, 0));
        final HintField name = new HintField();
        final JTextField qty = field();
        final JLabel icon = new JLabel();
        private final JPopupMenu suggest = new JPopupMenu();
        private final Timer searchTimer;
        private boolean settingText;

        ItemRow(String n, String q) {
            panel.setOpaque(false);
            panel.setAlignmentX(Component.LEFT_ALIGNMENT);
            panel.setBorder(new EmptyBorder(0, 0, 4, 0));
            icon.setPreferredSize(new Dimension(30, 26));
            icon.setHorizontalAlignment(SwingConstants.CENTER);
            icon.setOpaque(true);
            icon.setBackground(new Color(62, 53, 41));
            icon.setBorder(BorderFactory.createLineBorder(Color.BLACK));
            name.setHint("Item name");
            name.setText(n);
            qty.setText(q);
            qty.setColumns(5);
            qty.setToolTipText("How many (e.g. 28, 1k)");
            JButton remove = button("x");
            remove.setToolTipText("Remove this item");
            remove.addActionListener(e -> {
                items.remove(this);
                itemRows.remove(panel);
                itemRows.revalidate();
                refresh();
            });
            JPanel right = new JPanel(new BorderLayout(4, 0));
            right.setOpaque(false);
            right.add(qty, BorderLayout.CENTER);
            right.add(remove, BorderLayout.EAST);
            panel.add(icon, BorderLayout.WEST);
            panel.add(name, BorderLayout.CENTER);
            panel.add(right, BorderLayout.EAST);
            panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));

            suggest.setFocusable(false);
            searchTimer = new Timer(250, e -> showSuggestions());
            searchTimer.setRepeats(false);
            name.getDocument().addDocumentListener(new Doc(() -> {
                if (!settingText) searchTimer.restart();
                refresh();
            }));
            listen(qty);
            if (!n.isEmpty()) setIconFor(n);
        }

        private List<ItemPrice> search(String text) {
            try { return plugin.getItemManager().search(text); } catch (RuntimeException e) { return new ArrayList<>(); }
        }

        private void showSuggestions() {
            String text = name.getText().trim();
            suggest.setVisible(false);
            suggest.removeAll();
            if (text.length() < 2 || text.contains("/") || !name.isShowing()) return;
            List<ItemPrice> found = search(text);
            int shown = 0;
            for (ItemPrice p : found) {
                if (p.getName().equalsIgnoreCase(text)) { setIcon(p.getId()); continue; }
                JMenuItem mi = new JMenuItem(p.getName());
                mi.addActionListener(e -> {
                    settingText = true;
                    name.setText(p.getName());
                    settingText = false;
                    setIcon(p.getId());
                    refresh();
                });
                suggest.add(mi);
                if (++shown >= 8) break;
            }
            if (shown > 0) suggest.show(name, 0, name.getHeight());
        }

        private void setIconFor(String n) {
            for (ItemPrice p : search(n)) {
                if (p.getName().equalsIgnoreCase(n.trim())) { setIcon(p.getId()); return; }
            }
        }

        private void setIcon(int id) {
            AsyncBufferedImage img = plugin.getItemManager().getImage(id);
            img.addTo(icon);
        }
    }

    /** A text field that shows grey hint text while empty. */
    private static final class HintField extends JTextField {
        private String hint = "";

        HintField() { styleField(this); }

        void setHint(String hint) {
            this.hint = hint == null ? "" : hint;
            repaint();
        }

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            if (!getText().isEmpty() || hint.isEmpty()) return;
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            g2.setColor(new Color(124, 124, 124));
            g2.setFont(getFont());
            Insets in = getInsets();
            FontMetrics fm = g2.getFontMetrics();
            g2.drawString(hint, in.left, (getHeight() - fm.getHeight()) / 2 + fm.getAscent());
            g2.dispose();
        }
    }

    /** The form scrolls up and down only, always as wide as the window. */
    private static final class ScrollTrack extends JPanel implements Scrollable {
        ScrollTrack() {
            super(new BorderLayout());
            setBackground(ColorScheme.DARK_GRAY_COLOR);
        }
        @Override public Dimension getPreferredScrollableViewportSize() { return getPreferredSize(); }
        @Override public int getScrollableUnitIncrement(Rectangle r, int o, int d) { return 16; }
        @Override public int getScrollableBlockIncrement(Rectangle r, int o, int d) { return r.height; }
        @Override public boolean getScrollableTracksViewportWidth() { return true; }
        @Override public boolean getScrollableTracksViewportHeight() { return false; }
    }

    private static final class Doc implements DocumentListener {
        private final Runnable r;
        Doc(Runnable r) { this.r = r; }
        @Override public void insertUpdate(DocumentEvent e) { r.run(); }
        @Override public void removeUpdate(DocumentEvent e) { r.run(); }
        @Override public void changedUpdate(DocumentEvent e) { r.run(); }
    }
}

package com.routeplanner;

import com.google.gson.Gson;
import com.routeplanner.model.Route;
import com.routeplanner.util.RouteSerializer;

import java.util.ArrayDeque;
import java.util.Collections;
import java.util.Deque;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;

/**
 * Snapshot-based undo/redo for structural edits to a route (delete step, reorder step).
 * Step contents are not tracked -- the step editor already handles those.
 *
 * <p>Each route keeps its own stacks, keyed by object <em>identity</em> rather than equals().
 * Route is a Lombok {@code @Data} class, so its hashCode shifts whenever its contents change and
 * two routes with identical contents would collide; an IdentityHashMap sidesteps both problems.
 */
public class RouteHistory {
    private static final int MAX_DEPTH = 30;

    private static final class Entry {
        final String label;
        final String json;
        Entry(String label, String json) { this.label = label; this.json = json; }
    }

    private final Map<Route, Deque<Entry>> undo = new IdentityHashMap<>();
    private final Map<Route, Deque<Entry>> redo = new IdentityHashMap<>();

    /** Snapshot the route as it stands right now, before the caller mutates it. */
    public void push(Route route, String label, Gson gson) {
        if (route == null) return;
        String json = snapshot(route, gson);
        if (json == null) return;
        Deque<Entry> stack = stack(undo, route);
        stack.push(new Entry(label, json));
        while (stack.size() > MAX_DEPTH) stack.removeLast();
        stack(redo, route).clear();
    }

    public boolean canUndo(Route route) { return !isEmpty(undo, route); }
    public boolean canRedo(Route route) { return !isEmpty(redo, route); }

    public String peekUndoLabel(Route route) { return peekLabel(undo, route); }
    public String peekRedoLabel(Route route) { return peekLabel(redo, route); }

    /** @return label of the action undone, or null if there was nothing to undo. */
    public String undo(Route route, Gson gson) {
        return move(route, gson, undo, redo);
    }

    /** @return label of the action redone, or null if there was nothing to redo. */
    public String redo(Route route, Gson gson) {
        return move(route, gson, redo, undo);
    }

    /** Drop a route's history, e.g. once the route itself has been deleted. */
    public void forget(Route route) {
        undo.remove(route);
        redo.remove(route);
    }

    private String move(Route route, Gson gson, Map<Route, Deque<Entry>> fromMap,
                        Map<Route, Deque<Entry>> toMap) {
        if (route == null || isEmpty(fromMap, route)) return null;
        Deque<Entry> from = stack(fromMap, route);
        Entry e = from.peek();
        String current = snapshot(route, gson);
        if (current == null) return null;
        if (!restore(route, e.json, gson)) return null;
        from.pop();
        Deque<Entry> to = stack(toMap, route);
        to.push(new Entry(e.label, current));
        while (to.size() > MAX_DEPTH) to.removeLast();
        return e.label;
    }

    private Deque<Entry> stack(Map<Route, Deque<Entry>> m, Route route) {
        return m.computeIfAbsent(route, r -> new ArrayDeque<>());
    }

    private boolean isEmpty(Map<Route, Deque<Entry>> m, Route route) {
        if (route == null) return true;
        Deque<Entry> d = m.get(route);
        return d == null || d.isEmpty();
    }

    private String peekLabel(Map<Route, Deque<Entry>> m, Route route) {
        if (isEmpty(m, route)) return null;
        return m.get(route).peek().label;
    }

    private String snapshot(Route route, Gson gson) {
        try {
            return RouteSerializer.toJson(Collections.singletonList(route), gson);
        } catch (Exception ex) {
            return null;
        }
    }

    /**
     * Copy a snapshot's contents back into the existing Route instance. The object itself is never
     * swapped: the plugin's active-route reference and this class's identity keys both rely on the
     * instance staying put.
     */
    private boolean restore(Route route, String json, Gson gson) {
        try {
            List<Route> parsed = RouteSerializer.fromJson(json, gson);
            if (parsed == null || parsed.isEmpty()) return false;
            Route snap = parsed.get(0);
            route.setName(snap.getName());
            route.setSections(snap.getSections());
            return true;
        } catch (Exception ex) {
            return false;
        }
    }
}

package com.routeplanner;

import com.routeplanner.model.Route;
import com.routeplanner.model.RouteStep;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.*;

import javax.inject.Inject;
import java.awt.*;
import java.util.List;

public class RouteHudOverlay extends Overlay {

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final RoutePlannerConfig config;
    private final com.routeplanner.bank.BankItemManager bankItemManager;

    private static final Color BG_COLOR      = new Color(52, 40, 24, 64);   // OSRS brown @ ~25% opacity
    private static final Color TITLE_COLOR   = new Color(255, 152, 31);     // OSRS orange
    private static final Color CURRENT_COLOR = new Color(255, 235, 200);    // warm cream
    private static final Color NEXT_COLOR    = new Color(190, 170, 140);    // muted tan
    private static final Color BORDER_COLOR  = new Color(160, 130, 85, 180); // tan/gold edge
    private static final Color HAVE_COLOR    = new Color(110, 210, 90);     // soft green

    @Inject
    public RouteHudOverlay(Client client, RoutePlannerPlugin plugin, RoutePlannerConfig config,
                           com.routeplanner.bank.BankItemManager bankItemManager) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.bankItemManager = bankItemManager;
        setPosition(OverlayPosition.TOP_LEFT);
        // Under the game's interfaces: an open bank, shop or chat box covers the HUD instead of
        // the HUD covering them.
        setLayer(OverlayLayer.UNDER_WIDGETS);
        setPriority(OverlayPriority.MED);
        setMovable(true);
        setResizable(false);
        setSnappable(true);
    }

    private java.util.List<String> wrapText(String s, int maxChars) {
        java.util.List<String> out = new java.util.ArrayList<>();
        if (s == null) return out;
        StringBuilder cur = new StringBuilder();
        for (String word : s.split(" ")) {
            if (cur.length() > 0 && cur.length() + word.length() + 1 > maxChars) {
                out.add(cur.toString());
                cur = new StringBuilder();
            }
            if (cur.length() > 0) cur.append(" ");
            cur.append(word);
        }
        if (cur.length() > 0) out.add(cur.toString());
        return out;
    }

    /** Bank-like windows the HUD steps aside for (it can't be drawn beneath them in every renderer). */
    private static final int[] COVERING_WINDOWS = {
        net.runelite.api.gameval.InterfaceID.Bankmain.UNIVERSE,
        net.runelite.api.gameval.InterfaceID.BankDepositbox.UNIVERSE,
        net.runelite.api.gameval.InterfaceID.Shopmain.UNIVERSE,
        net.runelite.api.gameval.InterfaceID.GeOffers.UNIVERSE,
        net.runelite.api.gameval.InterfaceID.SeedVault.UNIVERSE,
    };
    private int lastWidth, lastHeight; // size when last drawn; hidden frames report none

    /** True when an open bank, shop, GE or similar window overlaps where the HUD sits. */
    private boolean coveredByWindow() {
        Rectangle at = getBounds();
        if (at == null) return false;
        Rectangle hud = new Rectangle(at.x, at.y, Math.max(at.width, lastWidth), Math.max(at.height, lastHeight));
        if (hud.width == 0 || hud.height == 0) return false;
        for (int id : COVERING_WINDOWS) {
            net.runelite.api.widgets.Widget w = client.getWidget(id);
            if (w != null && !w.isHidden() && w.getBounds() != null && w.getBounds().intersects(hud)) return true;
        }
        return false;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        Route activeRoute = plugin.getActiveRoute();
        if (coveredByWindow()) return null;

        if (activeRoute == null) return null;

        int fontStyle = config.hudFontBold() ? Font.BOLD : Font.PLAIN;
        graphics.setFont(config.hudFontFamily().toFont(config.hudFontSize(), fontStyle));
        FontMetrics fm = graphics.getFontMetrics();
        int lineHeight = fm.getHeight() + 3;
        int padding = 7;

        // Build content: [text, color]
        java.util.List<String[]> lines = new java.util.ArrayList<>();

        // Determine if we should show route steps or agility task
        boolean routeHasIncompleteStep = false;
        int routeCurrentIdx = -1;
        List<RouteStep> steps = activeRoute != null ? activeRoute.getSteps() : new java.util.ArrayList<>();

        if (activeRoute != null) {
            for (int i = 0; i < steps.size(); i++) {
                if (!steps.get(i).isCompleted()) {
                    routeCurrentIdx = i;
                    routeHasIncompleteStep = true;
                    break;
                }
            }
        }

        // Route fully complete (or empty): hide the HUD entirely
        if (activeRoute != null && !routeHasIncompleteStep) {
            return null;
        }

        // Show route name as title always
        if (activeRoute != null) {
            lines.add(new String[]{activeRoute.getName(), "TITLE"});
        }

        // Show route location step if there is one incomplete
        if (routeHasIncompleteStep) {
            RouteStep current = steps.get(routeCurrentIdx);
            String curPrefix = ">> " + (routeCurrentIdx + 1) + ". ";
            java.util.List<String> curWrapped = wrapText(curPrefix + current.getName(), 42);
            for (int i = 0; i < curWrapped.size(); i++) {
                String curLine = i == 0 ? curWrapped.get(i) : "     " + curWrapped.get(i);
                lines.add(new String[]{curLine, "CURRENT"});
            }
            if (routeCurrentIdx + 1 < steps.size()) {
                RouteStep next = steps.get(routeCurrentIdx + 1);
                String nxtPrefix = "   " + (routeCurrentIdx + 2) + ". ";
                java.util.List<String> nxtWrapped = wrapText(nxtPrefix + next.getName(), 42);
                for (int i = 0; i < nxtWrapped.size(); i++) {
                    String nxtLine = i == 0 ? nxtWrapped.get(i) : "     " + nxtWrapped.get(i);
                    lines.add(new String[]{nxtLine, "NEXT"});
                }
            }
        }

        // Getting on or off a boat (Sailing), or a teleport the route takes: say so, since the line
        // stops there and there's nothing in the world to highlight. Likewise "Use rope on Rock":
        // the object lights up, but it takes an item rather than a click.
        if (routeHasIncompleteStep) {
            com.routeplanner.transport.Transport t = plugin.getPathfinderOverlay().getActiveTransition();
            if (t != null && t.actionText != null
                    && (t.teleport || t.actionText.startsWith(com.routeplanner.sailing.SailingDocks.BOARD)
                        || t.actionText.startsWith(com.routeplanner.sailing.SailingDocks.DISEMBARK)
                        || t.actionText.startsWith("Use "))) {
                lines.add(new String[]{"---", "DIM"});
                for (String wrapped : wrapText(t.actionText, 42)) lines.add(new String[]{wrapped, "TITLE"});
            }
        }

        // Sailing countdowns and the voyage time
        if (routeHasIncompleteStep) {
            java.util.List<String> sailing = plugin.getSailingTimers().hudLines(
                plugin.getPathfinderOverlay().getCachedPath(), plugin.getSailingDocks());
            if (!sailing.isEmpty()) {
                lines.add(new String[]{"---", "DIM"});
                for (String line : sailing) lines.add(new String[]{line, "CURRENT"});
            }
        }

        // Item checklist section for ITEM steps
        if (routeHasIncompleteStep) {
            RouteStep curStep = steps.get(routeCurrentIdx);
            if (curStep.hasItems()) {
                lines.add(new String[]{"---", "DIM"});
                String mode = curStep.getItemMode();
                if ("SELL".equals(mode)) {
                    lines.add(new String[]{"Sell:", "TITLE"});
                    for (String[] st : bankItemManager.getSellStatusList(curStep.getItemList())) {
                        boolean sold = st[1].equals("SOLD");
                        String mark = sold ? "[x] " : "[  ] ";
                        lines.add(new String[]{"  " + mark + st[0], sold ? "HAVE" : "CURRENT"});
                    }
                } else {
                    boolean gathering = curStep.getSkillingTargetNpc() != null || curStep.getSkillingTargetObject() != null;
                    String header = "SHOP".equals(mode) ? "Buy:"
                        : ("PICKUP".equals(mode) && !gathering ? "Pick up:" : "Gather:");
                    lines.add(new String[]{header, "TITLE"});
                    java.util.Map<String, Long> baseline = curStep.countsGainedItems()
                        ? curStep.getPickupBaseline() : null;
                    for (String[] st : bankItemManager.getItemStatusList(curStep.getItemList(), baseline)) {
                        boolean have = st[1].equals("HAVE");
                        String mark = have ? "[x] " : "[  ] ";
                        lines.add(new String[]{"  " + mark + st[0], have ? "HAVE" : "CURRENT"});
                    }
                }
            }
        }

        // Catch goal (Sailing trawling)
        if (routeHasIncompleteStep) {
            RouteStep curStep = steps.get(routeCurrentIdx);
            if (curStep.hasCatchGoal()) {
                lines.add(new String[]{"---", "DIM"});
                lines.add(new String[]{"Catch:", "TITLE"});
                boolean done = curStep.getCatchProgress() >= curStep.getCatchGoal();
                lines.add(new String[]{"  " + Math.min(curStep.getCatchProgress(), curStep.getCatchGoal()) + " / "
                    + curStep.getCatchGoal() + " " + curStep.getCatchFish(), done ? "HAVE" : "CURRENT"});
            }
        }

        // Note step section (informational, not tracked)
        if (routeHasIncompleteStep) {
            RouteStep curStep = steps.get(routeCurrentIdx);
            if (curStep.hasNote()) {
                lines.add(new String[]{"---", "DIM"});
                String note = (curStep.getNoteText() != null && !curStep.getNoteText().isEmpty())
                    ? curStep.getNoteText() : curStep.getName();
                for (String para : note.split("\\r?\\n")) {
                    if (para.trim().isEmpty()) continue;
                    for (String wrapped : wrapText(para, 42)) {
                        lines.add(new String[]{wrapped, "CURRENT"});
                    }
                }
                if (curStep.getNpcKillCount() > 0) {
                    lines.add(new String[]{"Kills: " + curStep.getNpcKillProgress()
                        + " / " + curStep.getNpcKillCount(), "TITLE"});
                } else {
                    // Only show "mark complete" if no component will auto-complete the step
                    boolean hasAutoComplete = curStep.hasItems() || curStep.hasSkillGoal()
                        || (curStep.hasQuest() && curStep.isQuestComplete())
                        || curStep.getWorldPoint() != null;
                    if (!hasAutoComplete) {
                        lines.add(new String[]{"(mark complete to continue)", "DIM"});
                    }
                }
            }
        }

        // XP tracker for the current step only; a later step's goal shouldn't show early
        if (routeHasIncompleteStep) {
            for (com.routeplanner.model.RouteStep s : java.util.Collections.singletonList(steps.get(routeCurrentIdx))) {
                if (!s.isCompleted() && s.hasSkillGoal()
                        && s.getSkillingGoalType() != null) {
                    String sk = s.getSkillingSkill() != null
                        ? s.getSkillingSkill().substring(0,1).toUpperCase()
                          + s.getSkillingSkill().substring(1).toLowerCase() : "?";
                    net.runelite.api.Skill apiSk = null;
                    try { apiSk = net.runelite.api.Skill.valueOf(
                        s.getSkillingSkill().toUpperCase()); } catch (Exception ignored) {}
                    int curLvl = apiSk != null ? client.getRealSkillLevel(apiSk) : 0;
                    long curXp = apiSk != null ? client.getSkillExperience(apiSk) : 0;

                    lines.add(new String[]{"---", "DIM"});
                    String gt = s.getSkillingGoalType();
                    if (gt.equals("XP_GAIN")) {
                        lines.add(new String[]{sk + " XP Gained:", "TITLE"});
                        lines.add(new String[]{"  +" + String.format("%,d", s.getSkillingProgress())
                            + " / +" + String.format("%,d", s.getSkillingGoalValue()), "CURRENT"});
                    } else if (gt.equals("XP_TARGET")) {
                        lines.add(new String[]{sk + " Total XP:", "TITLE"});
                        lines.add(new String[]{"  " + String.format("%,d", curXp)
                            + " / " + String.format("%,d", s.getSkillingGoalValue()), "CURRENT"});
                    } else if (gt.equals("LEVEL")) {
                        lines.add(new String[]{sk + " Level:", "TITLE"});
                        lines.add(new String[]{"  " + curLvl + " / " + s.getSkillingGoalValue(), "CURRENT"});
                    }
                    lines.add(new String[]{"Lvl: " + curLvl, "NEXT"});
                    break;
                }
            }
        }

        // Calculate size
        int maxWidth = 0;
        for (String[] line : lines) {
            int w = fm.stringWidth(line[0]);
            if (w > maxWidth) maxWidth = w;
        }
        int width = maxWidth + padding * 2 + 4;
        int totalHeight = padding * 2 + lines.size() * lineHeight;

        // Theme palette
        com.routeplanner.HudTheme theme = config.hudTheme();
        Color bgC, borderC, titleC, currentC, nextC, haveC, dimC, dividerC;
        if (theme == com.routeplanner.HudTheme.QUEST_HELPER) {
            bgC      = new Color(70, 61, 50, 156);   // RuneLite standard overlay background
            borderC  = new Color(60, 60, 60, 140);
            titleC   = new Color(255, 255, 255);
            currentC = new Color(255, 255, 255);
            nextC    = new Color(190, 190, 190);
            haveC    = new Color(0, 255, 0);
            dimC     = new Color(170, 170, 170);
            dividerC = new Color(255, 255, 255, 40);
        } else if (theme == com.routeplanner.HudTheme.CUSTOM) {
            bgC      = config.hudBgColor();
            borderC  = config.hudBorderColor();
            titleC   = config.hudTitleColor();
            currentC = config.hudCurrentColor();
            nextC    = config.hudNextColor();
            haveC    = config.hudHaveColor();
            dimC     = config.hudDimColor();
            dividerC = config.hudDividerColor();
        } else { // OSRS_BROWN (default)
            bgC      = BG_COLOR;
            borderC  = BORDER_COLOR;
            titleC   = TITLE_COLOR;
            currentC = CURRENT_COLOR;
            nextC    = NEXT_COLOR;
            haveC    = HAVE_COLOR;
            dimC     = new Color(155, 135, 105);
            dividerC = new Color(185, 145, 85, 45);
        }

        // Background
        graphics.setColor(bgC);
        graphics.fillRoundRect(0, 0, width, totalHeight, 6, 6);
        boolean drawOutline = theme != com.routeplanner.HudTheme.CUSTOM || config.hudOutline();
        if (drawOutline) {
            int thickness = theme == com.routeplanner.HudTheme.CUSTOM ? Math.max(1, config.hudBorderThickness()) : 1;
            graphics.setColor(borderC);
            graphics.setStroke(new BasicStroke(thickness));
            graphics.drawRoundRect(0, 0, width - 1, totalHeight - 1, 6, 6);
        }

        // Text
        int y = padding + fm.getAscent();
        for (String[] line : lines) {
            Color color;
            switch (line[1]) {
                case "TITLE":   color = titleC; break;
                case "CURRENT": color = currentC; break;
                case "NEXT":    color = nextC; break;
                case "HAVE":    color = haveC; break;
                default:        color = dimC; break;
            }
            if (line[0].equals("---")) {
                graphics.setColor(dividerC);
                graphics.drawLine(padding, y - fm.getAscent() / 2, width - padding, y - fm.getAscent() / 2);
                y += lineHeight / 2;
                continue;
            }
            // dark shadow for legibility over the transparent background
            graphics.setColor(new Color(0, 0, 0, 190));
            graphics.drawString(line[0], padding + 1, y + 1);
            graphics.setColor(color);
            graphics.drawString(line[0], padding, y);
            y += lineHeight;
        }

        lastWidth = width;
        lastHeight = totalHeight;
        return new Dimension(width, totalHeight);
    }
}

package com.routeplanner;

import com.routeplanner.model.Route;
import lombok.extern.slf4j.Slf4j;

import javax.swing.*;
import javax.swing.filechooser.FileNameExtensionFilter;
import java.awt.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.Arrays;
import java.util.List;

@Slf4j
public class RouteImportExport {

    private final RoutePlannerPlugin plugin;
    private final RoutePlannerPanel panel;

    public RouteImportExport(RoutePlannerPlugin plugin, RoutePlannerPanel panel) {
        this.plugin = plugin;
        this.panel = panel;
    }

    public void exportRoute(Route route) {
        JFileChooser chooser = new JFileChooser();
        chooser.setDialogTitle("Export Route");
        chooser.setSelectedFile(new File(route.getName().replaceAll("[^a-zA-Z0-9_-]", "_") + ".json"));
        chooser.setFileFilter(new FileNameExtensionFilter("JSON files", "json"));

        int result = chooser.showSaveDialog(null);
        if (result != JFileChooser.APPROVE_OPTION) return;

        File file = chooser.getSelectedFile();
        if (!file.getName().endsWith(".json")) {
            file = new File(file.getAbsolutePath() + ".json");
        }

        try {
            String json = plugin.getRouteGson().toJson(route);
            Files.write(file.toPath(), json.getBytes(StandardCharsets.UTF_8));
            JOptionPane.showMessageDialog(null,
                "Route exported to:\n" + file.getAbsolutePath(),
                "Export Successful", JOptionPane.INFORMATION_MESSAGE);
            log.info("Exported route {} to {}", route.getName(), file.getAbsolutePath());
        } catch (IOException e) {
            log.error("Failed to export route", e);
            JOptionPane.showMessageDialog(null,
                "Export failed: " + e.getMessage(),
                "Export Error", JOptionPane.ERROR_MESSAGE);
        }
    }

    public void exportAllRoutes() {
        JFileChooser chooser = new JFileChooser();
        chooser.setDialogTitle("Export All Routes");
        chooser.setSelectedFile(new File("routes_export.json"));
        chooser.setFileFilter(new FileNameExtensionFilter("JSON files", "json"));

        int result = chooser.showSaveDialog(null);
        if (result != JFileChooser.APPROVE_OPTION) return;

        File file = chooser.getSelectedFile();
        if (!file.getName().endsWith(".json")) {
            file = new File(file.getAbsolutePath() + ".json");
        }

        try {
            String json = plugin.getRouteGson().toJson(plugin.getRoutes());
            Files.write(file.toPath(), json.getBytes(StandardCharsets.UTF_8));
            JOptionPane.showMessageDialog(null,
                "All routes exported to:\n" + file.getAbsolutePath(),
                "Export Successful", JOptionPane.INFORMATION_MESSAGE);
        } catch (IOException e) {
            log.error("Failed to export routes", e);
            JOptionPane.showMessageDialog(null,
                "Export failed: " + e.getMessage(),
                "Export Error", JOptionPane.ERROR_MESSAGE);
        }
    }

    /**
     * A JFileChooser using the platform's native look and feel (GTK on Linux, etc.) instead of
     * Swing's default cross-platform "Metal" theme, which several users found looked out of place
     * and confusing to navigate. Falls back silently to the default chooser if the system L&F
     * can't be set for any reason -- this is cosmetic, never worth failing an import/export over.
     */
    private JFileChooser newSystemFileChooser(String title) {
        // Use cross-platform look and feel for the file chooser so it works
        // correctly on Linux regardless of whether running under Wine or native.
        JFileChooser chooser = new JFileChooser();
        chooser.setDialogTitle(title);
        return chooser;
    }

    /**
     * Puts an updated copy of a route in place of the old one, in the same spot in the list. Ticks
     * carry over by section and step name, unless the file brings ticks of its own.
     */
    private void replaceRoute(Route old, Route updated) {
        boolean fileHasTicks = updated.getSteps().stream().anyMatch(com.routeplanner.model.RouteStep::isCompleted);
        if (!fileHasTicks) {
            java.util.Set<String> done = new java.util.HashSet<>();
            for (com.routeplanner.model.RouteSection sec : old.getSections()) {
                for (com.routeplanner.model.RouteStep st : sec.getSteps()) {
                    if (st.isCompleted()) done.add(sec.getName() + "\n" + st.getName());
                }
            }
            for (com.routeplanner.model.RouteSection sec : updated.getSections()) {
                for (com.routeplanner.model.RouteStep st : sec.getSteps()) {
                    st.setCompleted(done.contains(sec.getName() + "\n" + st.getName()));
                }
            }
        }
        updated.setName(old.getName());
        updated.setHubSourceId(old.getHubSourceId());
        int at = plugin.getRoutes().indexOf(old);
        plugin.deleteRoute(old);
        plugin.getRoutes().add(Math.max(0, Math.min(at, plugin.getRoutes().size())), updated);
        plugin.saveRoutesPublic();
        plugin.setActiveRoute(updated);
    }

    public void importRoute() {
        JFileChooser chooser = newSystemFileChooser("Import Route");
        chooser.setFileFilter(new FileNameExtensionFilter("JSON files", "json"));

        int result = chooser.showOpenDialog(null);
        if (result != JFileChooser.APPROVE_OPTION) return;

        File file = chooser.getSelectedFile();
        try {
            String json = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);

            // Try single route first
            try {
                Route route = plugin.getRouteGson().fromJson(json, Route.class);
                if (route != null) route.migrateIfNeeded();
                if (route != null && route.getName() != null) {
                    String name = route.getName();
                    Route existing = plugin.getRoutes().stream()
                        .filter(r -> r.getName().equalsIgnoreCase(name)).findFirst().orElse(null);
                    if (existing != null) {
                        Object[] options = {"Replace it", "Keep both", "Cancel"};
                        int choice = JOptionPane.showOptionDialog(null,
                            "You already have a route called \"" + existing.getName() + "\".\n"
                                + "Replace it with this one? Steps you've ticked off stay ticked.",
                            "Route already exists", JOptionPane.YES_NO_CANCEL_OPTION,
                            JOptionPane.QUESTION_MESSAGE, null, options, options[0]);
                        if (choice == 2 || choice == JOptionPane.CLOSED_OPTION) return;
                        if (choice == 0) {
                            replaceRoute(existing, route);
                            JOptionPane.showMessageDialog(null,
                                "Route \"" + route.getName() + "\" updated!",
                                "Import Successful", JOptionPane.INFORMATION_MESSAGE);
                            log.info("Replaced route: {}", route.getName());
                            return;
                        }
                        route.setName(name + " (imported)");
                    }
                    plugin.getRoutes().add(route);
                    plugin.saveRoutesPublic();
                    plugin.setActiveRoute(route);
                    JOptionPane.showMessageDialog(null,
                        "Route \"" + route.getName() + "\" imported!",
                        "Import Successful", JOptionPane.INFORMATION_MESSAGE);
                    log.info("Imported route: {}", route.getName());
                    return;
                }
            } catch (Exception ignored) {}

            // Try list of routes
            Route[] routes = plugin.getRouteGson().fromJson(json, Route[].class);
            if (routes != null) for (Route r : routes) r.migrateIfNeeded();
            if (routes != null && routes.length > 0) {
                int imported = 0;
                for (Route route : routes) {
                    if (route.getName() == null) continue;
                    String name = route.getName();
                    boolean exists = plugin.getRoutes().stream()
                        .anyMatch(r -> r.getName().equalsIgnoreCase(name));
                    if (exists) route.setName(name + " (imported)");
                    plugin.getRoutes().add(route);
                    imported++;
                }
                plugin.saveRoutesPublic();
                panel.refresh();
                JOptionPane.showMessageDialog(null,
                    imported + " route(s) imported!",
                    "Import Successful", JOptionPane.INFORMATION_MESSAGE);
            }

        } catch (Exception e) {
            log.error("Failed to import route", e);
            JOptionPane.showMessageDialog(null,
                "Import failed: " + e.getMessage(),
                "Import Error", JOptionPane.ERROR_MESSAGE);
        }
    }
}

