        routes = RouteSerializer.fromJson(json, getRouteGson());
    }

@Subscribe
    public void onGameTick(GameTick tick) {
        pathfinderOverlay.onGameTick();
        sailingTimers.onGameTick();

        if (client.getLocalPlayer() != null) {
            lastPlayerLocation = com.routeplanner.sailing.Sailing.position(client);
        }

        if (activeRoute == null) { pushLive(null); return; }
        RouteStep step = activeRoute.getActiveStep();
        pushLive(step);
        if (step != null && client.getTickCount() % 5 == 0) snapAgilityStart(step);

        // Rebuild NPC highlights when skilling step is active
        if (step != null && step.getSkillingTargetNpc() != null) {
            // Rebuild every 10 ticks to catch any missed spawns
            if (client.getTickCount() % 10 == 0) {
                skillingNpcHighlighter.rebuild();
            }
        }

        // Baselines, taken the moment the step becomes active: the inventory for PICKUP/SHOP (so
        // carried-over items don't count; MUST happen before the completion check) and the starting
        // XP for XP_GAIN (so the very first drop counts). They're saved with the step, so a reload
        // carries on; a reset, an imported route or another account takes fresh ones.
        if (step != null) takeBaselines(step);

        // Quest steps set to complete with the quest: check now and then (it runs a client script).
        if (step != null && step.hasQuest() && step.isQuestComplete() && client.getTickCount() % 3 == 0) {
            tryCompleteStep(step);
        }

        // Check item step completion
        if (step != null && (step.hasItems() || "DEPOSIT_ALL".equals(step.getItemMode()))) {
            boolean done;
            if ("DEPOSIT_ALL".equals(step.getItemMode())) {
                // Any bank counts as being there (banks have many booths). About 3 seconds after it
                // opens, check the inventory; keep checking while it's open until it's empty.
                net.runelite.api.widgets.Widget bankWidget = client.getWidget(net.runelite.api.gameval.InterfaceID.Bankmain.ITEMS);
                boolean bankOpen = bankWidget != null && !bankWidget.isHidden();
                if (!bankOpen || step != depositStep) {
                    depositStep = step;
                    depositOpenTick = bankOpen ? client.getTickCount() : -1;
                } else if (depositOpenTick < 0) {
                    depositOpenTick = client.getTickCount();
                }
                if (bankOpen) step.setLocationReached(true);
                done = false;
                if (bankOpen && client.getTickCount() - depositOpenTick >= DEPOSIT_CHECK_TICKS) {
                    net.runelite.api.ItemContainer inv = client.getItemContainer(net.runelite.api.InventoryID.INVENTORY);
                    done = inv != null && java.util.Arrays.stream(inv.getItems()).allMatch(i -> i.getId() <= 0);
                }
            } else if ("SELL".equals(step.getItemMode())) {
                // Arm once the items are seen in inventory, complete only after they're gone
                if (!bankItemManager.hasSoldAll(step.getItemList())) {
                    step.setSellArmed(true);
                }
                done = step.isSellArmed() && bankItemManager.hasSoldAll(step.getItemList());
            } else if (step.countsGainedItems()) {
                // Check items gained ABOVE the baseline snapshot taken when step started,
                // so carried-over items from prior steps don't count.
                done = itemsSatisfied(step);
            } else {
                done = bankItemManager.hasAllItems(step.getItemList());
            }
            if (done) {
                tryCompleteStep(step);
            }
        }

        // Reset kill progress + light up the NPC when a note-kill step becomes active
        if (step != null && step.getNpcHighlight() != null && step.getNpcKillCount() > 0) {
            if (step != lastKillStep) {
                step.setNpcKillProgress(0);
                lastKillStep = step;
                skillingNpcHighlighter.rebuild();
            }
        }

        // Dialogue option highlighting: advance through the sequence as menus open/close
        if (step != null && step.getDialogOptions() != null && !step.getDialogOptions().trim().isEmpty()) {
            if (step != lastDialogStep) {
                lastDialogStep = step;
                dialogProgress = 0;
                dialogOptionsVisibleLast = false;
                anyDialogueOpenLast = false;
            }
            net.runelite.api.widgets.Widget optWidget = client.getWidget(219, 1);
            boolean optionsVisible = optWidget != null && !optWidget.isHidden();
            boolean anyOpen = optionsVisible || isAnyDialogueOpen();
            if (anyOpen && !anyDialogueOpenLast) {
                dialogProgress = 0;
            }
            if (!optionsVisible && dialogOptionsVisibleLast) {
                dialogProgress++;
                if (dialogProgress >= step.getDialogOptions().split(",").length) {
                    tryCompleteStep(step);
                }
            }
            dialogOptionsVisibleLast = optionsVisible;
            anyDialogueOpenLast = anyOpen;
        } else {
            lastDialogStep = null;
        }

        // Teleport arrival. Landing only finishes the step when the teleport spot IS the goal: no
        // tile of its own, or a tile at the landing spot. A tile somewhere else still has to be
        // walked to after landing (e.g. teleport to Varrock, then go to the east bank).
        if (step != null && step.getTeleportDestination() != null
                && !step.hasSkillGoal() && !step.hasItems() && !step.hasNote()
                && client.getLocalPlayer() != null) {
            WorldPoint dest = step.getTeleportDestination();
            WorldPoint goal = step.getWorldPoint();
            boolean house = com.routeplanner.teleport.TeleportItems.isHouse(dest);
            boolean landingIsGoal = goal == null
                || (!house && goal.getPlane() == dest.getPlane() && goal.distanceTo2D(dest) <= 25);
            if (landingIsGoal) {
                WorldPoint playerPos = com.routeplanner.sailing.Sailing.position(client);
                boolean landed = house
                    ? client.getTopLevelWorldView().isInstance() // the house has no fixed tile
                    : playerPos.getPlane() == dest.getPlane() && playerPos.distanceTo2D(dest) <= 25;
                if (landed) {
                    if (goal != null) step.setLocationReached(true);
                    // Through the full check: chat options or a quest on the step still count.
                    tryCompleteStep(step);
                }
            }
        }


        if (step == null) return;

        // Boarding (Sailing): getting on a boat ends the walk to the gangplank. A step that
        // only asks you to board is then done; otherwise it carries on over the sea.
        if (step.hasBoarding() && !step.isBoarded()
                && com.routeplanner.sailing.Sailing.isSailing(client)) {
            step.setBoarded(true);
            tryCompleteStep(step);
            if (step.isCompleted()) return;
        }
        boolean boardingPending = pathfinderOverlay.isBoardingPending(step);

        // Sticky "reached": once we arrive, nav visuals (line + tile) switch off for the rest of the step
        if (step.getWorldPoint() != null && !step.isLocationReached() && !boardingPending
                && client.getLocalPlayer() != null
                && com.routeplanner.sailing.Sailing.isWithin(client, step.getWorldPoint(), 3)) {
            step.setLocationReached(true);
            arrivalHoldTicksRemaining = config.arrivalHideDelay(); // 50 = never hide until step complete
        }

        // Count down the arrival-hold timer each tick
        // At max value (50) = never auto-hide; only clears when step completes.
        if (arrivalHoldTicksRemaining > 0 && arrivalHoldTicksRemaining < 30) arrivalHoldTicksRemaining--;

        if (step.getWorldPoint() != null && !step.hasSkillGoal() && !step.hasItems() && !boardingPending
                && (!step.hasNote() || step.isNoteAutoComplete())) {
            if (com.routeplanner.sailing.Sailing.isWithin(client, step.getWorldPoint(), 3)) {
                // Through the full check: a Talk-to or quest step still waits for its picks/quest.
                tryCompleteStep(step);
            }
        }
    }

    @Subscribe
    public void onStatChanged(net.runelite.api.events.StatChanged event) {
        if (activeRoute == null) return;
        RouteStep step = activeRoute.getActiveStep();
        if (step == null || !step.hasSkillGoal()) return;
        if (step.getSkillingSkill() == null || step.getSkillingGoalType() == null) return;

        // Dynamically resolve skill by name
        net.runelite.api.Skill skill;
        try {
            skill = net.runelite.api.Skill.valueOf(step.getSkillingSkill().toUpperCase());
        } catch (Exception e) {
            return;
        }
        if (event.getSkill() != skill) return;

        String goalType = step.getSkillingGoalType();

        if (goalType.equals("XP_GAIN")) {
            if (step.getSkillingStartXp() <= 0) {
                step.setSkillingStartXp(event.getXp());
                log.info("Skilling XP_GAIN start: {}", event.getXp());
                return;
            }
            long gained = event.getXp() - step.getSkillingStartXp();
            step.setSkillingProgress(gained);
            log.info("Skilling XP gained: {}/{}", gained, step.getSkillingGoalValue());
            if (gained >= step.getSkillingGoalValue()) {
                log.info("Skilling XP gain goal reached!");
                tryCompleteStep(step);
            }
            if (panel != null) panel.refresh();
        } else if (goalType.equals("XP_TARGET")) {
            if (event.getXp() >= step.getSkillingGoalValue()) {
                log.info("Skilling XP target reached: {}", event.getXp());
                tryCompleteStep(step);
            }
        } else if (goalType.equals("LEVEL")) {
            if (event.getLevel() >= step.getSkillingGoalValue()) {
                log.info("Skilling level goal reached: {}", event.getLevel());
                tryCompleteStep(step);
            }
        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event) {
        if (getActiveRoute() == null || getActiveRoute().getActiveStep() == null) return;
        if (activeRoute == null) return;
        RouteStep step = activeRoute.getActiveStep();

        if (event.getNpc().getId() == step.getTargetId() && event.getNpc().isDead()) {
            completeStep(step);
        }
    }

    @Subscribe
    public void onItemDespawned(ItemDespawned event) {
        if (activeRoute == null) return;
        RouteStep step = activeRoute.getActiveStep();
        if (step == null || !step.hasItems()) return;
        if (event.getTile().getWorldLocation().equals(step.getWorldPoint())) {
            tryCompleteStep(step);
        }
    }

    @Provides
    RoutePlannerConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(RoutePlannerConfig.class);
    }

    @Subscribe
    public void onActorDeath(net.runelite.api.events.ActorDeath event) {
        if (activeRoute == null) return;
        RouteStep step = activeRoute.getActiveStep();
        if (step == null) return;
        if (step.getNpcHighlight() == null || step.getNpcKillCount() <= 0) return;
        if (!(event.getActor() instanceof net.runelite.api.NPC)) return;
        String name = ((net.runelite.api.NPC) event.getActor()).getName();
        if (name == null) return;
        String target = step.getNpcHighlight();
        boolean match = false;
        outer:
        for (String entry : target.split(",")) {
            for (String alt : entry.split("/")) {
                String t = alt.trim();
                if (name.equalsIgnoreCase(t)
                    || name.toLowerCase().startsWith(t.toLowerCase() + " ")
                    || name.toLowerCase().startsWith(t.toLowerCase() + "(")) {
                    match = true;
                    break outer;
                }
            }
        }
        if (!match) return;
        step.setNpcKillProgress(step.getNpcKillProgress() + 1);
        log.info("Note kill {}/{}: {}", step.getNpcKillProgress(), step.getNpcKillCount(), name);
        if (step.getNpcKillProgress() >= step.getNpcKillCount()) {
            tryCompleteStep(step);
        }
    }

    /** Trawling catches (Sailing) count toward the active step's catch goal. */
    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM) return;
        if (activeRoute == null) return;
        RouteStep step = activeRoute.getActiveStep();
        if (step == null || !step.hasCatchGoal()) return;
        com.routeplanner.sailing.CatchMessages.Catch c = com.routeplanner.sailing.CatchMessages.parse(event.getMessage());
        if (c == null || !com.routeplanner.sailing.CatchMessages.sameFish(c.fish, step.getCatchFish())) return;
        step.setCatchProgress(step.getCatchProgress() + c.count);
        tryCompleteStep(step);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING) {
            sailingDocks.reset();
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!"routeplanner".equals(event.getGroup())) return;
        if ("mode".equals(event.getKey())) {
            if (panel != null) {
                javax.swing.SwingUtilities.invokeLater(panel::refresh);
            }
        }
        if ("pathfinder".equals(event.getKey())) {
            pathfinderOverlay.clearPath();
        }
        if ("hudMatchInterface".equals(event.getKey()) && "true".equals(event.getNewValue())) {
            sampleInterfacePalette();
            configManager.setConfiguration("routeplanner", "hudMatchInterface", false);
        }
    }
}

package com.routeplanner;

import java.util.Arrays;

/**
 * The open and closed sets of one A* search in flat arrays: an open-addressing table from a packed
 * tile key to a node index, per-node cost and parent arrays, and a binary heap of node indices.
 * A route over the sea can explore a million tiles, which as HashMaps of WorldPoints takes several
 * times the memory and time.
 */
final class SearchGraph {

    static final int NONE = -1;

    private long[] tableKeys;
    private int[] tableNodes;
    private int tableMask;

    private long[] keys;
    private int[] g;
    private int[] f;
    private int[] parent;
    private int size;

    /** Queued entries as (f << 32 | node), so a node queued again at a lower cost leaves its old entry stale, not misplaced. */
    private long[] heap;
    private int heapSize;

    SearchGraph(int expected) {
        int cap = Integer.highestOneBit(Math.max(16, expected * 2) - 1) << 1;
        tableKeys = new long[cap];
        tableNodes = new int[cap];
        Arrays.fill(tableNodes, NONE);
        tableMask = cap - 1;
        keys = new long[expected];
        g = new int[expected];
        f = new int[expected];
        parent = new int[expected];
        heap = new long[expected];
    }

    static long key(int x, int y, int plane) {
        return ((long) plane << 32) | ((long) (x & 0xFFFF) << 16) | (y & 0xFFFF);
    }

    static int x(long key) { return (int) ((key >>> 16) & 0xFFFF); }
    static int y(long key) { return (int) (key & 0xFFFF); }
    static int plane(long key) { return (int) (key >>> 32); }

    int size() { return size; }
    long key(int node) { return keys[node]; }
    int g(int node) { return g[node]; }
    int parent(int node) { return parent[node]; }

    /** The node for {@code key}, or NONE if it hasn't been reached. */
    int find(long key) {
        int slot = slot(key);
        while (tableNodes[slot] != NONE) {
            if (tableKeys[slot] == key) return tableNodes[slot];
            slot = (slot + 1) & tableMask;
        }
        return NONE;
    }

    /**
     * Records reaching {@code key} at cost {@code cost} from {@code from} and queues it, unless it was
     * already reached at least as cheaply. Returns whether it was queued.
     */
    boolean offer(long key, int cost, int estimate, int from) {
        int node = find(key);
        if (node == NONE) {
            if (size == keys.length) grow();
            node = size++;
            keys[node] = key;
            insert(key, node);
        } else if (cost >= g[node]) {
            return false;
        }
        g[node] = cost;
        f[node] = cost + estimate;
        parent[node] = from;
        push(((long) f[node] << 32) | node);
        return true;
    }

    boolean isEmpty() { return heapSize == 0; }

    /**
     * Removes the queued node with the lowest estimate, skipping entries left behind when a node was
     * queued again more cheaply. Returns NONE once nothing is left.
     */
    int poll() {
        while (heapSize > 0) {
            long top = heap[0];
            heap[0] = heap[--heapSize];
            siftDown(0);
            int node = (int) top;
            if ((int) (top >>> 32) == f[node]) return node;
        }
        return NONE;
    }

    private int slot(long key) {
        long h = key * 0x9E3779B97F4A7C15L;
        return (int) (h >>> 40) & tableMask;
    }

    private void insert(long key, int node) {
        if (size * 2 > tableKeys.length) rehash();
        int slot = slot(key);
        while (tableNodes[slot] != NONE) slot = (slot + 1) & tableMask;
        tableKeys[slot] = key;
        tableNodes[slot] = node;
    }

    private void rehash() {
        long[] oldKeys = tableKeys;
        int[] oldNodes = tableNodes;
        tableKeys = new long[oldKeys.length * 2];
        tableNodes = new int[oldNodes.length * 2];
        Arrays.fill(tableNodes, NONE);
        tableMask = tableKeys.length - 1;
        for (int i = 0; i < oldKeys.length; i++) {
            if (oldNodes[i] == NONE) continue;
            int slot = slot(oldKeys[i]);
            while (tableNodes[slot] != NONE) slot = (slot + 1) & tableMask;
            tableKeys[slot] = oldKeys[i];
            tableNodes[slot] = oldNodes[i];
        }
    }

    private void grow() {
        int cap = keys.length * 2;
        keys = Arrays.copyOf(keys, cap);
        g = Arrays.copyOf(g, cap);
        f = Arrays.copyOf(f, cap);
        parent = Arrays.copyOf(parent, cap);
    }

    // Entries compare as plain longs: f is the high half, so the lowest f comes out first.
    private void push(long entry) {
        if (heapSize == heap.length) heap = Arrays.copyOf(heap, heap.length * 2);
        int i = heapSize++;
        while (i > 0) {
            int up = (i - 1) >> 1;
            if (heap[up] <= entry) break;
            heap[i] = heap[up];
            i = up;
        }
        heap[i] = entry;
    }

    private void siftDown(int i) {
        if (heapSize == 0) return;
        long entry = heap[i];
        while (true) {
            int child = 2 * i + 1;
            if (child >= heapSize) break;
            if (child + 1 < heapSize && heap[child + 1] < heap[child]) child++;
            if (heap[child] >= entry) break;
            heap[i] = heap[child];
            i = child;
        }
        heap[i] = entry;
    }
}

package com.routeplanner;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;

/**
 * Optional bridge to the Shortest Path plugin's cross-plugin API
 * (https://github.com/Skretzo/shortest-path/blob/master/docs/Cross-plugin-communication.md).
 *
 * Plugin Hub plugins can't share classes, so this talks to Shortest Path purely through
 * PluginMessage events: a "query" asks it to compute a path without drawing anything, and it
 * answers with a "result" carrying the same id. The answer may be posted from Shortest Path's
 * own pathfinding thread, so the handler only stashes it in a volatile field; everything else
 * here runs on the client thread via PathfinderOverlay.onGameTick.
 *
 * When Shortest Path isn't installed/enabled, or stops answering (e.g. an older version
 * without query support), isActive() goes false and the built-in A* is used instead.
 */
@Slf4j
@Singleton
public class ShortestPathBridge {

    private static final String NAMESPACE = "shortestpath";
    private static final String PLUGIN_NAME = "Shortest Path";
    private static final String ID_PREFIX = "routeplanner-";
    /** Pathfinder updates (every 2 game ticks) to wait for an answer before giving up. */
    private static final int RESPONSE_TIMEOUT_UPDATES = 4;
    /** Pathfinder updates to wait after a timeout before trying Shortest Path again (~2 min). */
    private static final int RETRY_AFTER_TIMEOUT_UPDATES = 100;

    /** An answer to one of our queries, already converted to plain route-planner types. */
    public static final class Result {
        final String id;
        final List<WorldPoint> path;
        final boolean reached;
        final boolean cancelled;
        /** Shortest Path's own description of each jump on the path (stairs, teleports...). */
        final List<com.routeplanner.transport.Transport> jumps;

        Result(String id, List<WorldPoint> path, boolean reached, boolean cancelled,
               List<com.routeplanner.transport.Transport> jumps) {
            this.id = id;
            this.path = path;
            this.reached = reached;
            this.cancelled = cancelled;
            this.jumps = jumps;
        }
    }

    private final EventBus eventBus;
    private final PluginManager pluginManager;
    private final RoutePlannerConfig config;

    private int nextId = 0;
    private String pendingId;
    private WorldPoint pendingTarget;
    private int updatesWaiting;
    private int timeoutCooldown;
    private volatile Result latest;

    @Inject
    public ShortestPathBridge(EventBus eventBus, PluginManager pluginManager, RoutePlannerConfig config) {
        this.eventBus = eventBus;
        this.pluginManager = pluginManager;
        this.config = config;
    }

    /** True when the user picked Shortest Path and it's installed, enabled and answering. */
    public boolean isActive() {
        return config.pathfinder() == PathfinderMode.SHORTEST_PATH
            && timeoutCooldown == 0
            && isShortestPathEnabled();
    }

    private boolean isShortestPathEnabled() {
        for (Plugin p : pluginManager.getPlugins()) {
            PluginDescriptor d = p.getClass().getAnnotation(PluginDescriptor.class);
            if (d != null && PLUGIN_NAME.equalsIgnoreCase(d.name())) {
                return pluginManager.isPluginEnabled(p);
            }
        }
        return false;
    }

    /**
     * Advance timers once per pathfinder update. Returns true if a pending query just timed out,
     * meaning the caller should rebuild with the built-in pathfinder right away.
     */
    public boolean tick() {
        if (timeoutCooldown > 0) timeoutCooldown--;
        if (pendingId == null) return false;
        if (++updatesWaiting <= RESPONSE_TIMEOUT_UPDATES) return false;
        log.info("Route Planner: Shortest Path didn't answer a path query, using built-in pathfinder");
        reset();
        timeoutCooldown = RETRY_AFTER_TIMEOUT_UPDATES;
        return true;
    }

    /** Ask Shortest Path for a path. A no-op if we're already waiting on the same target. */
    public void request(WorldPoint start, WorldPoint target) {
        if (pendingId != null && target.equals(pendingTarget)) return;
        pendingId = ID_PREFIX + (nextId++);
        pendingTarget = target;
        updatesWaiting = 0;
        latest = null;

        Map<String, Object> data = new HashMap<>();
        data.put("id", pendingId);
        data.put("start", start);
        data.put("target", target);
        if (config.recordTrace()) log.info("[RP-TRACE] SP ASK {} from {} to {}", pendingId, start, target);
        eventBus.post(new PluginMessage(NAMESPACE, "query", data));
    }

    /** Returns the answer to the pending query for this target once it has arrived, else null. */
    public Result takeResult(WorldPoint target) {
        Result r = latest;
        if (r == null || pendingId == null || !pendingId.equals(r.id)) return null;
        boolean forTarget = target.equals(pendingTarget);
        reset();
        return forTarget ? r : null;
    }

    /** Forget any in-flight query, so a late answer to it is ignored. */
    public void reset() {
        pendingId = null;
        pendingTarget = null;
        updatesWaiting = 0;
        latest = null;
    }

    /**
     * Shortest Path's "transports" list: per jump its origin, destination, objectInfo ("Climb-down
     * Ladder 2147", none for a teleport) and displayInfo ("Guardians of the Rift Minigame Teleport").
     */
    private static List<com.routeplanner.transport.Transport> jumps(Object raw) {
        List<com.routeplanner.transport.Transport> out = new ArrayList<>();
        if (!(raw instanceof List)) return out;
        for (Object o : (List<?>) raw) {
            if (!(o instanceof Map)) continue;
            Map<?, ?> m = (Map<?, ?>) o;
            if (!(m.get("origin") instanceof WorldPoint) || !(m.get("destination") instanceof WorldPoint)) continue;
            String object = m.get("objectInfo") instanceof String ? ((String) m.get("objectInfo")).trim() : "";
            String display = m.get("displayInfo") instanceof String ? ((String) m.get("displayInfo")).trim() : "";
            int objectId = -1;
            String action = object;
            java.util.regex.Matcher id = java.util.regex.Pattern.compile("^(.*\\S)\\s+(\\d+)$").matcher(object);
            if (id.matches()) {
                action = id.group(1);
                objectId = Integer.parseInt(id.group(2));
            }
            boolean teleport = object.isEmpty();
            String text = teleport ? (display.isEmpty() ? "Teleport" : "Teleport: " + display)
                : (action.isEmpty() ? display : action);
            out.add(new com.routeplanner.transport.Transport((WorldPoint) m.get("origin"),
                (WorldPoint) m.get("destination"), text.isEmpty() ? null : text, objectId, teleport));
        }
        return out;
    }

    @Subscribe
    public void onPluginMessage(PluginMessage message) {
        if (!NAMESPACE.equals(message.getNamespace()) || !"result".equals(message.getName())) return;
        Map<String, Object> data = message.getData();
        Object id = data.get("id");
        if (!(id instanceof String) || !((String) id).startsWith(ID_PREFIX)) return;

        List<WorldPoint> path = new ArrayList<>();
        Object rawPath = data.get("path");
        if (rawPath instanceof List) {
            for (Object o : (List<?>) rawPath) {
                if (o instanceof WorldPoint) path.add((WorldPoint) o);
            }
        }
        boolean reached = Boolean.TRUE.equals(data.get("reached"));
        boolean cancelled = "CANCELLED".equals(data.get("reason"));
        if (config.recordTrace()) {
            log.info("[RP-TRACE] SP REPLY {} reached={} reason={} tiles={} end={} closest={} jumps={} transports={}", id,
                reached, data.get("reason"), path.size(), path.isEmpty() ? null : path.get(path.size() - 1),
                data.get("closest"), PathfinderOverlay.describeJumps(path), data.get("transports"));
        }
        latest = new Result((String) id, path, reached, cancelled, jumps(data.get("transports")));
    }
}

package com.routeplanner;

import com.routeplanner.model.RouteStep;
import com.routeplanner.model.StepType;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.client.game.npcoverlay.HighlightedNpc;
import net.runelite.client.game.npcoverlay.NpcOverlayService;

import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.NpcDespawned;
import net.runelite.client.eventbus.Subscribe;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;
import java.util.function.Function;

@Singleton
public class SkillingNpcHighlighter {


    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final NpcOverlayService npcOverlayService;
    private final Function<NPC, HighlightedNpc> highlightFunction = this::shouldHighlight;

    @Inject
    public SkillingNpcHighlighter(Client client, RoutePlannerPlugin plugin,
                                   NpcOverlayService npcOverlayService) {
        this.client = client;
        this.plugin = plugin;
        this.npcOverlayService = npcOverlayService;
    }

    public void startUp() {
        npcOverlayService.registerHighlighter(highlightFunction);
    }

    public void rebuild() {
        npcOverlayService.rebuild();
    }

    public void shutDown() {
        npcOverlayService.unregisterHighlighter(highlightFunction);
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned event) {
        npcOverlayService.rebuild();
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event) {
        npcOverlayService.rebuild();
    }

    private HighlightedNpc shouldHighlight(NPC npc) {
        if (plugin.getActiveRoute() == null) return null;

        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || !step.isHighlightEnabled()) return null;

        String targetName;
        if (step.getSkillingTargetNpc() != null) {
            targetName = step.getSkillingTargetNpc();
        } else if (step.getNpcHighlight() != null) {
            targetName = step.getNpcHighlight();
        } else {
            return null;
        }
        if (targetName == null || targetName.trim().isEmpty()) return null;

        // Support multiple NPCs: comma-separated, with / for alternatives
        // e.g. "Rommik,Shop assistant/Shop keeper"
        String npcName = npc.getName();
        if (npcName == null) return null;
        boolean nameMatch = false;
        outer:
        for (String entry : targetName.split(",")) {
            for (String alt : entry.split("/")) {
                String t = alt.trim();
                if (npcName.equalsIgnoreCase(t)
                    || npcName.toLowerCase().startsWith(t.toLowerCase() + " ")
                    || npcName.toLowerCase().startsWith(t.toLowerCase() + "(")) {
                    nameMatch = true;
                    break outer;
                }
            }
        }
        if (!nameMatch) return null;

        // Only highlight NPCs within 30 tiles of the player; at sea, measured from the boat and out
        // as far as the client draws (sea creatures are further apart)
        net.runelite.api.coords.WorldPoint at = com.routeplanner.sailing.Sailing.position(client);
        if (at == null) return null;
        int range = 30;
        if (com.routeplanner.sailing.Sailing.isSailing(client) && client.getTopLevelWorldView() != null) {
            range = Math.max(range, client.getTopLevelWorldView().getScene().getDrawDistance());
        }
        if (npc.getWorldLocation().distanceTo(at) > range) return null;

        return HighlightedNpc.builder()
            .npc(npc)
            .highlightColor(plugin.getConfig().npcHighlightColor())
            .outline(true)
            .hull(false)
            .tile(false)
            .nameOnMinimap(true)
            .build();
    }
}

package com.routeplanner;

import com.routeplanner.util.RouteTextValidator;

import com.routeplanner.model.Route;
