    // Item name under the cursor when the menu was opened
    private String lastRightClickedShopItem = null;

    @Inject
    public TileMenuHandler(Client client, RoutePlannerPlugin plugin,
                           net.runelite.client.game.ItemManager itemManager) {
        this.client = client;
        this.plugin = plugin;
        this.itemManager = itemManager;
    }

    public void startUp() {
    }

    public void shutDown() {
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event) {
        if (plugin.getActiveRoute() == null) return;
        com.routeplanner.model.RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null) return;
        if (step.getSkillingTargetNpc() == null) return;
        // Only pickpocketing wants its option on left click; Talk-to and kill steps
        // highlight an NPC too but keep the game's own menu order.
        if (!"THIEVING".equalsIgnoreCase(step.getSkillingSkill())) return;

        net.runelite.api.MenuEntry entry = event.getMenuEntry();
        if (!(entry.getActor() instanceof NPC)) return;
        NPC npc = (NPC) entry.getActor();
        if (npc.getName() == null) return;

        String npcName = npc.getName();
        String targetName = step.getSkillingTargetNpc();
        boolean nameMatch = npcName.equalsIgnoreCase(targetName)
            || npcName.toLowerCase().startsWith(targetName.toLowerCase() + " ")
            || npcName.toLowerCase().startsWith(targetName.toLowerCase() + "(");
        if (!nameMatch) return;

        String option = entry.getOption();
        // Deprioritize everything except Pickpocket and Examine
        if (option.equalsIgnoreCase("Pickpocket")) {
            entry.setDeprioritized(false);
        } else if (!option.equalsIgnoreCase("Examine") && !option.equalsIgnoreCase("Cancel")) {
            entry.setDeprioritized(true);
        }
    }

    @Subscribe
    public void onMenuOpened(MenuOpened event) {
        if (plugin.getActiveRoute() == null) return;

        boolean hasWalkHere = false;
        for (MenuEntry entry : event.getMenuEntries()) {
            if (entry.getOption().equals("Walk here")) hasWalkHere = true;
        }

        if (hasWalkHere && client.isKeyPressed(KeyCode.KC_SHIFT)) {
            client.createMenuEntry(-1)
                .setOption(ADD_LOCATION_STEP)
                .setTarget("<col=00ff00>" + MENU_TARGET + "</col>")
                .setType(MenuAction.RUNELITE)
                .setDeprioritized(false);
            if (plugin.getActiveRoute() != null && plugin.getActiveRoute().getActiveStep() != null) {
                client.createMenuEntry(-1)
                    .setOption(SET_TRANSITION_POINT)
                    .setTarget("<col=00ff00>" + MENU_TARGET + "</col>")
                    .setType(MenuAction.RUNELITE)
                    .setDeprioritized(false);
                // Also offer object ID grab if a game object is under the cursor
                net.runelite.api.Tile tile = client.getTopLevelWorldView().getSelectedSceneTile();
                if (tile != null) {
                    for (net.runelite.api.GameObject obj : tile.getGameObjects()) {
                        if (obj != null) {
                            client.createMenuEntry(-1)
                                .setOption(SET_TRANSITION_OBJECT + " (ID:" + obj.getId() + ")")
                                .setTarget("<col=00ff00>" + MENU_TARGET + "</col>")
                                .setType(MenuAction.RUNELITE)
                                .setDeprioritized(false);
                            break;
                        }
                    }
                }
            }
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        String opt = event.getMenuOption();

        // Add to Item Step uses the item name as target, not MENU_TARGET
        if (opt.equals(ADD_TO_ITEM_STEP)) {
            if (lastRightClickedShopItem != null
                    && !pendingShopItems.contains(lastRightClickedShopItem)) {
                pendingShopItems.add(lastRightClickedShopItem);
                client.addChatMessage(net.runelite.api.ChatMessageType.GAMEMESSAGE, "",
                    "<col=00ff00>Route Planner:</col> added " + lastRightClickedShopItem
                    + " (" + pendingShopItems.size() + " selected)", null);
            }
            event.consume();
            return;
        }

        if (!event.getMenuTarget().contains(MENU_TARGET)) return;

        if (opt.startsWith(SET_TRANSITION_OBJECT)) {
            com.routeplanner.model.RouteStep activeStep = plugin.getActiveRoute() == null ? null
                : plugin.getActiveRoute().getActiveStep();
            if (activeStep == null) return;
            net.runelite.api.Tile tile = client.getTopLevelWorldView().getSelectedSceneTile();
            if (tile == null) return;
            for (net.runelite.api.GameObject obj : tile.getGameObjects()) {
                if (obj != null) {
                    activeStep.setTransitionObjectId(obj.getId());
                    plugin.saveRoutes();
                    client.addChatMessage(net.runelite.api.ChatMessageType.GAMEMESSAGE, "",
                        "<col=00ff00>Route Planner:</col> transition object ID set to " + obj.getId(), null);
                    log.info("Transition object ID set to {}", obj.getId());
                    break;
                }
            }
        } else if (opt.equals(SET_TRANSITION_POINT)) {
            net.runelite.api.Tile selectedTile = client.getTopLevelWorldView().getSelectedSceneTile();
            if (selectedTile == null) return;
            com.routeplanner.model.RouteStep activeStep = plugin.getActiveRoute() == null ? null
                : plugin.getActiveRoute().getActiveStep();
            if (activeStep == null) return;
            net.runelite.api.coords.WorldPoint raw = selectedTile.getWorldLocation();
            activeStep.setTransitionPoint(raw);
            plugin.saveRoutes();
            client.addChatMessage(net.runelite.api.ChatMessageType.GAMEMESSAGE, "",
                "<col=00ff00>Route Planner:</col> transition point set to " + raw, null);
            log.info("Transition point set to {}", raw);
        } else if (opt.equals(ADD_LOCATION_STEP)) {
            net.runelite.api.Tile selectedTile = client.getTopLevelWorldView().getSelectedSceneTile();
            if (selectedTile == null) {
                log.warn("Route Planner: no selected tile found");
                return;
            }
            promptAddLocationStep(selectedTile.getWorldLocation());
        } else if (opt.startsWith(CREATE_ITEM_STEP)) {
            createItemStepFromSelection();
            event.consume();
        } else if (opt.equals(CLEAR_SELECTION)) {
            pendingShopItems.clear();
            client.addChatMessage(net.runelite.api.ChatMessageType.GAMEMESSAGE, "",
                "<col=ff5555>Route Planner:</col> item selection cleared", null);
            event.consume();
        }
    }

    private void createItemStepFromSelection() {
        if (pendingShopItems.isEmpty() || plugin.getActiveRoute() == null) return;
        final java.util.List<String> snapshot = new java.util.ArrayList<>(pendingShopItems);
        pendingShopItems.clear();
        SwingUtilities.invokeLater(() -> {
            String itemList = String.join(", ", snapshot);
            String firstName = snapshot.get(0);
            String stepName = "Buy: " + firstName
                + (snapshot.size() > 1 ? " +" + (snapshot.size() - 1) + " more" : "");
            RouteStep step = new RouteStep(stepName, StepType.ITEM, null, -1);
            step.setItemList(itemList);
            step.setItemMode("SHOP");
            plugin.addStep(plugin.getActiveRoute(), step);
            log.info("Created shop item step with {} items: {}", snapshot.size(), itemList);
        });
    }

    private void promptAddLocationStep(WorldPoint tile) {
        SwingUtilities.invokeLater(() -> {
            if (plugin.getActiveRoute() == null) {
                JOptionPane.showMessageDialog(null, "Select or create a route first.");
                return;
            }
            new QuickStepDialog(plugin, plugin.getActiveRoute(), null, tile).setVisible(true);
            log.info("Opened step editor seeded at {}", tile);
        });
    }
}

package com.routeplanner;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;

/**
 * Loads transport edges (origin -> destination) from the bundled Shortest Path
 * TSV datasets. Only rows with BOTH a valid origin and destination are kept,
 * which naturally includes doors, stairs, dungeon entrances, agility shortcuts,
 * boats, ships and minecarts, and skips "from anywhere" teleports / hub types.
 */
@Slf4j
public class TransportLoader {

    // Files that contain simple origin->destination edges
    private static final String[] FILES = {
        "transports.tsv",
        "agility_shortcuts.tsv",
        "boats.tsv",
        "ships.tsv",
        "charter_ships.tsv",
        "minecarts.tsv"
    };

    /** Files whose edges travel between places (ships, minecarts) rather than through a door or up stairs. */
    private static final Set<String> TRAVEL_FILES = new HashSet<>(Arrays.asList(
        "boats.tsv", "ships.tsv", "charter_ships.tsv", "minecarts.tsv"));
    /** Origins whose edges are all journeys from TRAVEL_FILES, mapped to those destinations. */
    private static final Map<WorldPoint, Set<WorldPoint>> TRAVEL = new HashMap<>();

    /** Whether the edge from {@code origin} to {@code destination} is a ship or minecart journey. */
    public static boolean isTravel(WorldPoint origin, WorldPoint destination) {
        Set<WorldPoint> dests = TRAVEL.get(origin);
        return dests != null && dests.contains(destination);
    }

    /** Every loaded edge with its menu text and object id, for highlighting the stairs to use. */
    private static final Map<WorldPoint, List<com.routeplanner.transport.Transport>> DETAILS = new HashMap<>();

    /** The transport going from {@code origin} to {@code destination}, or null if none is known. */
    public static com.routeplanner.transport.Transport find(WorldPoint origin, WorldPoint destination) {
        List<com.routeplanner.transport.Transport> list = DETAILS.get(origin);
        if (list == null) return null;
        for (com.routeplanner.transport.Transport t : list) if (t.destination.equals(destination)) return t;
        return null;
    }

    public static Map<WorldPoint, List<WorldPoint>> load() {
        Map<WorldPoint, List<WorldPoint>> edges = new HashMap<>();
        int total = 0;
        for (String f : FILES) {
            int count = 0;
            try (InputStream is = TransportLoader.class.getResourceAsStream(
                    "/com/routeplanner/transports/" + f)) {
                if (is == null) { log.warn("Transport file missing: {}", f); continue; }
                BufferedReader br = new BufferedReader(new InputStreamReader(is));
                String line;
                while ((line = br.readLine()) != null) {
                    if (line.isEmpty() || line.startsWith("#")) continue;
                    String[] cols = line.split("\t");
                    if (cols.length < 2) continue;
                    WorldPoint origin = parsePoint(cols[0]);
                    WorldPoint dest = parsePoint(cols[1]);
                    if (origin == null || dest == null) continue;
                    edges.computeIfAbsent(origin, k -> new ArrayList<>()).add(dest);
                    if (TRAVEL_FILES.contains(f)) TRAVEL.computeIfAbsent(origin, k -> new HashSet<>()).add(dest);
                    DETAILS.computeIfAbsent(origin, k -> new ArrayList<>()).add(detail(origin, dest, cols.length > 2 ? cols[2] : ""));
                    count++;
                }
            } catch (Exception e) {
                log.warn("Failed to load transport file {}: {}", f, e.toString());
            }
            log.info("TransportLoader: {} edges from {}", count, f);
            total += count;
        }
        log.info("TransportLoader: {} total edges across {} origins", total, edges.size());
        return edges;
    }

    /** "Climb-up Staircase 16671" -> action "Climb-up Staircase", object 16671. */
    private static com.routeplanner.transport.Transport detail(WorldPoint origin, WorldPoint dest, String col) {
        String text = col.trim();
        int id = -1;
        int sp = text.lastIndexOf(' ');
        if (sp > 0) {
            try {
                id = Integer.parseInt(text.substring(sp + 1));
                text = text.substring(0, sp);
            } catch (NumberFormatException ignored) {}
        }
        return new com.routeplanner.transport.Transport(origin, dest, text.isEmpty() ? null : text, id);
    }

    private static WorldPoint parsePoint(String s) {
        if (s == null) return null;
        s = s.trim();
        if (s.isEmpty()) return null;
        String[] parts = s.split("\\s+");
        if (parts.length < 3) return null;
        try {
            return new WorldPoint(Integer.parseInt(parts[0]),
                Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));
        } catch (NumberFormatException e) {
            return null;
        }
    }
}

package com.routeplanner;

import java.io.IOException;
import java.io.InputStream;
import java.util.BitSet;
import java.util.HashMap;
import java.util.Map;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

/**
 * Reads collision-map.zip in the format of Skretzo/shortest-path's SplitFlagMap.
 *
 * Index formula:
 *   index = (plane * 64 * 64 + (y - minY) * 64 + (x - minX)) * 4 + flag
 *
 * Flags: 0 = can travel NORTH from tile, 1 = can travel EAST from tile, 2 and 3 = the north and
 * east edges are walls or doors (unused here). South is stored as North of the tile below. West is
 * stored as East of the tile to the left. A set bit means movement IS ALLOWED (not blocked).
 */
public class WorldCollisionMap {

    public static final int NORTH = 0;
    public static final int EAST  = 1;

    private static final int REGION_SIZE = 64;
    private static final int FLAG_COUNT = 4;
    private static final int BITS_PER_PLANE = REGION_SIZE * REGION_SIZE * FLAG_COUNT;

    private static class RegionData {
        final int minX;
        final int minY;
        final BitSet flags;
        final byte planeCount;

        RegionData(int minX, int minY, byte[] data) {
            this.minX = minX;
            this.minY = minY;
            this.flags = BitSet.valueOf(data);
            int size = flags.size();
            this.planeCount = (byte) ((size + BITS_PER_PLANE - 1) / BITS_PER_PLANE);
        }

        boolean get(int x, int y, int plane, int direction) {
            if (x < minX || x >= minX + REGION_SIZE) return false;
            if (y < minY || y >= minY + REGION_SIZE) return false;
            if (plane < 0 || planeCount <= 0) return false;
            if (direction < 0 || direction >= 2) return false;
            int idx = (plane * REGION_SIZE * REGION_SIZE
                + (y - minY) * REGION_SIZE
                + (x - minX)) * FLAG_COUNT + direction;
            return flags.get(idx);
        }
    }

    // key = regionX | (regionY << 16)
    private final Map<Integer, RegionData> regions = new HashMap<>();

    public WorldCollisionMap(InputStream zipStream) throws IOException {
        try (ZipInputStream zis = new ZipInputStream(zipStream)) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry()) != null) {
                String[] parts = entry.getName().split("_");
                int regionX = Integer.parseInt(parts[0]);
                int regionY = Integer.parseInt(parts[1]);
                int key = regionX | (regionY << 16);
                int minX = regionX * REGION_SIZE;
                int minY = regionY * REGION_SIZE;
                byte[] data = zis.readAllBytes();
                regions.put(key, new RegionData(minX, minY, data));
                zis.closeEntry();
            }
        }
    }

    /**
     * Returns true if movement NORTH from (x,y,plane) is allowed.
     */
    public boolean canMoveNorth(int x, int y, int plane) {
        return getFlag(x, y, plane, NORTH);
    }

    /**
     * Returns true if movement SOUTH from (x,y,plane) is allowed.
     * South from (x,y) = North from (x, y-1).
     */
    public boolean canMoveSouth(int x, int y, int plane) {
        return getFlag(x, y - 1, plane, NORTH);
    }

    /**
     * Returns true if movement EAST from (x,y,plane) is allowed.
     */
    public boolean canMoveEast(int x, int y, int plane) {
        return getFlag(x, y, plane, EAST);
    }

    /**
     * Returns true if movement WEST from (x,y,plane) is allowed.
     * West from (x,y) = East from (x-1, y).
     */
    public boolean canMoveWest(int x, int y, int plane) {
        return getFlag(x - 1, y, plane, EAST);
    }

    private boolean getFlag(int x, int y, int plane, int direction) {
        int regionX = x / REGION_SIZE;
        int regionY = y / REGION_SIZE;
        int key = regionX | (regionY << 16);
        RegionData region = regions.get(key);
        if (region == null) return true; // unknown = assume walkable
        return region.get(x, y, plane, direction);
    }

    public boolean isLoaded() {
        return !regions.isEmpty();
    }
}

package com.routeplanner;

import com.routeplanner.model.RouteStep;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.worldmap.WorldMapOverlay;

import javax.inject.Inject;
import java.awt.*;
import java.awt.geom.Ellipse2D;

public class WorldMapPathOverlay extends Overlay {

    // World map interface ID and map view child ID
    private static final int WORLD_MAP_INTERFACE = 595;
    private static final int WORLD_MAP_CHILD = 7;

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final WorldMapOverlay worldMapOverlay;
    private final PathfinderOverlay pathfinderOverlay;

    @Inject
    public WorldMapPathOverlay(Client client, RoutePlannerPlugin plugin,
                                WorldMapOverlay worldMapOverlay,
                                PathfinderOverlay pathfinderOverlay) {
        this.client = client;
        this.plugin = plugin;
        this.worldMapOverlay = worldMapOverlay;
        this.pathfinderOverlay = pathfinderOverlay;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null) return null;
        // Until the player boards (Sailing), the dock is where they're headed.
        WorldPoint target = plugin.getPathfinderOverlay().isBoardingPending(step) ? step.getBoardPoint() : step.getWorldPoint();
        if (target == null) return null;

        // Check world map is open
        Widget mapWidget = client.getWidget(WORLD_MAP_INTERFACE, WORLD_MAP_CHILD);
        if (mapWidget == null || mapWidget.isHidden()) return null;

        Rectangle mapBounds = mapWidget.getBounds();
        if (mapBounds == null) return null;

        WorldPoint player = com.routeplanner.sailing.Sailing.position(client);
        if (player == null) return null;

        graphics.setColor(new Color(255, 140, 0, 200));
        float[] dash = {6f, 4f};
        graphics.setStroke(new BasicStroke(2, BasicStroke.CAP_ROUND,
            BasicStroke.JOIN_ROUND, 1f, dash, 0f));
        Shape oldClip = graphics.getClip();
        graphics.clip(mapBounds);
        // The route the pathfinder worked out (round coasts at sea, along roads on land); a straight
        // line to the destination until there is one
        if (!drawRoute(graphics, pathfinderOverlay.getCachedPath())) {
            Point playerMapPoint = worldMapOverlay.mapWorldPointToGraphicsPoint(player);
            Point targetMapPoint = worldMapOverlay.mapWorldPointToGraphicsPoint(target);
            if (playerMapPoint != null && targetMapPoint != null) {
                graphics.drawLine(playerMapPoint.getX(), playerMapPoint.getY(),
                                  targetMapPoint.getX(), targetMapPoint.getY());
            }
        }
        graphics.setClip(oldClip);

        // Draw destination dot
        Point destPoint = worldMapOverlay.mapWorldPointToGraphicsPoint(target);
        if (destPoint != null && mapBounds.contains(destPoint.getX(), destPoint.getY())) {
            int size = 10;
            int x = destPoint.getX() - size / 2;
            int y = destPoint.getY() - size / 2;

            graphics.setColor(Color.BLACK);
            graphics.fill(new Ellipse2D.Double(x - 1, y - 1, size + 2, size + 2));
            graphics.setColor(new Color(255, 140, 0));
            graphics.fill(new Ellipse2D.Double(x, y, size, size));

            graphics.setColor(Color.WHITE);
            graphics.setFont(new Font("Arial", Font.BOLD, 11));
            graphics.drawString(step.getName(), destPoint.getX() + 8, destPoint.getY() + 4);
        }

        // Draw player dot
        Point playerPoint = worldMapOverlay.mapWorldPointToGraphicsPoint(player);
        if (playerPoint != null && mapBounds.contains(playerPoint.getX(), playerPoint.getY())) {
            int size = 8;
            int x = playerPoint.getX() - size / 2;
            int y = playerPoint.getY() - size / 2;
            graphics.setColor(Color.BLACK);
            graphics.fill(new Ellipse2D.Double(x - 1, y - 1, size + 2, size + 2));
            graphics.setColor(Color.WHITE);
            graphics.fill(new Ellipse2D.Double(x, y, size, size));
        }

        return null;
    }

    /**
     * Draws the path as one line on the map, broken where it jumps (stairs, a ship, a cave mouth) or goes
     * off the map view. Returns false if there's no path to draw.
     */
    private boolean drawRoute(Graphics2D graphics, java.util.List<WorldPoint> path) {
        if (path == null || path.size() < 2) return false;
        java.awt.geom.Path2D.Float line = new java.awt.geom.Path2D.Float();
        boolean drawing = false;
        WorldPoint prev = null;
        for (WorldPoint wp : path) {
            Point p = worldMapOverlay.mapWorldPointToGraphicsPoint(wp);
            boolean jump = prev != null && (prev.getPlane() != wp.getPlane()
                || Math.max(Math.abs(prev.getX() - wp.getX()), Math.abs(prev.getY() - wp.getY())) > MAX_STEP_TILES);
            if (p == null || jump) drawing = false;
            prev = wp;
            if (p == null) continue;
            if (drawing) line.lineTo(p.getX(), p.getY());
            else line.moveTo(p.getX(), p.getY());
            drawing = true;
        }
        graphics.draw(line);
        return true;
    }

    /** Path points further apart than this are a jump (stairs, a ship, a cave mouth), not a line. */
    private static final int MAX_STEP_TILES = 5;
}

