package com.routeplanner.agility;

import lombok.Data;
import net.runelite.api.coords.WorldPoint;

@Data
public class AgilityObstacle {
    private final String name;
    private final int[] objectIds;
    private final WorldPoint location; // nullable - used only as hint

    public AgilityObstacle(String name, WorldPoint location, int... objectIds) {
        this.name = name;
        this.location = location;
        this.objectIds = objectIds;
    }

    public boolean matchesId(int id) {
        for (int oid : objectIds) {
            if (oid == id) return true;
        }
        return false;
    }
}

package com.routeplanner.bank;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.SpritePixels;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.bank.BankSearch;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * The Route Planner tab in the bank: a game-style square button with the plugin's icon, at the
 * top right of the bank like Quest Helper's. Clicking it shows only the current step's items in
 * the bank grid and puts the step in the bank title; any other tab, "View all items" or a
 * search turns it off, the same as switching between real bank tabs.
 */
@Slf4j
@Singleton
public class BankFilterButton {

    private static final String TAB_NAME = "Route Planner";
    private static final int BANK_GROUP_ID = 12;

    // The game's own small square button, as used by its bank buttons (and Quest Helper's tab)
    private static final int BUTTON_SPRITE = 195;
    private static final int BUTTON_SPRITE_SELECTED = 196;
    private static final int TAB_SOUND = 2266;
    /** Our icon, registered under an id the game doesn't use. */
    private static final int ICON_SPRITE = -21470;

    // Placement: Quest Helper's tab sits at x=408; ours goes just left of it, or there if it's absent.
    private static final int SIZE = 25;
    private static final int QUEST_HELPER_X = 408;
    private static final int Y = 5;

    // The bank grid (same spacing as the game's own layout)
    private static final int COLUMNS = 8;
    private static final int ITEM_SPACING_X = 48;
    private static final int ITEM_SPACING_Y = 36;
    private static final int ITEM_ROW_START = 51;

    @Inject private Client client;
    @Inject private RoutePlannerPlugin plugin;
    @Inject private BankItemManager bankItemManager;
    @Inject private BankSearch bankSearch;
    @Inject private net.runelite.client.game.ItemManager itemManager;

    private boolean filterActive;
    private RouteStep filteredStep;
    private Widget background;
    private Widget icon;
    private boolean iconRegistered;
    private BufferedImage iconSource; // the plugin icon the sprite was made from
    /** Each grid widget's x, y and hidden flag before we filtered, to put back exactly. */
    private final java.util.Map<Integer, int[]> saved = new java.util.HashMap<>();
    private String savedTitle;

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event) {
        if (event.getGroupId() == BANK_GROUP_ID) {
            background = null;
            icon = null;
            filterActive = false;
            filteredStep = null;
        }
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event) {
        if (event.getGroupId() == BANK_GROUP_ID) {
            background = null;
            icon = null;
            filterActive = false;
            filteredStep = null;
        }
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event) {
        if (event.getScriptId() != ScriptID.BANKMAIN_BUILD) return;
        saved.clear(); // the bank just laid itself out again; that's the new state to come back to
        savedTitle = null;
        createTab();
        if (filterActive) applyItemFilter();
    }

    /** The step changed while the bank is open: show or hide the tab, and drop a stale filter. */
    @Subscribe
    public void onGameTick(GameTick tick) {
        if (background == null) return;
        RouteStep step = stepWithItems();
        boolean show = step != null;
        if (background.isHidden() == show) {
            background.setHidden(!show);
            if (icon != null) icon.setHidden(!show);
        }
        if (filterActive && step != filteredStep) {
            if (step == null) turnOff(true);
            else applyItemFilter();
        }
    }

    /** Another tab, "View all items" or the search box replaces our view, like any bank tab. */
    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        if (!filterActive) return;
        String option = event.getMenuOption();
        if (option == null || isOurTab(event)) return;
        if (option.startsWith("View tab") || option.startsWith("View tag tab") || option.equals("View all items")
            || option.startsWith("Potion store") || option.equals("Search")) {
            turnOff(false);
        }
    }

    /** Our own tab's click (matched by widget, since the menu text isn't reliable to compare). */
    private boolean isOurTab(MenuOptionClicked event) {
        if (background != null && event.getParam1() == InterfaceID.Bankmain.UNIVERSE
            && event.getParam0() == background.getIndex()) return true;
        String target = event.getMenuTarget();
        return target != null && net.runelite.client.util.Text.removeTags(target).contains(TAB_NAME);
    }

    private RouteStep stepWithItems() {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        return step != null && step.getItemList() != null && !step.getItemList().trim().isEmpty() ? step : null;
    }

    private void createTab() {
        Widget parent = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
        if (parent == null || parent.isHidden()) return;
        int x = questHelperTabPresent(parent) ? QUEST_HELPER_X - SIZE - 3 : QUEST_HELPER_X;
        registerIcon();
        if (background != null && stillThere(parent)) {
            // Quest Helper may have added its tab after ours: keep to its left
            if (background.getOriginalX() != x) {
                background.setOriginalX(x);
                background.revalidate();
                if (icon != null) { icon.setOriginalX(x + 3); icon.revalidate(); }
            }
            refreshSprites();
            return;
        }
        registerIcon();

        background = parent.createChild(-1, WidgetType.GRAPHIC);
        background.setOriginalWidth(SIZE);
        background.setOriginalHeight(SIZE);
        background.setOriginalX(x);
        background.setOriginalY(Y);
        background.setSpriteId(filterActive ? BUTTON_SPRITE_SELECTED : BUTTON_SPRITE);
        background.setAction(0, "View tab");
        background.setName("<col=ff9040>" + TAB_NAME + "</col>");
        background.setHasListener(true);
        background.setOnOpListener((JavaScriptCallback) e -> toggle());
        background.revalidate();

        icon = parent.createChild(-1, WidgetType.GRAPHIC);
        icon.setOriginalWidth(SIZE - 6);
        icon.setOriginalHeight(SIZE - 6);
        icon.setOriginalX(x + 3);
        icon.setOriginalY(Y + 3);
        icon.setSpriteId(ICON_SPRITE);
        icon.revalidate();

        boolean show = stepWithItems() != null;
        background.setHidden(!show);
        icon.setHidden(!show);
    }

    /** The bank can rebuild its interface and drop children we added; check ours survived. */
    private boolean stillThere(Widget parent) {
        Widget[] kids = parent.getDynamicChildren();
        if (kids == null) return false;
        for (Widget w : kids) {
            if (w != null && w.getName() != null && w.getName().contains(TAB_NAME)) return true;
        }
        return false;
    }

    /** Quest Helper adds a tab named "quest-helper" at the same spot; make room for it. */
    private static boolean questHelperTabPresent(Widget parent) {
        Widget[] kids = parent.getDynamicChildren();
        if (kids == null) return false;
        for (Widget w : kids) {
            if (w != null && w.getName() != null && w.getName().contains("quest-helper")) return true;
        }
        return false;
    }

    /** The plugin's icon as a game sprite, so it sits on the button like the game's own icons. */
    private void registerIcon() {
        BufferedImage img = plugin.getRouteIcon();
        if (img == null) img = ImageUtil.loadImageResource(RoutePlannerPlugin.class, "route_icon.png");
        if (iconRegistered && img == iconSource) return; // still current (re-made once the orb loads)
        iconSource = img;
        try {
            BufferedImage scaled = ImageUtil.resizeImage(img, SIZE - 6, SIZE - 6);
            SpritePixels sprite = ImageUtil.getImageSpritePixels(scaled, client);
            client.getSpriteOverrides().put(ICON_SPRITE, sprite);
            iconRegistered = true;
        } catch (RuntimeException e) {
            log.warn("Route Planner: couldn't load the bank tab icon", e);
        }
    }

    private void refreshSprites() {
        if (background != null) {
            background.setSpriteId(filterActive ? BUTTON_SPRITE_SELECTED : BUTTON_SPRITE);
            background.revalidate();
        }
    }

    private void toggle() {
        log.debug("Route Planner bank tab clicked, filter was {}", filterActive ? "on" : "off");
        client.playSoundEffect(TAB_SOUND);
        if (filterActive) {
            turnOff(true);
        } else {
            filterActive = true;
            refreshSprites();
            applyItemFilter();
        }
    }

    /** @param resetBank put the normal bank view back (not needed when another tab takes over). */
    private void turnOff(boolean resetBank) {
        filterActive = false;
        filteredStep = null;
        refreshSprites();
        restore();
        if (resetBank) bankSearch.reset(true);
    }

    /** Put every grid item and the title back the way the bank had them. */
    private void restore() {
        Widget itemContainer = client.getWidget(InterfaceID.Bankmain.ITEMS);
        if (itemContainer != null && !saved.isEmpty()) {
            Widget[] items = itemContainer.getDynamicChildren();
            if (items != null) {
                for (Widget item : items) {
                    if (item == null) continue;
                    int[] s = saved.get(item.getIndex());
                    if (s == null) continue;
                    item.setOriginalX(s[0]);
                    item.setOriginalY(s[1]);
                    item.setHidden(s[2] == 1);
                    item.revalidate();
                }
            }
            itemContainer.revalidateScroll();
        }
        Widget title = client.getWidget(InterfaceID.Bankmain.TITLE);
        if (title != null && savedTitle != null) title.setText(savedTitle);
        saved.clear();
        savedTitle = null;
        log.debug("Route Planner bank tab: bank view restored");
    }

    private void applyItemFilter() {
        RouteStep step = stepWithItems();
        if (step == null) return;
        filteredStep = step;

        Set<String> requiredNames = new HashSet<>();
        for (List<String> group : bankItemManager.parseItemList(step.getItemList())) {
            for (String alt : group) requiredNames.add(bankItemManager.parseItemName(alt).toLowerCase().trim());
        }

        Widget itemContainer = client.getWidget(InterfaceID.Bankmain.ITEMS);
        if (itemContainer == null) return;
        Widget[] items = itemContainer.getDynamicChildren();
        if (items == null) return;

        if (saved.isEmpty()) {
            for (Widget item : items) {
                if (item == null) continue;
                saved.put(item.getIndex(), new int[]{item.getOriginalX(), item.getOriginalY(), item.isHidden() ? 1 : 0});
            }
            Widget title = client.getWidget(InterfaceID.Bankmain.TITLE);
            if (title != null) savedTitle = title.getText();
        }

        // Keep this step's items, in bank order; hide everything else
        List<Widget> keep = new ArrayList<>();
        for (Widget item : items) {
            if (item == null) continue;
            int[] before = saved.get(item.getIndex());
            boolean wasHidden = before != null ? before[2] == 1 : item.isHidden();
            if (item.getItemId() <= 0 || wasHidden) { item.setHidden(true); continue; }
            String name = itemManager.getItemComposition(item.getItemId()).getName();
            boolean wanted = name != null && requiredNames.stream().anyMatch(r -> BankItemManager.nameMatches(r, name));
            if (wanted) keep.add(item);
            else item.setHidden(true);
        }
        for (int i = 0; i < keep.size(); i++) {
            Widget item = keep.get(i);
            item.setHidden(false);
            item.setOriginalX(ITEM_ROW_START + (i % COLUMNS) * ITEM_SPACING_X);
            item.setOriginalY((i / COLUMNS) * ITEM_SPACING_Y);
            item.revalidate();
        }
        int rows = (keep.size() + COLUMNS - 1) / COLUMNS;
        itemContainer.setScrollY(0);
        itemContainer.setScrollHeight(Math.max(itemContainer.getHeight(), rows * ITEM_SPACING_Y));
        itemContainer.revalidateScroll();

        Widget title = client.getWidget(InterfaceID.Bankmain.TITLE);
        if (title != null) title.setText("Route: " + step.getName());
    }

    public void reset() {
        if (filterActive) {
            restore();
            bankSearch.reset(true);
        }
        filterActive = false;
        filteredStep = null;
        background = null;
        icon = null;
        if (iconRegistered) {
            client.getSpriteOverrides().remove(ICON_SPRITE);
            iconRegistered = false;
        }
    }
}

package com.routeplanner.bank;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;

@Slf4j
@Singleton
public class BankItemManager {

    @Inject private Client client;
    @Inject private ItemManager itemManager;

    // Parse a quantity prefix like "1k", "1m", "1mil", "500k", "2.5m" from item name
    // Returns [quantity, itemName] or [1, fullString] if no quantity found
    private long suffixMultiply(double num, String suffix) {
        if (suffix == null) return (long) num;
        switch (suffix.toLowerCase()) {
            case "k": return (long)(num * 1_000);
            case "m": case "mil": return (long)(num * 1_000_000);
            case "b": return (long)(num * 1_000_000_000);
            default: return (long) num;
        }
    }

    /** Item-list names ending in "(*)" mean any charge: "Amulet of glory(*)" matches glory(1)-(6). */
    public static final String ANY_CHARGE = "(*)";

    /** True when an item-list name (without quantity) refers to the actual item name. */
    public static boolean nameMatches(String listName, String actual) {
        if (listName == null || actual == null) return false;
        String want = listName.trim().toLowerCase();
        String have = actual.trim().toLowerCase();
        if (!want.endsWith(ANY_CHARGE)) return want.equals(have);
        String base = want.substring(0, want.length() - ANY_CHARGE.length()).trim();
        return have.startsWith(base) && have.substring(base.length()).trim().matches("\\(\\d+\\)");
    }

    /** How many of an item-list name are in a name -> quantity map, summing every charge for "(*)". */
    public static long countOf(Map<String, Long> qtys, String listName) {
        if (!listName.trim().endsWith(ANY_CHARGE)) return qtys.getOrDefault(listName.trim().toLowerCase(), 0L);
        long total = 0;
        for (Map.Entry<String, Long> e : qtys.entrySet()) {
            if (nameMatches(listName, e.getKey())) total += e.getValue();
        }
        return total;
    }

    private static boolean anyMatches(Set<String> names, String listName) {
        for (String n : names) if (nameMatches(listName, n)) return true;
        return false;
    }

    public String parseItemName(String input) {
        input = input.trim();
        java.util.regex.Matcher m = java.util.regex.Pattern
            .compile("^[\\d.]+\\s*(?:k|m|mil|b)?\\s+(.+)$", java.util.regex.Pattern.CASE_INSENSITIVE)
            .matcher(input);
        if (m.matches()) return m.group(1).trim();
        return input;
    }

    public long parseQuantityValue(String input) {
        input = input.trim();
        java.util.regex.Matcher m = java.util.regex.Pattern
            .compile("^([\\d.]+)\\s*(k|m|mil|b)?\\s+.+$", java.util.regex.Pattern.CASE_INSENSITIVE)
            .matcher(input);
        if (m.matches()) {
            try {
                double num = Double.parseDouble(m.group(1));
                String suffix = m.group(2) == null ? "" : m.group(2).toLowerCase();
                return suffixMultiply(num, suffix);
            } catch (Exception ignored) {}
        }
        return 1;
    }

    // Parse item list string into groups (each group is a list of alternatives)
    // e.g. "Spade,1mil Coins/Platinum token" ->
    //      [["Spade"], ["1mil Coins", "Platinum token"]]
    public List<List<String>> parseItemList(String itemListStr) {
        if (itemListStr == null || itemListStr.trim().isEmpty()) return Collections.emptyList();
        List<List<String>> groups = new ArrayList<>();
        for (String group : itemListStr.split(",")) {
            group = group.trim();
            if (group.isEmpty()) continue;
            List<String> alternatives = new ArrayList<>();
            for (String alt : group.split("/")) {
                alt = alt.trim();
                if (!alt.isEmpty()) alternatives.add(alt);
            }
            if (!alternatives.isEmpty()) groups.add(alternatives);
        }
        return groups;
    }

    // Check if player has all required items in inventory with quantity
    public boolean hasAllItems(String itemListStr) {
        List<List<String>> groups = parseItemList(itemListStr);
        if (groups.isEmpty()) return true;

        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        if (inventory == null) return false;

        // Build map of item name -> total quantity in inventory
        Map<String, Long> inventoryQtys = new HashMap<>();
        for (Item item : inventory.getItems()) {
            if (item.getId() <= 0) continue;
            String name = itemManager.getItemComposition(item.getId()).getName();
            if (name != null) {
                inventoryQtys.merge(name.toLowerCase(), (long) item.getQuantity(), Long::sum);
            }
        }

        for (List<String> group : groups) {
            boolean groupSatisfied = false;
            for (String alt : group) {
                String itemName = parseItemName(alt).toLowerCase();
                long required = parseQuantityValue(alt);
                long have = countOf(inventoryQtys, itemName);
                if (have >= required) {
                    groupSatisfied = true;
                    break;
                }
            }
            if (!groupSatisfied) return false;
        }
        return true;
    }

    // Current inventory quantities (item name lowercased -> total qty across stacks)
    private Map<String, Long> inventoryQtyMap() {
        Map<String, Long> qtys = new HashMap<>();
        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        if (inventory == null) return qtys;
        for (Item item : inventory.getItems()) {
            if (item.getId() <= 0) continue;
            String name = itemManager.getItemComposition(item.getId()).getName();
            if (name != null) qtys.merge(name.toLowerCase(), (long) item.getQuantity(), Long::sum);
        }
        return qtys;
    }

    // PICKUP: snapshot current counts of every item referenced in the list (baseline at step start)

    // PICKUP: true once enough of each group's item has been gained since the baseline

    // PICKUP: how many gained so far (summed across groups, best alternative each) -- for HUD

    // PICKUP: total required across groups (largest alternative each) -- for HUD
    public long pickupRequired(String itemListStr) {
        long total = 0;
        for (List<String> group : parseItemList(itemListStr)) {
            long req = 0;
            for (String alt : group) req = Math.max(req, parseQuantityValue(alt));
            total += req;
        }
        return total;
    }

    /** Snapshot current inventory counts for items referenced in itemListStr. */
    public java.util.Map<String, Long> snapshotInventory(String itemListStr) {
        java.util.Map<String, Long> snapshot = new java.util.HashMap<>();
        net.runelite.api.ItemContainer inv = client.getItemContainer(net.runelite.api.InventoryID.INVENTORY);
        if (inv == null || itemListStr == null) return snapshot;
        for (java.util.List<String> group : parseItemList(itemListStr)) {
            for (String alt : group) {
                String name = parseItemName(alt).toLowerCase();
                long count = 0;
                for (net.runelite.api.Item item : inv.getItems()) {
                    if (item.getId() <= 0) continue;
                    String n = itemManager.getItemComposition(item.getId()).getName();
                    if (nameMatches(name, n)) count += item.getQuantity();
                }
                snapshot.put(name, count);
            }
        }
        return snapshot;
    }

    /** True when enough of each item group has been gained ABOVE the baseline snapshot. */
    public boolean hasAllItemsAboveBaseline(String itemListStr, java.util.Map<String, Long> baseline) {
        if (baseline == null) return hasAllItems(itemListStr);
        net.runelite.api.ItemContainer inv = client.getItemContainer(net.runelite.api.InventoryID.INVENTORY);
        if (inv == null) return false;
        // Count current inventory
        java.util.Map<String, Long> current = new java.util.HashMap<>();
        for (net.runelite.api.Item item : inv.getItems()) {
            if (item.getId() <= 0) continue;
            String n = itemManager.getItemComposition(item.getId()).getName();
            if (n == null) continue;
            current.merge(n.toLowerCase(), (long) item.getQuantity(), Long::sum);
        }
        for (java.util.List<String> group : parseItemList(itemListStr)) {
            long required = 0;
            for (String alt : group) required = Math.max(required, parseQuantityValue(alt));
            // Check if any alternative in the group satisfies the required amount above baseline
            boolean groupSatisfied = false;
            for (String alt : group) {
                String name = parseItemName(alt).toLowerCase();
                long base = baseline.getOrDefault(name, 0L);
                long gained = Math.max(0, countOf(current, name) - base);
                if (gained >= required) { groupSatisfied = true; break; }
            }
            if (!groupSatisfied) return false;
        }
        return true;
    }

    // SELL: returns true when none of the listed items remain in the inventory (all sold)
    public boolean hasSoldAll(String itemListStr) {
        List<List<String>> groups = parseItemList(itemListStr);
        if (groups.isEmpty()) return true;

        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        if (inventory == null) return true;

        Set<String> invNames = new HashSet<>();
        for (Item item : inventory.getItems()) {
            if (item.getId() <= 0) continue;
            String name = itemManager.getItemComposition(item.getId()).getName();
            if (name != null) invNames.add(name.toLowerCase());
        }

        for (List<String> group : groups) {
            for (String alt : group) {
                String itemName = parseItemName(alt).toLowerCase();
                if (anyMatches(invNames, itemName)) return false; // still holding one
            }
        }
        return true;
    }

    // SELL: returns [displayText, status] where status is "SOLD" or "HOLDING"
    public List<String[]> getSellStatusList(String itemListStr) {
        List<List<String>> groups = parseItemList(itemListStr);
        List<String[]> result = new ArrayList<>();
        if (groups.isEmpty()) return result;

        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        Set<String> invNames = new HashSet<>();
        if (inventory != null) {
            for (Item item : inventory.getItems()) {
                if (item.getId() <= 0) continue;
                String name = itemManager.getItemComposition(item.getId()).getName();
                if (name != null) invNames.add(name.toLowerCase());
            }
        }

        for (List<String> group : groups) {
            boolean holding = false;
            StringBuilder disp = new StringBuilder();
            for (int i = 0; i < group.size(); i++) {
                String alt = group.get(i);
                if (i > 0) disp.append("/");
                disp.append(alt);
                if (anyMatches(invNames, parseItemName(alt))) holding = true;
            }
            result.add(new String[]{disp.toString(), holding ? "HOLDING" : "SOLD"});
        }
        return result;
    }

    // Returns list of [displayText, status] where status is "HAVE" or "NEED"
    // Used by the HUD to show the item checklist on screen.
    public List<String[]> getItemStatusList(String itemListStr) {
        List<List<String>> groups = parseItemList(itemListStr);
        List<String[]> result = new ArrayList<>();
        if (groups.isEmpty()) return result;

        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        Map<String, Long> invQtys = new HashMap<>();
        if (inventory != null) {
            for (Item item : inventory.getItems()) {
                if (item.getId() <= 0) continue;
                String name = itemManager.getItemComposition(item.getId()).getName();
                if (name != null) {
                    invQtys.merge(name.toLowerCase(), (long) item.getQuantity(), Long::sum);
                }
            }
        }

        for (List<String> group : groups) {
            boolean have = false;
            StringBuilder disp = new StringBuilder();
            for (int i = 0; i < group.size(); i++) {
                String alt = group.get(i);
                if (i > 0) disp.append("/");
                disp.append(alt);
                String itemName = parseItemName(alt).toLowerCase();
                long required = parseQuantityValue(alt);
                if (countOf(invQtys, itemName) >= required) {
                    have = true;
                }
            }
            result.add(new String[]{disp.toString(), have ? "HAVE" : "NEED"});
        }
        return result;
    }

    /** Same as getItemStatusList but subtracts baseline counts for PICKUP steps. */
    public List<String[]> getItemStatusList(String itemListStr, java.util.Map<String, Long> baseline) {
        if (baseline == null) return getItemStatusList(itemListStr);
        List<List<String>> groups = parseItemList(itemListStr);
        List<String[]> result = new ArrayList<>();
        if (groups.isEmpty()) return result;
        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        Map<String, Long> invQtys = new HashMap<>();
        if (inventory != null) {
            for (Item item : inventory.getItems()) {
                if (item.getId() <= 0) continue;
                String name = itemManager.getItemComposition(item.getId()).getName();
                if (name != null) invQtys.merge(name.toLowerCase(), (long) item.getQuantity(), Long::sum);
            }
        }
        for (List<String> group : groups) {
            boolean have = false;
            StringBuilder disp = new StringBuilder();
            for (int i = 0; i < group.size(); i++) {
                String alt = group.get(i);
                if (i > 0) disp.append("/");
                disp.append(alt);
                String itemName = parseItemName(alt).toLowerCase();
                long required = parseQuantityValue(alt);
                long base = baseline.getOrDefault(itemName, 0L);
                long gained = Math.max(0, countOf(invQtys, itemName) - base);
                if (gained >= required) have = true;
            }
            result.add(new String[]{disp.toString(), have ? "HAVE" : "NEED"});
        }
        return result;
    }

    /** One line of an item list with live counts, for the side panel's step card. */
    public static final class ItemProgress {
        public final String name;
        public final long have;
        public final long need;
        public final int itemId; // -1 when the item couldn't be identified

        ItemProgress(String name, long have, long need, int itemId) {
            this.name = name;
            this.have = have;
            this.need = need;
            this.itemId = itemId;
        }
    }

    /**
     * Have/need counts per item-list entry, counting only items gained since {@code baseline}
     * when one is given. For alternatives ("Coins/Platinum token") the closest one is shown.
     * Call on the client thread.
     */
    public List<ItemProgress> getItemProgress(String itemListStr, Map<String, Long> baseline) {
        List<ItemProgress> out = new ArrayList<>();
        List<List<String>> groups = parseItemList(itemListStr);
        if (groups.isEmpty()) return out;
        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        Map<String, Long> invQtys = new HashMap<>();
        Map<String, Integer> invIds = new HashMap<>();
        if (inventory != null) {
            for (Item item : inventory.getItems()) {
                if (item.getId() <= 0) continue;
                String name = itemManager.getItemComposition(item.getId()).getName();
                if (name == null) continue;
                invQtys.merge(name.toLowerCase(), (long) item.getQuantity(), Long::sum);
                invIds.putIfAbsent(name.toLowerCase(), item.getId());
            }
        }
        for (List<String> group : groups) {
            ItemProgress best = null;
            for (String alt : group) {
                String name = parseItemName(alt);
                long need = parseQuantityValue(alt);
                long count = countOf(invQtys, name);
                if (baseline != null) count = Math.max(0, count - baseline.getOrDefault(name.toLowerCase(), 0L));
                long have = Math.min(count, need);
                if (best == null || (double) have / need > (double) best.have / best.need) {
                    best = new ItemProgress(name, have, need, idFor(name, invIds));
                }
            }
            if (best != null) out.add(best);
        }
        return out;
    }

    /** A Sell-step line: 1/1 once the item has left the inventory. */
    public ItemProgress soldLine(String name, boolean sold) {
        return new ItemProgress(name, sold ? 1 : 0, 1, idFor(parseItemName(name.split("/")[0]), new HashMap<>()));
    }

    private final Map<String, Integer> idCache = new HashMap<>();

    /** An item id for a list name, for its icon: from the inventory, else the item search. */
    private int idFor(String listName, Map<String, Integer> invIds) {
        for (Map.Entry<String, Integer> e : invIds.entrySet()) {
            if (nameMatches(listName, e.getKey())) return e.getValue();
        }
        String key = listName.trim().toLowerCase();
        Integer cached = idCache.get(key);
        if (cached != null) return cached;
        int id = -1;
        String search = key.endsWith(ANY_CHARGE) ? key.substring(0, key.length() - ANY_CHARGE.length()).trim() : key;
        for (net.runelite.http.api.item.ItemPrice p : itemManager.search(search)) {
            if (nameMatches(listName, p.getName()) || p.getName().equalsIgnoreCase(search)) { id = p.getId(); break; }
        }
        idCache.put(key, id);
        return id;
    }

    // Get list of missing items with quantities
    public List<String> getMissingItems(String itemListStr) {
        List<List<String>> groups = parseItemList(itemListStr);
        List<String> missing = new ArrayList<>();
        if (groups.isEmpty()) return missing;

        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        Map<String, Long> inventoryQtys = new HashMap<>();
        if (inventory != null) {
            for (Item item : inventory.getItems()) {
                if (item.getId() <= 0) continue;
                String name = itemManager.getItemComposition(item.getId()).getName();
                if (name != null) {
                    inventoryQtys.merge(name.toLowerCase(), (long) item.getQuantity(), Long::sum);
                }
            }
        }

        for (List<String> group : groups) {
            boolean found = false;
            for (String alt : group) {
                String itemName = parseItemName(alt).toLowerCase();
                long required = parseQuantityValue(alt);
                long have = countOf(inventoryQtys, itemName);
                if (have >= required) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                missing.add(String.join("/", group));
            }
        }
        return missing;
    }
}

package com.routeplanner.bank;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.util.List;

@Slf4j
@Singleton
public class BankOverlay extends Overlay {

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final BankItemManager bankItemManager;
    private final ItemManager itemManager;

    @Inject
    public BankOverlay(Client client, RoutePlannerPlugin plugin,
                       BankItemManager bankItemManager, ItemManager itemManager) {
        this.client = client;
        this.plugin = plugin;
        this.bankItemManager = bankItemManager;
        this.itemManager = itemManager;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null) return null;

        boolean isItem = step.hasItems();
        boolean isHerblore = step.isHighlightEnabled() && step.getHerblorePotion() != null;
        boolean isBankSkill = step.isHighlightEnabled() && step.getBankHighlightItems() != null
            && !step.getBankHighlightItems().trim().isEmpty();
        if (!isItem && !isHerblore && !isBankSkill) return null;

        // Check if the bank is open -- or the Farming Guild seed vault, which lists its items
        // the same way, so the same highlighting works there for tree/farm runs. The seed vault
        // uses the generated gameval id: ComponentID.SEED_VAULT_ITEM_CONTAINER points at an
        // empty sibling (631:17) since the interface was reworked; the items are in 631:18.
        Widget container = visibleWidget(ComponentID.BANK_ITEM_CONTAINER);
        if (container == null) container = visibleWidget(InterfaceID.SeedVault.OBJ_LIST);
        if (container == null) return null;
        Widget[] items = container.getDynamicChildren();
        if (items == null) return null;

        String itemListStr;
        if (isItem) {
            itemListStr = step.getItemList();
        } else if (isHerblore) {
            com.routeplanner.skilling.PotionRecipes.Potion pot =
                com.routeplanner.skilling.PotionRecipes.getByName(step.getHerblorePotion());
            if (pot == null) return null;
            if (inventoryHasItem(pot.unfinished)) {
                itemListStr = pot.secondary;
            } else if (bankHasItem(items, pot.unfinished)) {
                itemListStr = pot.unfinished + ", " + pot.secondary;
            } else {
                itemListStr = pot.herbGrimy + "/" + pot.herbClean + ", Vial of water";
            }
        } else {
            itemListStr = step.getBankHighlightItems();
        }

        List<List<String>> groups = bankItemManager.parseItemList(itemListStr);
        if (groups.isEmpty()) return null;

        // Items scrolled out of view still have canvas positions; keep highlights inside the list.
        Shape savedClip = graphics.getClip();
        graphics.clip(visibleBounds(container));
        for (Widget item : items) {
            if (item == null || item.isHidden() || item.getItemId() <= 0) continue;
            String itemName = itemManager.getItemComposition(item.getItemId()).getName();
            if (itemName == null) continue;

            boolean isRequired = false;
            boolean isMissing = false;

            for (List<String> group : groups) {
                for (String alt : group) {
                    String altName = bankItemManager.parseItemName(alt);
                    if (BankItemManager.nameMatches(altName, itemName)) {
                        isRequired = true;
                        // Check if INVENTORY has enough, not bank
                        long required = bankItemManager.parseQuantityValue(alt);
                        net.runelite.api.ItemContainer inv =
                            client.getItemContainer(net.runelite.api.InventoryID.INVENTORY);
                        long inInventory = 0;
                        if (inv != null) {
                            for (net.runelite.api.Item invItem : inv.getItems()) {
                                if (invItem.getId() <= 0) continue;
                                String invName = itemManager.getItemComposition(invItem.getId()).getName();
                                if (BankItemManager.nameMatches(altName, invName)) {
                                    inInventory += invItem.getQuantity();
                                }
                            }
                        }
                        isMissing = inInventory < required;
                        break;
                    }
                }
                if (isRequired) break;
            }

            if (isRequired) {
                Rectangle bounds = new Rectangle(
                    item.getCanvasLocation().getX(),
                    item.getCanvasLocation().getY(),
                    item.getWidth(),
                    item.getHeight()
                );
                // Green if already have it, orange if still need it
                Color highlight = isMissing
                    ? new Color(255, 140, 0, 120)
                    : new Color(0, 255, 0, 80);
                Color border = isMissing
                    ? new Color(255, 140, 0, 220)
                    : new Color(0, 255, 0, 200);

                graphics.setColor(highlight);
                graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
                graphics.setColor(border);
                graphics.setStroke(new BasicStroke(2));
                graphics.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
            }
        }
        graphics.setClip(savedClip);

        return null;
    }

    /**
     * The on-screen part of a widget. A scrolled list (like the seed vault's) can be far taller
     * than its window and start above the screen, so intersect with every ancestor's bounds.
     */
    private static Rectangle visibleBounds(Widget w) {
        Rectangle r = w.getBounds();
        for (Widget p = w.getParent(); p != null; p = p.getParent()) {
            r = r.intersection(p.getBounds());
        }
        return r;
    }

    private Widget visibleWidget(int componentId) {
        Widget w = client.getWidget(componentId);
        return w == null || w.isHidden() ? null : w;
    }

    private boolean bankHasItem(Widget[] items, String name) {
        if (name == null) return false;
        for (Widget item : items) {
            if (item == null || item.isHidden() || item.getItemId() <= 0) continue;
            String n = itemManager.getItemComposition(item.getItemId()).getName();
            if (n != null && n.equalsIgnoreCase(name)) return true;
        }
        return false;
    }

    private boolean inventoryHasItem(String name) {
        if (name == null) return false;
        net.runelite.api.ItemContainer inv =
            client.getItemContainer(net.runelite.api.InventoryID.INVENTORY);
        if (inv == null) return false;
        for (net.runelite.api.Item invItem : inv.getItems()) {
            if (invItem.getId() <= 0) continue;
            String n = itemManager.getItemComposition(invItem.getId()).getName();
            if (n != null && n.equalsIgnoreCase(name)) return true;
        }
        return false;
    }
}

package com.routeplanner.bank;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Highlights matching ground items on tiles for an ITEM step in PICKUP mode.
 */
@Slf4j
@Singleton
public class GroundItemOverlay extends Overlay {

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final BankItemManager bankItemManager;
    private final ItemManager itemManager;

    @Inject
    public GroundItemOverlay(Client client, RoutePlannerPlugin plugin,
                             BankItemManager bankItemManager, ItemManager itemManager) {
        this.client = client;
        this.plugin = plugin;
        this.bankItemManager = bankItemManager;
        this.itemManager = itemManager;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || !step.hasItems()) return null;
        if (!"PICKUP".equals(step.getItemMode())) return null;

        // Collect target item names (lowercased), supporting "/" alternatives
        List<List<String>> groups = bankItemManager.parseItemList(step.getItemList());
        if (groups.isEmpty()) return null;
        Set<String> targets = new HashSet<>();
        for (List<String> group : groups) {
            for (String alt : group) {
                String n = bankItemManager.parseItemName(alt);
                if (n != null) targets.add(n.toLowerCase());
            }
        }
        if (targets.isEmpty()) return null;

        Scene scene = client.getScene();
        if (scene == null) return null;
        Tile[][][] tiles = scene.getTiles();
        int z = client.getPlane();
        if (z < 0 || z >= tiles.length) return null;
        Tile[][] plane = tiles[z];

        for (Tile[] row : plane) {
            if (row == null) continue;
            for (Tile tile : row) {
                if (tile == null) continue;
                List<TileItem> groundItems = tile.getGroundItems();
                if (groundItems == null || groundItems.isEmpty()) continue;

                String matchName = null;
                for (TileItem gi : groundItems) {
                    if (gi == null) continue;
                    String name = itemManager.getItemComposition(gi.getId()).getName();
                    if (name != null && targets.stream().anyMatch(t -> BankItemManager.nameMatches(t, name))) {
                        matchName = name;
                        break;
                    }
                }
                if (matchName == null) continue;

                LocalPoint lp = tile.getLocalLocation();
                if (lp == null) continue;

                net.runelite.api.ItemLayer itemLayer = tile.getItemLayer();
                if (itemLayer != null) {
                    Shape clickbox = itemLayer.getClickbox();
                    if (clickbox != null) {
                        graphics.setColor(new Color(255, 140, 0, 70));
                        graphics.fill(clickbox);
                        graphics.setColor(new Color(255, 140, 0, 230));
                        graphics.setStroke(new BasicStroke(2));
                        graphics.draw(clickbox);
                    }
                }

                net.runelite.api.Point textLoc =
                    Perspective.getCanvasTextLocation(client, graphics, lp, matchName, 0);
                if (textLoc != null) {
                    graphics.setColor(Color.BLACK);
                    graphics.drawString(matchName, textLoc.getX() + 1, textLoc.getY() + 1);
                    graphics.setColor(new Color(255, 200, 0));
                    graphics.drawString(matchName, textLoc.getX(), textLoc.getY());
                }
            }
        }
        return null;
    }

}

package com.routeplanner.bank;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;

/**
 * Outlines the active step's inventory items (its "Inventory items" highlight), for steps where
 * you use one item on another, e.g. a cocktail shaker for a Fruit Blast. Gated by the step's
 * Highlight toggle like its NPC and object. Highlight only: never clicks.
 */
@Singleton
public class InventoryItemOverlay extends Overlay {
    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final ItemManager itemManager;
    private final BankItemManager bankItemManager;

    @Inject
    public InventoryItemOverlay(Client client, RoutePlannerPlugin plugin, ItemManager itemManager,
                                BankItemManager bankItemManager) {
        this.client = client;
        this.plugin = plugin;
        this.itemManager = itemManager;
        this.bankItemManager = bankItemManager;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || !step.isHighlightEnabled()) return null;
        String list = step.getInventoryHighlightItems();
        if (list == null || list.trim().isEmpty()) return null;

        List<String> wanted = new ArrayList<>();
        for (String entry : list.split("[,/]")) {
            if (!entry.trim().isEmpty()) wanted.add(bankItemManager.parseItemName(entry));
        }

        Widget inv = client.getWidget(InterfaceID.Inventory.ITEMS);
        if (inv == null || inv.isHidden()) return null;
        Widget[] slots = inv.getDynamicChildren();
        if (slots == null) return null;
        for (Widget slot : slots) {
            if (slot == null || slot.isHidden() || slot.getItemId() <= 0) continue;
            String name = itemManager.getItemComposition(slot.getItemId()).getName();
            for (String want : wanted) {
                if (BankItemManager.nameMatches(want, name)) {
                    highlight(graphics, slot.getBounds());
                    break;
                }
            }
        }
        return null;
    }

    private void highlight(Graphics2D graphics, Rectangle b) {
        if (b == null) return;
        Color outline = plugin.getConfig().npcHighlightColor();
        graphics.setColor(outline);
        graphics.setStroke(new BasicStroke(2));
        graphics.drawRect(b.x, b.y, b.width, b.height);
        graphics.setColor(com.routeplanner.util.HighlightColors.fill(outline));
        graphics.fillRect(b.x, b.y, b.width, b.height);
    }
}

package com.routeplanner.bank;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.util.List;

@Slf4j
@Singleton
public class ShopOverlay extends Overlay {

    // Shop stock container: group 300, child 16
    private static final int SHOP_GROUP = 300;
    private static final int SHOP_STOCK_CHILD = 16;

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final BankItemManager bankItemManager;
    private final ItemManager itemManager;

    @Inject
    public ShopOverlay(Client client, RoutePlannerPlugin plugin,
                       BankItemManager bankItemManager, ItemManager itemManager) {
        this.client = client;
        this.plugin = plugin;
        this.bankItemManager = bankItemManager;
        this.itemManager = itemManager;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || !step.hasItems()) return null;
        String mode = step.getItemMode();
        boolean isSell = "SELL".equals(mode);
        boolean isShop = "SHOP".equals(mode);
        if (!isShop && !isSell) return null;

        // SHOP highlights the shop stock (300,16); SELL highlights the inventory panel (301,0)
        Widget container = isSell
            ? client.getWidget(301, 0)
            : client.getWidget(SHOP_GROUP, SHOP_STOCK_CHILD);
        if (container == null || container.isHidden()) return null;

        List<List<String>> groups = bankItemManager.parseItemList(step.getItemList());
        if (groups.isEmpty()) return null;

        Widget[] items = container.getDynamicChildren();
        if (items == null) return null;

        for (Widget item : items) {
            if (item == null || item.isHidden() || item.getItemId() <= 0) continue;
            String itemName = itemManager.getItemComposition(item.getItemId()).getName();
            if (itemName == null) continue;

            boolean isRequired = false;
            boolean isMissing = false;

            for (List<String> group : groups) {
                for (String alt : group) {
                    String altName = bankItemManager.parseItemName(alt);
                    if (BankItemManager.nameMatches(altName, itemName)) {
                        isRequired = true;
                        if (isSell) {
                            // Item present in inventory = still needs selling -> orange
                            isMissing = true;
                        } else {
                            long required = bankItemManager.parseQuantityValue(alt);
                            // Count only what was bought since the step started.
                            long inInventory = countInInventory(altName);
                            if (step.getPickupBaseline() != null) {
                                inInventory -= step.getPickupBaseline().getOrDefault(altName.toLowerCase(), 0L);
                            }
                            isMissing = inInventory < required;
                        }
                        break;
                    }
                }
                if (isRequired) break;
            }

            if (isRequired) {
                Rectangle bounds = new Rectangle(
                    item.getCanvasLocation().getX(),
                    item.getCanvasLocation().getY(),
                    item.getWidth(),
                    item.getHeight()
                );
                Color highlight = isMissing
                    ? new Color(255, 140, 0, 120)
                    : new Color(0, 255, 0, 80);
                Color border = isMissing
                    ? new Color(255, 140, 0, 220)
                    : new Color(0, 255, 0, 200);

                graphics.setColor(highlight);
                graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
                graphics.setColor(border);
                graphics.setStroke(new BasicStroke(2));
                graphics.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
            }
        }

        return null;
    }

    private long countInInventory(String itemName) {
        ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
        if (inv == null) return 0;
        long total = 0;
        for (Item invItem : inv.getItems()) {
            if (invItem.getId() <= 0) continue;
            String name = itemManager.getItemComposition(invItem.getId()).getName();
            if (BankItemManager.nameMatches(itemName, name)) {
                total += invItem.getQuantity();
            }
        }
        return total;
    }
}

package com.routeplanner.dialog;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import com.routeplanner.model.StepType;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.List;

/**
 * Highlights the chat dialogue option to press for a NOTE step that defines a
 * dialogue sequence (e.g. "3,1"). Reads the standard option widget (group 219).
 */
@Singleton
public class DialogHighlightOverlay extends Overlay {

    private final Client client;
    private final RoutePlannerPlugin plugin;

    @Inject
    public DialogHighlightOverlay(Client client, RoutePlannerPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || step.getDialogOptions() == null
            || step.getDialogOptions().trim().isEmpty()) return null;
        String seqStr = step.getDialogOptions();
        if (seqStr == null || seqStr.trim().isEmpty()) return null;

        String[] parts = seqStr.split(",");
        int progress = plugin.getDialogProgress();
        if (progress < 0 || progress >= parts.length) return null;
        int targetOption;
        try {
            targetOption = Integer.parseInt(parts[progress].trim());
        } catch (NumberFormatException e) {
            return null;
        }

        List<Widget> options = DialogOptions.options(client);
        if (targetOption < 1 || targetOption > options.size()) return null;

        Rectangle b = options.get(targetOption - 1).getBounds();
        if (b == null || b.width <= 0 || b.height <= 0) return null;

        graphics.setColor(new Color(255, 140, 0, 60));
        graphics.fillRect(b.x - 2, b.y - 1, b.width + 4, b.height + 2);
        graphics.setColor(new Color(255, 140, 0, 235));
        graphics.setStroke(new BasicStroke(2));
        graphics.drawRect(b.x - 2, b.y - 1, b.width + 4, b.height + 2);
        return null;
    }
}

package com.routeplanner.dialog;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

import java.util.ArrayList;
import java.util.List;

/**
 * Reading the chat options menu ("Select an Option"). Shared by the highlight overlay and the
 * recorder so both count options the same way: option 1 is the first line under the title.
 */
public final class DialogOptions {

    private DialogOptions() {}

    /** The open options menu's container, or null when it isn't showing. */
    public static Widget container(Client client) {
        Widget w = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
        return w == null || w.isHidden() ? null : w;
    }

    /** The option lines in order (title excluded); empty when the menu isn't open. */
    public static List<Widget> options(Client client) {
        List<Widget> out = new ArrayList<>();
        Widget container = container(client);
        if (container == null) return out;
        Widget[] kids = container.getDynamicChildren();
        if (kids == null || kids.length == 0) kids = container.getChildren();
        if (kids == null) return out;
        boolean titleSkipped = false;
        for (Widget w : kids) {
            if (w == null || w.isHidden()) continue;
            String t = w.getText();
            if (t == null || t.trim().isEmpty()) continue;
            // The first line is always the menu's title ("Select an Option", or a question
            // like "Start the quest?"), never something to pick.
            if (!titleSkipped) { titleSkipped = true; continue; }
            out.add(w);
        }
        return out;
    }

    /** The option lines' text, cleaned of colour tags. */
    public static List<String> texts(Client client) {
        List<String> out = new ArrayList<>();
        for (Widget w : options(client)) out.add(clean(w.getText()));
        return out;
    }

    public static String clean(String raw) {
        return raw == null ? "" : Text.removeTags(raw).replace(' ', ' ').trim();
    }
}

package com.routeplanner.hub;

/**
 * Thrown by {@link RouteHubFetcher} on any failure -- network, HTTP, oversized payload, or an
 * unsafe path. The message is written to be shown directly to the user, never a stack trace.
 */
public class HubFetchException extends Exception {
    public HubFetchException(String message) {
        super(message);
    }
}

package com.routeplanner.hub;

import java.util.List;

/**
 * Deserialized shape of index.json from the Route Hub repo. Field names must match the JSON
 * exactly since Gson binds by name. Anything the catalog doesn't recognize (a newer schemaVersion,
 * or fields added later) is simply ignored by Gson rather than causing a parse failure.
 */
public class HubIndex {
    public int schemaVersion;
    public List<HubRouteEntry> routes;
}

package com.routeplanner.hub;

import java.util.List;

/**
 * One catalog entry from index.json. All fields are read-only data from the network -- nothing
 * here is trusted until it has passed {@link HubRouteEntry#validate()}, which enforces the v1.4
 * plan's bounds (name/description length, step count) and re-runs the link scanner over every
 * free-text field, independently of whatever checks the submitter's editor may or may not have
 * applied.
 */
public class HubRouteEntry {
    public String id;
    public String name;
    public String author;
    public String description;
    public String icon;
    public String file;
    public int steps;
    public List<String> tags;
    public String updated;

    private static final int MAX_NAME_LEN = 100;
    private static final int MAX_DESC_LEN = 120;
    private static final int MAX_STEPS = 1500;

    /**
     * @return null if the entry is safe to display/install, or a short reason if it should be
     * rejected. Never throws -- a malformed catalog entry should be skipped, not crash the panel.
     */
    public String validate() {
        if (id == null || id.isEmpty()) return "missing id";
        if (id.contains("..") || id.contains("/") || id.contains("\\")) return "unsafe id";
        if (name == null || name.isEmpty()) return "missing name";
        if (name.length() > MAX_NAME_LEN) return "name too long";
        if (author == null || author.isEmpty()) return "missing author";
        if (description == null) return "missing description";
        if (description.length() > MAX_DESC_LEN) return "description too long";
        if (file == null || file.isEmpty() || file.contains("..") || file.startsWith("/")) return "unsafe file path";
        if (icon != null && (icon.contains("..") || icon.startsWith("/"))) return "unsafe icon path";
        if (steps < 0 || steps > MAX_STEPS) return "step count out of bounds";

        String linkErr = com.routeplanner.util.RouteTextValidator.checkField("Route name", name);
        if (linkErr == null) linkErr = com.routeplanner.util.RouteTextValidator.checkField("Description", description);
        if (linkErr == null && author != null) linkErr = com.routeplanner.util.RouteTextValidator.checkField("Author", author);
        if (linkErr != null) return linkErr;

        return null;
    }
}

package com.routeplanner.hub;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.List;

/**
 * Fetches and parses the Route Hub catalog. Entries that fail {@link HubRouteEntry#validate()} are
 * dropped rather than shown or installed -- a bad entry should never reach the browse panel or the
 * install path, even if it somehow got past PR review.
 */
@Slf4j
@Singleton
public class RouteHubCatalog {

    private final RouteHubFetcher fetcher;
    private final Gson gson;

    @Inject
    public RouteHubCatalog(RouteHubFetcher fetcher, Gson gson) {
        this.fetcher = fetcher;
        this.gson = gson;
    }

    /** Fetches, parses, and validates the catalog. Never returns null; returns an empty list on
     *  total failure so the panel can show "couldn't load" rather than crash. */
    /** Passthrough to the fetcher for icon bytes, keeping RouteHubPanel from needing to know about
     *  RouteHubFetcher directly -- it only ever talks to the catalog. */
    public byte[] fetchIconBytes(String relativeIconPath) throws HubFetchException {
        return fetcher.fetchIcon(relativeIconPath);
    }

    /** Passthrough to the fetcher for a route file's raw JSON. Deserialization and validation are
     *  the caller's responsibility (RouteHubPanel uses plugin.getRouteGson() and
     *  validateFetchedRoute()), since RouteHubCatalog only knows about catalog-level shape. */
    public String fetchRouteJson(String relativeRoutePath) throws HubFetchException {
        return fetcher.fetchRoute(relativeRoutePath);
    }

    public List<HubRouteEntry> loadValidEntries() throws HubFetchException {
        String json = fetcher.fetchIndex();
        HubIndex index;
        try {
            index = gson.fromJson(json, HubIndex.class);
        } catch (JsonSyntaxException e) {
            log.warn("Route Hub index.json failed to parse", e);
            throw new HubFetchException("The Route Hub catalog is malformed and couldn't be read.");
        }
        if (index == null || index.routes == null) {
            throw new HubFetchException("The Route Hub catalog is empty or malformed.");
        }

        List<HubRouteEntry> valid = new ArrayList<>();
        for (HubRouteEntry entry : index.routes) {
            if (entry == null) continue;
            String err = entry.validate();
            if (err != null) {
                log.warn("Skipping invalid Route Hub entry (id={}): {}", entry.id, err);
                continue;
            }
            valid.add(entry);
        }
        return valid;
    }
}

package com.routeplanner.hub;

import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;

/**
 * Read-only GETs against the Route Hub's GitHub-hosted catalog. Every call is a plain HTTP GET to
 * raw.githubusercontent.com -- nothing is ever uploaded or posted. Bounds (payload size caps) are
 * enforced here so a malformed or oversized response can never wedge the panel; callers get a
 * {@link HubFetchException} instead of a crash, with a message safe to show the user directly.
 */
@Slf4j
@Singleton
public class RouteHubFetcher {

    /** Base raw-content URL for the curated routes repo, branch pinned to avoid surprise changes. */
    private static final String BASE_URL =
        "https://raw.githubusercontent.com/BlackDeath-Osrs/route-planner-routes/main/";

    // Sanity caps mirroring the v1.4 plan bounds. A response over these is rejected outright.
    private static final long MAX_INDEX_BYTES = 1_500_000;   // ~1 MB catalog, some headroom
    private static final long MAX_ROUTE_BYTES = 2_500_000;   // ~2 MB per-route cap, some headroom
    private static final long MAX_ICON_BYTES = 25_000;       // 20 KB icon cap, some headroom

    private final OkHttpClient okHttpClient;

    @Inject
    public RouteHubFetcher(OkHttpClient okHttpClient) {
        this.okHttpClient = okHttpClient;
    }

    /** Fetches index.json as raw text. Caller is responsible for JSON parsing + schema validation. */
    public String fetchIndex() throws HubFetchException {
        return fetchText("index.json", MAX_INDEX_BYTES, "route catalog");
    }

    /** Fetches a single route file (path as given in index.json's "file" field) as raw text. */
    public String fetchRoute(String relativePath) throws HubFetchException {
        requireSafeRelativePath(relativePath);
        return fetchText(relativePath, MAX_ROUTE_BYTES, "route");
    }

    /** Fetches an icon (path as given in index.json's "icon" field) as raw bytes. */
    public byte[] fetchIcon(String relativePath) throws HubFetchException {
        requireSafeRelativePath(relativePath);
        return fetchBytes(relativePath, MAX_ICON_BYTES, "icon");
    }

    // ---- internals ----

    /**
     * index.json and route "file"/"icon" entries are relative paths we build a URL from. Reject
     * anything that looks like it is trying to escape the repo (".." segments) or specify a whole
     * new host (a scheme or a leading "//") -- the catalog must only ever point within itself.
     */
    private void requireSafeRelativePath(String relativePath) throws HubFetchException {
        if (relativePath == null || relativePath.isEmpty()
            || relativePath.contains("..")
            || relativePath.startsWith("/")
            || relativePath.contains("://")) {
            throw new HubFetchException("The Route Hub catalog referenced an invalid file path.");
        }
    }

    private String fetchText(String relativePath, long maxBytes, String what) throws HubFetchException {
        byte[] bytes = fetchBytes(relativePath, maxBytes, what);
        return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
    }

    private byte[] fetchBytes(String relativePath, long maxBytes, String what) throws HubFetchException {
        Request request = new Request.Builder().url(BASE_URL + relativePath).build();
        try (Response response = okHttpClient.newCall(request).execute()) {
            if (!response.isSuccessful()) {
                throw new HubFetchException("Couldn't reach the Route Hub (the " + what + " wasn't found or the server had an error).");
            }
            if (response.body() == null) {
                throw new HubFetchException("The Route Hub sent back an empty response for the " + what + ".");
            }
            long declaredLength = response.body().contentLength();
            if (declaredLength > maxBytes) {
                throw new HubFetchException("The " + what + " from the Route Hub was too large to load safely.");
            }
            byte[] data = response.body().bytes();
            if (data.length > maxBytes) {
                throw new HubFetchException("The " + what + " from the Route Hub was too large to load safely.");
            }
            return data;
        } catch (IOException e) {
            log.warn("Route Hub fetch failed for {}", relativePath, e);
            throw new HubFetchException("Couldn't connect to the Route Hub. Check your connection and try again.");
        }
    }
}

package com.routeplanner.hub;

