        bottomStack.setLayout(new BoxLayout(bottomStack, BoxLayout.Y_AXIS));
        bottomStack.setOpaque(false);
        bottomStack.add(footerLabel);
        bottomStack.add(buildWarningBanner());
        add(bottomStack, BorderLayout.SOUTH);
    }

    /** Called each time the Hub view is switched to. Loads once per panel lifetime for now --
     *  a manual refresh / re-check-on-open comes with the Installed tab in a later step. */
    public void onShown() {
        if (loadedOnce) return;
        loadedOnce = true;
        load();
    }

    // Decoded icons keyed by entry id, so re-rendering the list (e.g. after a tab switch) does not
    // re-fetch or re-decode icons that already loaded successfully this session. Cleared never --
    // the panel's lifetime is one Hub-view visit, and 12-48px icons are cheap to hold in memory.
    private final java.util.Map<String, ImageIcon> iconCache = new java.util.HashMap<>();
    private java.util.List<HubRouteEntry> allEntries = java.util.Collections.emptyList();

    /** Fetches and decodes one entry's icon off the EDT, then swaps it into the given label. Never
     *  throws back to the caller and never leaves the label in a broken state -- on any failure the
     *  grey-blue placeholder simply stays as-is. */
    private void loadIconInto(JLabel target, HubRouteEntry entry) {
        ImageIcon cached = iconCache.get(entry.id);
        if (cached != null) {
            target.setIcon(cached);
            return;
        }
        if (entry.icon == null || entry.icon.isEmpty()) return;

        new SwingWorker<ImageIcon, Void>() {
            @Override
            protected ImageIcon doInBackground() {
                try {
                    byte[] bytes = catalog.fetchIconBytes(entry.icon);
                    java.awt.Image img = javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(bytes));
                    if (img == null) return null; // not a decodable image
                    if (img.getWidth(null) <= 0 || img.getHeight(null) <= 0) return null;
                    java.awt.Image scaled = img.getScaledInstance(48, 48, java.awt.Image.SCALE_SMOOTH);
                    return new ImageIcon(scaled);
                } catch (Exception e) {
                    log.debug("Icon load failed for {}: {}", entry.id, e.toString());
                    return null;
                }
            }

            @Override
            protected void done() {
                try {
                    ImageIcon icon = get();
                    if (icon == null) return; // leave the placeholder as-is
                    iconCache.put(entry.id, icon);
                    target.setIcon(icon);
                } catch (Exception e) {
                    // failed or cancelled -- placeholder remains, nothing to show the user for this
                }
            }
        }.execute();
    }

    private static final int MAX_STEPS = 1500;
    private static final int MAX_NOTE_LEN = 280;
    private static final int MAX_NAME_LEN = 100;

    /**
     * Re-validates every free-text field of every step in a fetched route, independently of
     * whatever the catalog entry or PR review already checked. A route JSON fetched over the
     * network must never be trusted just because it appeared in the curated index -- this is the
     * import-time re-validation layer from the security model. Returns null if the route is safe
     * to install, or a short user-facing reason if it should be refused.
     */
    private String validateFetchedRoute(com.routeplanner.model.Route route) {
        if (route == null || route.getName() == null) return "The route file is empty or malformed.";
        if (route.getName().length() > MAX_NAME_LEN) return "The route's name is too long.";

        String nameErr = com.routeplanner.util.RouteTextValidator.checkField("Route name", route.getName());
        if (nameErr != null) return nameErr;

        int totalSteps = 0;
        java.util.List<com.routeplanner.model.RouteSection> sections = route.getSections();
        if (sections == null) return null; // an empty route is unusual but not unsafe

        for (com.routeplanner.model.RouteSection section : sections) {
            if (section == null || section.getSteps() == null) continue;

            String secErr = com.routeplanner.util.RouteTextValidator.checkField("Section name", section.getName());
            if (secErr != null) return secErr;

            for (com.routeplanner.model.RouteStep step : section.getSteps()) {
                if (step == null) continue;
                totalSteps++;
                if (totalSteps > MAX_STEPS) return "This route has too many steps.";

                if (step.getName() != null && step.getName().length() > MAX_NAME_LEN) {
                    return "A step name is too long.";
                }
                if (step.getNoteText() != null && step.getNoteText().length() > MAX_NOTE_LEN) {
                    return "A step's note is too long.";
                }

                String err = com.routeplanner.util.RouteTextValidator.checkField("Step name", step.getName());
                if (err == null) err = com.routeplanner.util.RouteTextValidator.checkField("Note", step.getNoteText());
                if (err == null) err = com.routeplanner.util.RouteTextValidator.checkField("Highlight NPC", step.getNpcHighlight());
                if (err == null) err = com.routeplanner.util.RouteTextValidator.checkField("Dialogue options", step.getDialogOptions());
                if (err == null) err = com.routeplanner.util.RouteTextValidator.checkField("Items", step.getItemList());
                if (err == null) err = com.routeplanner.util.RouteTextValidator.checkField("Inventory items", step.getInventoryHighlightItems());
                if (err != null) return err;
            }
        }
        return null;
    }

    private void load() {
        new SwingWorker<List<HubRouteEntry>, Void>() {
            private HubFetchException failure;

            @Override
            protected List<HubRouteEntry> doInBackground() {
                try {
                    return catalog.loadValidEntries();
                } catch (HubFetchException e) {
                    failure = e;
                    return null;
                }
            }

            @Override
            protected void done() {
                listPanel.remove(statusLabel);
                if (failure != null) {
                    showMessage(failure.getMessage());
                    return;
                }
                List<HubRouteEntry> entries;
                try {
                    entries = get();
                } catch (Exception e) {
                    showMessage("Something went wrong loading the Route Hub.");
                    return;
                }
                if (entries == null || entries.isEmpty()) {
                    showMessage("No routes are available yet.");
                    return;
                }
                allEntries = entries;
                applyFilter("");
                updateFooter(entries);
            }
        }.execute();
    }

    /** Re-renders the list from allEntries, keeping only rows whose name, description, author, or
     *  tags contain the query (case-insensitive). Rebuilding rows from scratch each time is simpler
     *  and less error-prone than trying to show/hide already-built components, and with a catalog
     *  this small the cost is negligible. */
    private void applyFilter(String query) {
        listPanel.removeAll();
        String q = query == null ? "" : query.trim().toLowerCase();

        java.util.List<HubRouteEntry> matches = new java.util.ArrayList<>();
        for (HubRouteEntry entry : allEntries) {
            if (q.isEmpty() || matchesQuery(entry, q)) matches.add(entry);
        }

        if (matches.isEmpty()) {
            showMessage(q.isEmpty() ? "No routes are available yet." : "No routes match \"" + query + "\".");
        } else {
            for (HubRouteEntry entry : matches) {
                listPanel.add(buildRow(entry));
                listPanel.add(Box.createVerticalStrut(6));
            }
        }
        listPanel.revalidate();
        listPanel.repaint();
    }

    private boolean matchesQuery(HubRouteEntry entry, String lowerQuery) {
        if (entry.name != null && entry.name.toLowerCase().contains(lowerQuery)) return true;
        if (entry.description != null && entry.description.toLowerCase().contains(lowerQuery)) return true;
        if (entry.author != null && entry.author.toLowerCase().contains(lowerQuery)) return true;
        if (entry.tags != null) {
            for (String tag : entry.tags) {
                if (tag != null && tag.toLowerCase().contains(lowerQuery)) return true;
            }
        }
        return false;
    }

    /** Shows the most recent "updated" date across the catalog, in a small footer. A single line
     *  for the whole Hub, not per-row, since the ask was catalog freshness at a glance. */
    private void updateFooter(java.util.List<HubRouteEntry> entries) {
        String latest = null;
        for (HubRouteEntry entry : entries) {
            if (entry.updated == null || entry.updated.isEmpty()) continue;
            if (latest == null || entry.updated.compareTo(latest) > 0) latest = entry.updated;
        }
        footerLabel.setText(latest != null ? "Route Hub last updated " + latest : " ");
    }

    private void showMessage(String text) {
        JLabel msg = new JLabel(text);
        msg.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        msg.setBorder(new EmptyBorder(10, 4, 10, 4));
        listPanel.add(msg);
        listPanel.revalidate();
        listPanel.repaint();
    }

    /** A route row: a 48x48 icon placeholder on the left, name/description/author line in the
     *  middle, and a small green "+" install control anchored to the bottom-right of the sub-line.
     *  Real icon bytes and real install behaviour arrive with the install step (4e/4f); this gets
     *  the layout and sizing right first, since that is what is actually visible right now. */
    /** The persistent "Community content" disclosure: expanded by default, collapsible to a single
     *  line via the chevron, with the choice remembered across sessions. This replaces a per-install
     *  confirmation dialog -- the caution is visible the whole time the Hub is being browsed, rather
     *  than a click-through box shown once per install. */
    private JPanel buildWarningBanner() {
        JPanel banner = new JPanel(new BorderLayout());
        banner.setBackground(new Color(42, 36, 22));
        banner.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(new Color(90, 74, 31), 1),
            new EmptyBorder(0, 0, 0, 0)));

        JLabel label = new JLabel("\u26a0 Community content");
        label.setForeground(new Color(255, 204, 102));
        label.setFont(label.getFont().deriveFont(Font.BOLD, 11f));
        label.setBorder(new EmptyBorder(8, 10, 8, 4));

        JLabel chevron = new JLabel();
        chevron.setForeground(new Color(216, 201, 143));
        chevron.setFont(chevron.getFont().deriveFont(11f));
        chevron.setBorder(new EmptyBorder(8, 4, 8, 10));
        chevron.setCursor(new Cursor(Cursor.HAND_CURSOR));

        JPanel head = new JPanel(new BorderLayout());
        head.setOpaque(false);
        head.add(label, BorderLayout.WEST);
        head.add(chevron, BorderLayout.EAST);
        head.setCursor(new Cursor(Cursor.HAND_CURSOR));

        String warningText = "These routes are made by other players, not by Route Planner. "
            + "Submissions are reviewed and links are blocked, but always be cautious \u2014 never "
            + "follow a step that asks you to visit a website, share your account, or do anything "
            + "outside the game.";

        JLabel body = new JLabel("<html><div style=\'width:180px;\'>" + warningText + "</div></html>");
        body.setForeground(new Color(216, 201, 143));
        body.setFont(body.getFont().deriveFont(10.5f));
        body.setBorder(new EmptyBorder(0, 10, 10, 10));

        // The panel text is small to fit the row width; the tooltip shows the same words at normal
        // system tooltip size/font, which is easier to read on request.
        String tooltipHtml = "<html><div style=\'width:220px;\'>" + warningText + "</div></html>";
        body.setToolTipText(tooltipHtml);
        label.setToolTipText(tooltipHtml);

        banner.add(head, BorderLayout.NORTH);
        banner.add(body, BorderLayout.CENTER);

        Runnable applyState = () -> {
            boolean collapsed = plugin.isHubWarningCollapsed();
            body.setVisible(!collapsed);
            chevron.setText(collapsed ? "\u25b8" : "\u25be");
        };
        applyState.run();

        java.awt.event.MouseAdapter toggle = new java.awt.event.MouseAdapter() {
            @Override
            public void mouseClicked(java.awt.event.MouseEvent e) {
                plugin.setHubWarningCollapsed(!plugin.isHubWarningCollapsed());
                applyState.run();
                banner.revalidate();
                banner.repaint();
            }
        };
        head.addMouseListener(toggle);
        chevron.addMouseListener(toggle);

        return banner;
    }

    private JPanel buildRow(HubRouteEntry entry) {
        JPanel row = new JPanel(new BorderLayout(10, 0));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        // Right padding trimmed (9 -> -6, i.e. 15px less) so the install "+" sits further right,
        // per direct feedback. Left/top/bottom padding are untouched.
        row.setBorder(new EmptyBorder(9, 9, 9, -6));

        // Fixed-size icon, wrapped in a panel so BorderLayout cannot stretch it to the row's height.
        JLabel iconLabel = new JLabel();
        iconLabel.setOpaque(true);
        iconLabel.setBackground(new Color(45, 55, 65));
        iconLabel.setHorizontalAlignment(SwingConstants.CENTER);
        iconLabel.setBorder(BorderFactory.createLineBorder(new Color(60, 70, 80), 1));
        loadIconInto(iconLabel, entry);
        JPanel iconBox = new JPanel();
        iconBox.setOpaque(false);
        iconBox.setLayout(new BoxLayout(iconBox, BoxLayout.Y_AXIS));
        iconLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        iconLabel.setMaximumSize(new Dimension(48, 48));
        iconLabel.setPreferredSize(new Dimension(48, 48));
        iconLabel.setMinimumSize(new Dimension(48, 48));
        iconBox.add(iconLabel);
        iconBox.add(Box.createVerticalStrut(6));
        // installBtn is built below and added here, under the icon, per direct feedback --
        // it no longer competes with the description for horizontal room on the text side.

        JLabel name = new JLabel(escape(entry.name));
        name.setForeground(Color.WHITE);
        name.setFont(name.getFont().deriveFont(Font.BOLD, 13.5f));
        name.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel desc = new JLabel(escape(entry.description));
        desc.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        desc.setFont(desc.getFont().deriveFont(12f));
        desc.setBorder(new EmptyBorder(2, 0, 2, 0));
        desc.setAlignmentX(Component.LEFT_ALIGNMENT);
        desc.setMaximumSize(new Dimension(Integer.MAX_VALUE, 16));
        desc.setPreferredSize(new Dimension(0, 16));

        JLabel installBtn = buildInstallControl(entry);
        installBtn.setAlignmentX(Component.LEFT_ALIGNMENT);
        // "by X · N steps" no longer takes row width -- it's a tooltip on the name/description
        // instead, since the row is too narrow to fit that text alongside anything else without
        // clipping. The tooltip text is plain (not HTML), so no escaping is needed here beyond
        // what Swing already does for tooltip content.
        String subInfo = "by " + entry.author + " \u00b7 " + entry.steps + " steps";
        name.setToolTipText(subInfo);
        // Description's tooltip shows the description itself, not author/steps -- the div above it
        // wraps and can visually truncate, so hovering should reveal the full text rather than
        // duplicate what the name's tooltip already says.
        desc.setToolTipText("<html><div style=\'width:220px;\'>" + escape(entry.description) + "</div></html>");
        installBtn.setToolTipText("Install this route (" + subInfo + ")");
        iconBox.add(installBtn);

        JPanel textCol = new JPanel();
        textCol.setLayout(new BoxLayout(textCol, BoxLayout.Y_AXIS));
        textCol.setOpaque(false);
        textCol.add(name);
        textCol.add(desc);

        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 95));
        row.setPreferredSize(new Dimension(0, 95));
        row.add(iconBox, BorderLayout.WEST);
        row.add(textCol, BorderLayout.CENTER);
        return row;
    }

    /** Finds the installed route (if any) whose hubSourceId matches this catalog entry. Reading
     *  the real route list as the source of truth means there is no separate persisted "installed"
     *  set to drift out of sync -- e.g. if the user deletes the route manually from their list, the
     *  button correctly reverts to Install with no extra bookkeeping. */
    private com.routeplanner.model.Route findInstalled(HubRouteEntry entry) {
        for (com.routeplanner.model.Route r : plugin.getRoutes()) {
            if (entry.id.equals(r.getHubSourceId())) return r;
        }
        return null;
    }

    /** Install/Remove control. Green "+" when not installed; red "-" when it is, matching the
     *  route's real presence in plugin.getRoutes() rather than separately tracked state. */
    private JLabel buildInstallControl(HubRouteEntry entry) {
        JLabel btn = new JLabel();
        btn.setOpaque(true);
        btn.setFont(btn.getFont().deriveFont(Font.BOLD, 13f));
        btn.setHorizontalAlignment(SwingConstants.CENTER);
        btn.setCursor(new Cursor(Cursor.HAND_CURSOR));
        btn.addMouseListener(new java.awt.event.MouseAdapter() {
            @Override
            public void mouseClicked(java.awt.event.MouseEvent e) {
                com.routeplanner.model.Route existing = findInstalled(entry);
                if (existing != null) {
                    removeInstalled(entry, existing, btn);
                } else {
                    installEntry(entry, btn);
                }
            }
        });
        refreshInstallControl(btn, entry);
        return btn;
    }

    /** Sets the control's icon/colors/tooltip to match whether entry is currently installed. */
    private void refreshInstallControl(JLabel btn, HubRouteEntry entry) {
        boolean installed = findInstalled(entry) != null;
        if (installed) {
            btn.setText("\u2212"); // minus sign
            btn.setForeground(new Color(224, 159, 159));
            btn.setBackground(new Color(74, 46, 46));
            btn.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(new Color(107, 63, 63), 1),
                new EmptyBorder(1, 8, 1, 8)));
            btn.setToolTipText("Remove this route");
        } else {
            btn.setText("+");
            btn.setForeground(new Color(159, 224, 159));
            btn.setBackground(new Color(46, 74, 46));
            btn.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(new Color(63, 107, 63), 1),
                new EmptyBorder(1, 8, 1, 8)));
            btn.setToolTipText("Install this route");
        }
    }

    /** Fetches the route file, independently re-validates it, and on success installs it via the
     *  exact same add/save/activate sequence file-import uses -- so a hub-installed route behaves
     *  identically to a manually imported one from that point on. Runs off the EDT. */
    private void installEntry(HubRouteEntry entry, JLabel btn) {
        btn.setEnabled(false);
        new SwingWorker<Void, Void>() {
            private String failureMessage;
            private com.routeplanner.model.Route parsedRoute;

            @Override
            protected Void doInBackground() {
                try {
                    String json = catalog.fetchRouteJson(entry.file);
                    com.routeplanner.model.Route route = plugin.getRouteGson().fromJson(json, com.routeplanner.model.Route.class);
                    if (route == null) {
                        failureMessage = "The route file is empty or malformed.";
                        return null;
                    }
                    route.migrateIfNeeded();
                    String err = validateFetchedRoute(route);
                    if (err != null) {
                        failureMessage = "This route couldn't be installed: " + err;
                        return null;
                    }
                    route.setHubSourceId(entry.id);
                    String name = route.getName();
                    boolean exists = plugin.getRoutes().stream().anyMatch(r -> r.getName().equalsIgnoreCase(name));
                    if (exists) route.setName(name + " (Hub)");
                    parsedRoute = route;
                } catch (HubFetchException e) {
                    failureMessage = e.getMessage();
                } catch (Exception e) {
                    log.warn("Failed to install hub route {}", entry.id, e);
                    failureMessage = "Something went wrong installing this route.";
                }
                return null;
            }

            @Override
            protected void done() {
                btn.setEnabled(true);
                if (failureMessage != null) {
                    JOptionPane.showMessageDialog(RouteHubPanel.this, failureMessage,
                        "Install failed", JOptionPane.WARNING_MESSAGE);
                    return;
                }
                plugin.getRoutes().add(parsedRoute);
                plugin.saveRoutesPublic();
                plugin.setActiveRoute(parsedRoute);
                refreshInstallControl(btn, entry);
            }
        }.execute();
    }

    /** Removes a hub-installed route. Delegates to plugin.deleteRoute(), the same path the normal
     *  route-list "Delete Route" menu item uses -- that method also clears the active route if it
     *  matched, forgets its undo/redo history, and refreshes the main panel. A bare
     *  routes.remove(route) skips all of that, which is what originally left stale step data
     *  visible after a hub removal: the main panel was never told to refresh. */
    private void removeInstalled(HubRouteEntry entry, com.routeplanner.model.Route route, JLabel btn) {
        int confirm = JOptionPane.showConfirmDialog(this,
            "Remove \"" + route.getName() + "\" from your routes?",
            "Remove route", JOptionPane.YES_NO_OPTION);
        if (confirm != JOptionPane.YES_OPTION) return;

        plugin.deleteRoute(route);
        refreshInstallControl(btn, entry);
    }

    /** Entry text is already link-scanned by HubRouteEntry.validate(), but it is still rendered
     *  inside an HTML-interpreting JLabel, so escape markup characters to prevent malformed or
     *  unexpected HTML from a catalog entry affecting the label\'s rendering. */
    private static String escape(String s) {
        if (s == null) return "";
        return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }
}

package com.routeplanner.model;

import com.google.gson.annotations.SerializedName;
import lombok.Data;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.function.Predicate;

@Data
public class Route {
    private String name;
    private List<RouteSection> sections = new ArrayList<>();

    /** Set only when this route was installed from the Route Hub; holds the hub catalog's entry id.
     *  Null for manually created or file-imported routes. This is how the browse panel knows a route
     *  is already installed (and can offer Remove instead of Install) without a second, separate
     *  persisted set that could drift out of sync with the real route list. */
    private String hubSourceId;
    private boolean repeatable = false; // if true, resets and restarts when last step completes

    // Legacy flat-step format; migrated into a default section on load.
    @SerializedName("steps")
    private List<RouteStep> legacySteps;

    public Route(String name) {
        this.name = name;
    }

    public List<RouteStep> getAllSteps() {
        List<RouteStep> all = new ArrayList<>();
        if (sections != null) {
            for (RouteSection sec : sections) {
                if (sec.getSteps() != null) all.addAll(sec.getSteps());
            }
        }
        return all;
    }

    /** Flattened read accessor used across the codebase. */
    public List<RouteStep> getSteps() {
        return getAllSteps();
    }

    public void migrateIfNeeded() {
        if (sections == null) sections = new ArrayList<>();
        if (sections.isEmpty() && legacySteps != null && !legacySteps.isEmpty()) {
            RouteSection def = new RouteSection(UUID.randomUUID().toString(), "Steps");
            def.getSteps().addAll(legacySteps);
            sections.add(def);
        }
        legacySteps = null;
        // v1.2: old agility steps (StepType.AGILITY, now removed) deserialize with type==null.
        // Convert them to the new skilling form (skill=AGILITY) + course start location.
        for (RouteSection sec : sections) {
            if (sec.getSteps() == null) continue;
            for (RouteStep st : sec.getSteps()) {
                if (st.getType() == null && st.getAgilityCourse() != null) {
                    st.setType(StepType.SKILLING);
                    st.setSkillingSkill("AGILITY");
                    st.setSkillingGoalType(st.getAgilityGoalType() != null ? st.getAgilityGoalType() : "LEVEL");
                    st.setSkillingGoalValue(st.getAgilityGoalValue());
                    net.runelite.api.coords.WorldPoint loc =
                        com.routeplanner.agility.AgilityCoursePresets.startLocation(st.getAgilityCourse());
                    if (loc != null && st.getWorldPoint() == null) st.setWorldPoint(loc);
                    if (st.getName() == null || st.getName().isEmpty()) {
                        st.setName("Agility: " + st.getAgilityCourse());
                    }
                }
            }
        }
    }

    public RouteSection findSection(String id) {
        if (id == null || sections == null) return null;
        for (RouteSection s : sections) if (id.equals(s.getId())) return s;
        return null;
    }

    public RouteSection ensureLastSection() {
        if (sections == null) sections = new ArrayList<>();
        if (sections.isEmpty()) {
            sections.add(new RouteSection(UUID.randomUUID().toString(), "Section 1"));
        }
        return sections.get(sections.size() - 1);
    }

    public void addStepToSection(RouteStep step, String sectionId) {
        RouteSection sec = findSection(sectionId);
        if (sec == null) sec = ensureLastSection();
        step.setSectionId(sec.getId());
        sec.getSteps().add(step);
    }

    public void addStepToLastSection(RouteStep step) {
        RouteSection sec = ensureLastSection();
        step.setSectionId(sec.getId());
        sec.getSteps().add(step);
    }

    public void removeStep(RouteStep step) {
        if (sections == null) return;
        for (RouteSection sec : sections) {
            if (sec.getSteps() != null && sec.getSteps().remove(step)) return;
        }
    }

    public void removeStepsIf(Predicate<RouteStep> pred) {
        if (sections == null) return;
        for (RouteSection sec : sections) {
            if (sec.getSteps() != null) sec.getSteps().removeIf(pred);
        }
    }

    public RouteStep getActiveStep() {
        if (sections == null) return null;
        for (RouteSection sec : sections) {
            if (sec.getSteps() == null) continue;
            for (RouteStep s : sec.getSteps()) if (!s.isCompleted()) return s;
        }
        return null;
    }

    public boolean isComplete() {
        return getAllSteps().stream().allMatch(RouteStep::isCompleted);
    }

    public void resetProgress() {
        getAllSteps().forEach(s -> {
            s.setCompleted(false);
            s.setLocationReached(false);
            s.setBoarded(false);
            s.setSellArmed(false);
            s.setPickupBaseline(null);
            s.setBaselineAccount(0);
            s.setCatchProgress(0);
            s.setNpcKillProgress(0);
        });
    }
}

package com.routeplanner.model;

import lombok.Data;
import java.util.ArrayList;
import java.util.List;

@Data
public class RouteSection {
    private String id;
    private String name;
    private boolean collapsed;
    private List<RouteStep> steps = new ArrayList<>();

    public RouteSection() {}

    public RouteSection(String id, String name) {
        this.id = id;
        this.name = name;
        this.collapsed = false;
    }
}

package com.routeplanner.model;

import lombok.Data;
import net.runelite.api.coords.WorldPoint;

@Data
public class RouteStep {
    private String name;
    private StepType type;
    private WorldPoint worldPoint;
    private int targetId;
    private boolean completed;
    private transient boolean locationReached; // true once player reached worldPoint; nav visuals off (sticky)
    private String sectionId;   // which RouteSection this step belongs to

    // Agility task fields
    private String agilityCourse;
    private String agilityGoalType;
    private long agilityGoalValue;

    // Quest step fields
    private String questName;          // matches net.runelite.api.Quest enum name
    private boolean questComplete;     // true = auto-complete step when quest is FINISHED

    // Item/Bank step fields
    private String itemList;  // comma separated, / for alternatives e.g. "Spade,Rune pouch/Divine Rune pouch"
    private String itemMode = "BANK";  // "BANK" (fetch from bank), "SHOP" (buy), or "SELL" (sell to shop)
    private transient boolean sellArmed = false;  // SELL: true once items seen in inventory
    private java.util.Map<String, Long> pickupBaseline;  // PICKUP/SHOP: inventory counts when step became active
    // The account the step's baselines (pickupBaseline, skillingStartXp) were taken on when it became
    // active; 0 = not taken yet. Saved, so reloading keeps the progress; an imported route or another
    // account doesn't match, so those take their own.
    private long baselineAccount;

    /** PICKUP and SHOP count items gained since the step started, not items already carried. */
    public boolean countsGainedItems() {
        return "PICKUP".equals(itemMode) || "SHOP".equals(itemMode);
    }

    // Guided quest (Quest Helper) step fields
    private int questStopIndex = -1;   // flat step index to stop at, -1 = whole quest
    private String questStopText;       // display text of the stop step

    // Teleport step fields
    private String teleportSpell;     // spell name e.g. "Varrock Teleport"
    private net.runelite.api.coords.WorldPoint teleportDestination; // destination WorldPoint
    private int teleportSpellId;      // widget child ID for highlighting  // matches net.runelite.api.Quest enum name

    private String teleportMethod;    // Phase 2: "SPELL", "ITEM" or "NEXUS" (null = walk only)
    private String teleportItem;      // Phase 2: item name for ITEM teleports (e.g. "Amulet of glory")
    private String teleportNexus;     // NEXUS teleports: Portal Nexus destination as shown in its menu

    // Skilling step fields
    private String skillingSkill;      // e.g. "THIEVING"
    private String skillingGoalType;   // "XP_GAIN", "XP_TARGET", "LEVEL"
    private long skillingGoalValue;    // target value
    private long skillingStartXp;      // XP when step became active
    private long skillingProgress;     // current XP gained (for XP_GAIN)
    private String skillingTargetNpc;  // NPC to highlight (e.g. "Knight of Ardougne")
    private String skillingTargetObject; // game object to highlight (e.g. "Baker's stall")
    private String gearReminder; // fishing gear reminder (e.g. "Fly fishing rod, Feathers")
    private String herblorePotion; // potion for Herblore steps (drives the bank highlight)
    private String bankHighlightItems; // generic bank highlight for skilling steps (Cooking, etc.)
    private String inventoryHighlightItems; // items to outline in the inventory, e.g. "Cocktail shaker, Lemon"

    // Transition point: when set, this step has two phases.
    // Phase 1: path to transitionPoint (the staircase/ladder tile).
    // Phase 2: once player plane matches worldPoint plane, path to worldPoint.
    private WorldPoint transitionPoint;
    private int transitionObjectId = -1; // game object ID to highlight as the transition object (-1 = none)

    // Boarding point (Sailing): when set, the step starts by getting on a boat.
    // Phase 1: path to boardPoint (the dock by the gangplank) and highlight the gangplank.
    // Phase 2: once on the boat, path over the sea to worldPoint. With no worldPoint, boarding is the step.
    private WorldPoint boardPoint;
    private int boardObjectId = -1;      // the gangplank's object ID, if known (-1 = find it by name)
    private transient boolean boarded;   // true once the player got on a boat during this step

    // Catch goal (Sailing trawling): fish caught into the net, counted from the catch messages
    // since they never reach the inventory. Progress is saved so a reload carries on.
    private String catchFish;       // e.g. "Giant krill"
    private int catchGoal;          // how many to catch (0 = none)
    private int catchProgress;      // caught so far while this step is active

    public boolean hasCatchGoal() {
        return catchGoal > 0 && catchFish != null;
    }

    public boolean hasBoarding() {
        return boardPoint != null;
    }

    // Note step (informational, not tracked)
    private String noteText;
    private boolean noteAutoComplete; // NOTE step: done on arrival, no manual tick (off = wait for the tick)
    private String npcHighlight; // NOTE step: optional NPC name to highlight
    private boolean highlightEnabled; // master toggle: light up this step's in-game targets (default off)
    private String recipeLabel; // editor: the exact recipe/method dropdown label chosen (for reverse-prefill)
    private int npcKillCount;    // NOTE step: kills to auto-complete (0 = manual)
    private transient int npcKillProgress; // kills so far while this step is active
    private String dialogOptions;          // NOTE step: chat option sequence to highlight, e.g. "3,1""

    public RouteStep(String name, StepType type, WorldPoint worldPoint, int targetId) {
        this.name = name;
        this.type = type;
        this.worldPoint = worldPoint;
        this.targetId = targetId;
        this.completed = false;
    }

    // Constructor for skilling steps
    public RouteStep(String name, String skill, String goalType, long goalValue, long startXp) {
        this.name = name;
        this.type = StepType.SKILLING;
        this.worldPoint = null;
        this.targetId = -1;
        this.completed = false;
        this.skillingSkill = skill;
        this.skillingGoalType = goalType;
        this.skillingGoalValue = goalValue;
        this.skillingStartXp = startXp;
        this.skillingProgress = 0;
    }

    // --- Component presence helpers (Phase 2) ---
    // A component is a view over fields the step already carries.
    // Descriptive only; nothing branches on these yet.

    public boolean hasLocation() {
        return worldPoint != null || teleportMethod != null;
    }

    public boolean hasItems() {
        return (itemList != null && !itemList.trim().isEmpty())
            || "DEPOSIT_ALL".equals(itemMode);
    }

    public boolean hasSkillGoal() {
        return skillingSkill != null && !skillingSkill.trim().isEmpty();
    }

    public boolean hasHighlight() {
        return (skillingTargetNpc != null && !skillingTargetNpc.trim().isEmpty())
            || (skillingTargetObject != null && !skillingTargetObject.trim().isEmpty())
            || (npcHighlight != null && !npcHighlight.trim().isEmpty());
    }

    public boolean hasQuest() {
        return questName != null && !questName.trim().isEmpty();
    }

    public boolean hasNote() {
        return noteText != null && !noteText.trim().isEmpty();
    }
}

package com.routeplanner.model;

public enum StepType {
    LOCATION,
    ITEM,
    SKILLING,
    TELEPORT,
    NOTE
}

package com.routeplanner.quest;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;

/**
 * On a step that completes with a whole quest, highlights that quest in the open quest list,
 * where Quest Helper's right-click "Start Quest Helper" loads it. Quest Helper takes no messages
 * from other plugins, so pointing at its menu option is as far as this can go.
 * Highlight only: never clicks.
 */
@Singleton
public class QuestListOverlay extends Overlay {
    private final Client client;
    private final RoutePlannerPlugin plugin;

    @Inject
    public QuestListOverlay(Client client, RoutePlannerPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || !step.hasQuest() || !step.isQuestComplete()) return null;
        String quest = questName(step.getQuestName());
        if (quest == null) return null;

        Widget target = questRow(quest);
        if (target == null) return null;
        Rectangle b = target.getBounds();
        if (b == null) return null;

        Color outline = plugin.getConfig().npcHighlightColor();
        graphics.setColor(outline);
        graphics.setStroke(new BasicStroke(2));
        graphics.drawRect(b.x - 1, b.y - 1, b.width + 2, b.height + 2);
        graphics.setColor(com.routeplanner.util.HighlightColors.fill(outline));
        graphics.fillRect(b.x - 1, b.y - 1, b.width + 2, b.height + 2);
        return null;
    }

    /** The quest's name as the quest list shows it, from its Quest enum name. */
    private static String questName(String enumName) {
        try {
            return Quest.valueOf(enumName).getName();
        } catch (IllegalArgumentException e) {
            return null;
        }
    }

    /** The quest's row in the open quest list, the scrollbar if it's scrolled out of view, or null. */
    private Widget questRow(String quest) {
        Widget list = visible(InterfaceID.Questlist.LIST);
        Widget view = visible(InterfaceID.Questlist.LIST_CONTAINER);
        if (list == null || view == null) return null;
        Widget[] rows = list.getDynamicChildren();
        if (rows == null) return null;
        for (Widget row : rows) {
            if (row == null || row.isHidden() || row.getText() == null) continue;
            if (!Text.removeTags(row.getText()).trim().equalsIgnoreCase(quest)) continue;
            Rectangle r = row.getBounds();
            if (view.getBounds().contains(r.getCenterX(), r.getCenterY())) return row;
            return visible(InterfaceID.Questlist.SCROLLBAR);
        }
        return null;
    }

    private Widget visible(int componentId) {
        Widget w = client.getWidget(componentId);
        return w == null || w.isHidden() ? null : w;
    }
}

package com.routeplanner.record;

import com.routeplanner.agility.AgilityCourse;
import com.routeplanner.agility.AgilityCoursePresets;
import com.routeplanner.agility.AgilityObstacle;
import com.routeplanner.model.RouteStep;
import com.routeplanner.util.LocationNames;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;

import java.util.*;

/**
 * The skilling and combat half of Record mode: turns XP drops and kills into steps.
 *
 *  - Gathering (woodcutting, mining, fishing, hunter): the items you got become a PICKUP-style
 *    item count ("28 Yew logs"), with the tree / rock / fishing spot as the highlight target.
 *  - Agility: XP on a known course becomes an XP goal on that course, started at its start tile.
 *  - Any other skill: the XP gained becomes an "Gain XP amount" goal, with the NPC or object
 *    you were using (a pickpocket NPC, a stall, a range) as the highlight target.
 *  - Kills: NPCs you were fighting that die become a kill-count step highlighting that NPC.
 *
 * Repeating the same thing in the same spot adds to one step rather than making many. Like the
 * rest of the recorder it only reads game state; it never acts for the player.
 */
class ActivityRecorder {

    /** Same activity if the next XP / kill comes within this many tiles of where it started. */
    private static final int ACTIVITY_RADIUS = 15;
    /** While XP keeps coming this recently, the player is busy here: no idle location steps. */
    private static final int BUSY_TICKS = 30;
    /** A clicked NPC / object explains XP that arrives within this many ticks. */
    private static final int TARGET_WINDOW_TICKS = 30;
    /** Teleport spells give Magic XP; ignore Magic this soon after a teleport click. */
    private static final int TELEPORT_XP_TICKS = 10;

    private static final Set<Skill> GATHERING = EnumSet.of(
        Skill.WOODCUTTING, Skill.MINING, Skill.FISHING, Skill.HUNTER);
    /** Combat XP is recorded as kills instead. */
    private static final Set<Skill> COMBAT = EnumSet.of(
        Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED, Skill.HITPOINTS, Skill.SLAYER);

    private final Client client;
    private final RouteRecorder host;

    private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);

    /** The NPC or object the player last used. */
    private String targetName;
    private String targetOption;
    private boolean targetIsNpc;
    private int targetObjectId = -1;
    private WorldPoint targetPos;   // where the player stood when they clicked it
    private WorldPoint targetObjectTile; // the clicked object's own tile, when it was an object
    private int targetTick = -1000;
    private int teleportTick = -1000;
    private int combatTick = -1000;
    /** The NPC last clicked to attack, and when: a kill counts even if the target just changed. */
    private String attackedName;
    private int attackedTick = -1000;

    /** The step being added to, and what it's for. */
    private RouteStep step;
    private Skill skill;            // null for a kill step
    private String stepTarget;      // what it highlights (NPC / object / course name)
    private WorldPoint stepPos;
    private long stepXp;
    private int lastXpTick = -1000;
    private int stepBeganTick = -1000;
    /** XP added to the current step in the last few ticks, so a quest reward can be taken back out. */
    private long recentXp;
    private int recentXpTick = -1000;
    private int ignoreXpUntil = -1000;
    private final Map<String, Long> gathered = new LinkedHashMap<>();
    /** Items gained this tick before the XP drop that explains them arrived. */
    private final Map<String, Long> pendingGains = new LinkedHashMap<>();
    private int pendingTick = -1;
    /** Salvaging, sorting and trawling (Sailing), which run as sessions. */
    private final SailingActivity sailing;

    ActivityRecorder(Client client, RouteRecorder host) {
        this.client = client;
        this.host = host;
        this.sailing = new SailingActivity(client, host);
    }

    void start() {
        xp.clear();
        for (Skill s : Skill.values()) {
            if (s == Skill.OVERALL) continue;
            xp.put(s, client.getSkillExperience(s));
        }
        targetName = null;
        attackedName = null;
        targetTick = teleportTick = combatTick = lastXpTick = attackedTick = -1000;
        step = null;
        gathered.clear();
        pendingGains.clear();
        sailing.start();
    }

    /** An NPC or object was clicked (not walking or examining). */
    void onTargetClick(String option, String target, boolean npc, int objectId, WorldPoint at, WorldPoint objectTile, int tick) {
        targetPos = at;
        targetObjectTile = objectTile;
        targetObjectId = npc ? -1 : objectId;
        targetName = cleanName(target);
        targetOption = option;
        targetIsNpc = npc;
        targetTick = tick;
        if ("Attack".equalsIgnoreCase(option) && npc) {
            attackedName = cleanName(target);
            attackedTick = tick;
        }
        // A ship's cannon fights too: its hits give Sailing XP the way an attack gives Ranged
        if ("Attack".equalsIgnoreCase(option)
            || ("Operate".equalsIgnoreCase(option) && target != null && target.toLowerCase().contains("cannon"))) {
            combatTick = tick;
        }
        sailing.onTargetClick(option, target, at, tick);
    }

    /** Fish caught by a trawling net: they make the trawl's catch step (see SailingActivity). */
    void onCatch(String fish, int count, WorldPoint pos, int tick) {
        if (sailing.onCatch(fish, count, pos, tick)) step = null; // a catch step isn't an XP activity
    }

    /** "Lower net" in the Sailing panel: trawling is on. */
    void onLowerNet(int tick) {
        sailing.onLowerNet(tick);
    }

    void onTeleportClick(int tick) {
        teleportTick = tick;
    }

    /** True while the player is busy with an activity here, so standing still isn't a new stop. */
    boolean isBusy(WorldPoint pos, int tick) {
        // Mid-fight: standing (or stopping the boat) between kills isn't a stop either; nor is
        // waiting for a shoal mid-trawl
        if (tick - combatTick <= BUSY_TICKS) return true;
        if (sailing.isBusy(tick)) return true;
        if (step == null || host.lastDraft() != step || tick - lastXpTick > BUSY_TICKS) return false;
        if (skill == Skill.AGILITY) return true; // a lap ranges all over (and up) the course
        return pos == null || stepPos == null || pos.distanceTo2D(stepPos) <= ACTIVITY_RADIUS;
    }

    /**
     * The course an obstacle belongs to, by its object id (courses can span several map
     * regions, so the id is the reliable part), falling back to the region the player is in.
     */
    private static AgilityCourse courseFor(int objectId, WorldPoint pos) {
        if (objectId > 0) {
            for (AgilityCourse c : AgilityCoursePresets.ALL) {
                for (AgilityObstacle o : c.getObstacles()) if (o.matchesId(objectId)) return c;
            }
        }
        return pos == null ? null : AgilityCoursePresets.getCourseForRegion(pos.getRegionID());
    }

    /** Running a course right now: agility XP came recently. */
    boolean runningCourse(WorldPoint pos, int tick) {
        return skill == Skill.AGILITY && step != null && host.lastDraft() == step && tick - lastXpTick <= BUSY_TICKS;
    }

    /** True when the player is running a known agility course (its jumps and climbs aren't travel). */
    boolean onAgilityCourse(WorldPoint pos, int clickedObjectId, int tick) {
        // Mid-lap any obstacle counts, even one the course table doesn't list by id.
        if (runningCourse(pos, tick)) return true;
        for (AgilityCourse c : AgilityCoursePresets.ALL) {
            for (AgilityObstacle o : c.getObstacles()) if (o.matchesId(clickedObjectId)) return true;
        }
        return false;
    }

    void onXp(Skill s, int newXp, WorldPoint pos, int tick) {
        Integer old = xp.put(s, newXp);
        if (old == null || old <= 0 || newXp <= old) return;
        long gained = newXp - old;
        if (tick <= ignoreXpUntil) { host.trace("XP+" + gained + " " + s + " ignored (quest reward)"); return; }
        if (COMBAT.contains(s)) { host.trace("XP+" + gained + " " + s + " ignored (combat)"); return; }
        if (s == Skill.MAGIC && (tick - teleportTick <= TELEPORT_XP_TICKS || tick - combatTick <= TARGET_WINDOW_TICKS)) {
            host.trace("XP+" + gained + " MAGIC ignored (teleport/combat)");
            return;
        }
        // Trawling: its XP (the net's Sailing, the catches' Fishing) belongs to it; the catches make the
        // step (see onCatch), since the fish are the point and a crewmate's catches give no Fishing XP
        if (sailing.absorbTrawlXp(s, tick)) return;
        // Fighting at sea: the kills make the step ("Kill 3 Vampyre kraken"), like any combat XP
        if (s == Skill.SAILING && tick - combatTick <= TARGET_WINDOW_TICKS) {
            host.trace("XP+" + gained + " SAILING ignored (sea combat, recorded as kills)");
            return;
        }
        // Salvaging or sorting: a session; otherwise Sailing XP only counts after clicking a wreck
        String session = s == Skill.SAILING ? sailing.session(pos, tick) : null;
        boolean anywhere = sailing.anywhere(session);
        if (s == Skill.SAILING && session == null
                && (tick - targetTick > TARGET_WINDOW_TICKS || !SailingActivity.trainingClick(targetOption, targetName))) {
            host.trace("XP+" + gained + " SAILING ignored (travel or boat facility, last target=" + targetOption + " " + targetName + ")");
            return;
        }

        String target = session != null ? session : tick - targetTick <= TARGET_WINDOW_TICKS ? targetName : null;
        AgilityCourse course = s == Skill.AGILITY
            ? courseFor(tick - targetTick <= TARGET_WINDOW_TICKS ? targetObjectId : -1, pos) : null;
        if (course != null) target = course.getName();

        // A lap that began on an obstacle the course list doesn't know: once a later obstacle
        // names the course, the step takes it on instead of splitting the lap.
        if (course != null && s == Skill.AGILITY && skill == s && step != null && host.lastDraft() == step
            && stepTarget == null && tick - lastXpTick <= BUSY_TICKS) {
            stepTarget = course.getName();
            step.setRecipeLabel(course.getName());
        }
        // Back to this wreck's Salvage or Sort step after the other one (or a chat) came in between
        RouteStep resume = sailing.sessionStep(session);
        boolean resumed = false;
        if (resume != null && resume != step) {
            step = resume;
            skill = s;
            stepTarget = target;
            stepPos = resume.getWorldPoint();
            stepXp = sailing.xp(resume);
            gathered.clear();
            resumed = true;
        }
        boolean same = resumed || step != null && host.lastDraft() == step && skill == s
            && (course != null ? course.getName().equals(stepTarget)
                // A course the plugin doesn't know: every obstacle has its own name, so keep
                // the lap together while the XP keeps coming instead of matching the target.
                : s == Skill.AGILITY ? stepTarget == null && tick - lastXpTick <= BUSY_TICKS
                : (anywhere || near(pos)) && (target == null || target.equals(stepTarget)));
        if (s == Skill.AGILITY && course == null) target = null;
        host.trace("XP+" + gained + " " + s + " target=" + target + " course=" + (course == null ? null : course.getName())
            + " -> " + (same ? "add to current step" : "new activity (current=" + RouteRecorder.describeStep(step)
            + ", lastDraftIsCurrent=" + (step != null && host.lastDraft() == step) + ")"));
        if (!same) {
            begin(s, target, course, anywhere ? null : pos);
            sailing.began(session, step);
        }
        stepXp += gained;
        sailing.recordXp(step, stepXp);
        if (tick - recentXpTick > 2) recentXp = 0;
        recentXp += gained;
        recentXpTick = tick;
        lastXpTick = tick;
        if (GATHERING.contains(s) && pendingTick >= tick - 1) {
            pendingGains.forEach((k, v) -> gathered.merge(k, v, Long::sum));
        }
        pendingGains.clear();
        refresh(pos);
    }

    /**
     * A quest was just finished: its reward XP isn't training. XP that arrived in the last couple
     * of ticks is taken back off the step (removing the step if that was all it had), and XP
     * for a few ticks more is ignored (reward lamps and the scroll can come slightly later).
     */
    void onQuestComplete(int tick) {
        ignoreXpUntil = tick + 10;
        if (step == null || tick - recentXpTick > 2 || recentXp <= 0) return;
        stepXp -= recentXp;
        recentXp = 0;
        host.trace("QUEST reward XP removed from " + RouteRecorder.describeStep(step));
        if (stepXp <= 0 && tick - stepBeganTick <= 2) {
            host.removeDraft(step);
            step = null;
        } else if (stepXp > 0) {
            refresh(null);
        }
    }

    /** Items arrived in the inventory that weren't picked up, bought or withdrawn. */
    void onItemsGained(Map<String, Long> gains, int tick) {
        if (step != null && GATHERING.contains(skill) && host.lastDraft() == step && tick - lastXpTick <= 2) {
            gains.forEach((k, v) -> gathered.merge(k, v, Long::sum));
            refresh(null);
            return;
        }
        // The XP for these may come later this tick: hold on to them until it does.
        if (pendingTick != tick) pendingGains.clear();
        gains.forEach((k, v) -> pendingGains.merge(k, v, Long::sum));
        pendingTick = tick;
    }

    /** An NPC died; count it if the player was fighting it. */
    void onNpcDeath(NPC npc, WorldPoint pos) {
        Player me = client.getLocalPlayer();
        if (me == null || npc.getName() == null) return;
        String name = cleanName(npc.getName());
        // Ours if we were fighting it, or it's what we've been attacking: with several about (or a
        // ship's cannon landing the last hit) the target has often moved on to the next one already.
        boolean fighting = me.getInteracting() == npc || npc.getInteracting() == me;
        // ...but not one another player was fighting (sea creatures go for the boat's crew, NPCs)
        boolean otherPlayers = npc.getInteracting() instanceof Player && npc.getInteracting() != me;
        boolean attacked = name.equalsIgnoreCase(attackedName) && host.currentTick() - attackedTick <= TARGET_WINDOW_TICKS
            && !otherPlayers;
        if (!fighting && !attacked) {
            host.trace("DEATH '" + name + "' not ours (attacked=" + attackedName + " "
                + (host.currentTick() - attackedTick) + " ticks ago, its target="
                + (npc.getInteracting() == null ? "none" : npc.getInteracting().getName()) + ")");
            return;
        }
        RouteStep last = host.lastDraft();
        boolean same = last != null && name.equalsIgnoreCase(last.getNpcHighlight()) && last.getNpcKillCount() > 0
            && host.isNear(last, pos, ACTIVITY_RADIUS);
        if (!same) {
            // Loot picked up after a kill sits on the same step, so fighting and looting stay together.
            last = host.stepAt(pos, "Kill " + name + LocationNames.at(pos), ActivityRecorder::canTakeKills);
            last.setNpcHighlight(name);
            last.setNpcKillCount(0);
            step = null; // a kill step isn't an XP activity
        }
        last.setNpcKillCount(last.getNpcKillCount() + 1);
        last.setNoteText("Kill " + last.getNpcKillCount() + " " + name + ".");
    }

    private static boolean canTakeKills(RouteStep s) {
        return "PICKUP".equals(s.getItemMode()) && !s.hasSkillGoal()
            && s.getSkillingTargetNpc() == null && s.getSkillingTargetObject() == null && !s.hasNote();
    }

    private void begin(Skill s, String target, AgilityCourse course, WorldPoint pos) {
        WorldPoint at = pos;
        if (s == Skill.AGILITY) {
            // Best: the course's first obstacle as actually clicked. Then the course preset.
            WorldPoint startTile = null;
            if (course != null && targetObjectTile != null && !course.getObstacles().isEmpty()
                && course.getObstacles().get(0).matchesId(targetObjectId)) startTile = targetObjectTile;
            if (startTile == null && course != null) startTile = AgilityCoursePresets.startLocation(course.getName());
            // No known start: the lap starts where its first obstacle was clicked (on the ground,
            // not wherever on the rooftops the first XP landed you).
            if (startTile == null && targetPos != null) startTile = targetPos;
            if (startTile != null) at = startTile;
        }
        step = host.stepAt(at, "Train " + cap(s.name()) + LocationNames.at(pos), null);
        skill = s;
        stepTarget = target;
        stepPos = pos;
        stepXp = 0;
        stepBeganTick = host.currentTick();
        gathered.clear();
        if (course != null) {
            step.setRecipeLabel(course.getName());
        } else if (SailingActivity.SALVAGING.equals(target) || SailingActivity.SORTING.equals(target)) {
            sailing.setUp(target, step);
        } else if (target != null) {
            if (targetIsNpc) step.setSkillingTargetNpc(target);
            else step.setSkillingTargetObject(target);
        }
    }

    /** Rewrite the step from what's been recorded so far. */
    private void refresh(WorldPoint pos) {
        WorldPoint where = stepPos != null ? stepPos : pos;
        String verb = targetOption != null && stepTarget != null && stepTarget.equals(targetName)
            ? targetOption : null;
        if (GATHERING.contains(skill) && !gathered.isEmpty()) {
            // Gathering is about what you come away with, so it's an item count.
            List<String> entries = new ArrayList<>();
            gathered.forEach((k, v) -> entries.add(v > 1 ? v + " " + k : k));
            step.setItemMode("PICKUP");
            step.setItemList(String.join(", ", entries));
            step.setSkillingSkill(null);
            step.setSkillingGoalType(null);
            step.setName((verb != null ? verb + " " + stepTarget : "Gather") + LocationNames.at(where));
            return;
        }
        step.setSkillingSkill(skill.name());
        step.setSkillingGoalType("XP_GAIN");
        step.setSkillingGoalValue(stepXp);
        step.setSkillingStartXp(0); // captured when the step becomes active during playback
        if (skill == Skill.AGILITY) {
            step.setName(step.getRecipeLabel() != null
                ? "Agility: " + step.getRecipeLabel() + " course" : "Agility" + LocationNames.at(where));
        } else if (sailing.name(stepTarget, step, stepPos, where) != null) {
            step.setName(sailing.name(stepTarget, step, stepPos, where));
        } else if (verb != null) {
            step.setName(verb + " " + stepTarget + LocationNames.at(where));
        } else {
            step.setName("Train " + cap(skill.name()) + LocationNames.at(where));
        }
    }

    private boolean near(WorldPoint pos) {
        if (pos == null || stepPos == null) return pos == null && stepPos == null;
        return pos.distanceTo2D(stepPos) <= ACTIVITY_RADIUS;
    }

    /** "Man  (level-2)" -> "Man". */
    private static String cleanName(String raw) {
        if (raw == null) return null;
        // "Use Raw shrimps -> Range": the thing used on is the target.
        int arrow = raw.lastIndexOf("->");
        if (arrow >= 0) raw = raw.substring(arrow + 2);
        return raw.replaceAll("\\s*\\(level-\\d+\\)", "").trim();
    }

    private static String cap(String s) {
        return s.isEmpty() ? s : s.substring(0, 1).toUpperCase() + s.substring(1).toLowerCase();
    }

}

package com.routeplanner.record;

import com.routeplanner.dialog.DialogOptions;
import com.routeplanner.model.RouteStep;
import com.routeplanner.util.LocationNames;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

import java.util.ArrayList;
import java.util.List;

/**
 * The conversation half of Record mode: dialogue choices and finished quests.
 *
 *  - Talking to an NPC becomes a "Talk to ..." step that highlights them.
 *  - Each option picked in a chat menu is added to that step's dialogue sequence ("2,1,3"),
 *    which playback highlights in turn. A mouse pick is read from the clicked line; a keyboard
 *    pick from the player repeating that line in the next chat box. A pick that can't be read
 *    either way is recorded as 0 (no highlight) so the rest of the sequence stays in step.
 *  - "Congratulations, you've completed a quest" puts that quest on the step, set to complete
 *    when the quest is finished.
 *
 * Like the rest of the recorder it only reads what's on screen; it never answers for the player.
 */
class DialogRecorder {

    /** A Talk-to click explains a conversation that opens within this many ticks (walking there). */
    private static final int TALK_WINDOW_TICKS = 30;
    /** After a menu closes, the player's echo of their choice shows up within this many ticks. */
    private static final int ECHO_WINDOW_TICKS = 4;
    /** The conversation is over once no chat box has shown for this many ticks. */
    private static final int END_TICKS = 3;
    private static final int[] DIALOGUE_GROUPS = {219, 231, 217, 229, 233, 193};
    private static final String QUEST_DONE = "congratulations, you've completed a quest:";
    private static final String MINIQUEST_DONE = "congratulations, you've completed a miniquest:";

    private final Client client;
    private final RouteRecorder host;

    private String talkNpc;
    private int talkTick = -1000;

    private boolean inConversation;
    /** A crewmate on the boat was just clicked; the chat it opens isn't part of the route. */
    private int crewTick = -1000;
    private boolean muted;
    private int lastOpenTick;
    private RouteStep step;          // the step this conversation's picks go on (made on demand)
    private String convNpc;

    /** The options menu currently (or last) on screen, and whether its pick is known yet. */
    private List<String> menu = new ArrayList<>();
    private boolean menuOpen;
    private boolean picked;
    private int closedTick = -1;

    DialogRecorder(Client client, RouteRecorder host) {
        this.client = client;
        this.host = host;
    }

    void start() {
        talkNpc = null;
        talkTick = -1000;
        crewTick = -1000;
        muted = false;
        inConversation = false;
        step = null;
        menu = new ArrayList<>();
        menuOpen = false;
        closedTick = -1;
    }

    /** An NPC was clicked; "Talk-to" means a conversation is coming. */
    /**
     * A crewmate or a facility on the player's boat was clicked: the conversation or menu that follows
     * (chatting to the crew, where to send the net's fish) isn't recorded.
     */
    void onCrewClick(int tick) {
        crewTick = tick;
        talkNpc = null;
    }

    void onNpcClick(String option, String target, int tick) {
        if (!"Talk-to".equalsIgnoreCase(option)) return;
        talkNpc = target.replaceAll("\\s*\\(level-\\d+\\)", "").trim();
        talkTick = tick;
    }

    /** A click inside the options menu: the clicked line is the pick. */
    void onMenuClick(int widgetId, int childIndex, WorldPoint pos) {
        if (widgetId != InterfaceID.Chatmenu.OPTIONS || !menuOpen) return;
        Widget container = DialogOptions.container(client);
        Widget line = container != null && childIndex >= 0 ? container.getChild(childIndex) : null;
        String text = line != null ? DialogOptions.clean(line.getText()) : null;
        int idx = text == null ? -1 : menu.indexOf(text);
        host.trace("DIALOG click child=" + childIndex + " text='" + text + "' -> option " + (idx + 1));
        if (idx >= 0) pick(idx + 1, pos);
    }

    void onTick(WorldPoint pos, int tick) {
        List<String> now = DialogOptions.texts(client);
        boolean open = !now.isEmpty();

        // Picking a line (key or mouse) first swaps it for "Please wait..." in the same menu:
        // that's the pick. Keep the original lines as the menu so the swap isn't a new menu.
        int waiting = open && menuOpen ? waitIndex(menu, now) : -1;
        if (waiting >= 0) {
            if (!picked) {
                host.trace("DIALOG wait on line " + (waiting + 1) + " -> option " + (waiting + 1));
                pick(waiting + 1, pos);
            }
        } else if (open && menuOpen && !now.equals(menu)) {
            // A menu replaced straight by a different one: the old pick can't be read any more.
            resolveUnread(pos);
            menu = now;
            picked = false;
            host.trace("DIALOG menu " + menu);
        } else if (open && !menuOpen) {
            menu = now;
            picked = false;
            host.trace("DIALOG menu " + menu);
        } else if (!open && menuOpen && !picked) {
            closedTick = tick;          // pick still unknown: watch for the echo
        }
        menuOpen = open;

        // Keyboard picks: the player says the chosen line in the next chat box.
        if (!menuOpen && !picked && closedTick >= 0) {
            String said = playerLine();
            int idx = said == null ? -1 : indexOfSaid(said);
            if (idx >= 0) {
                host.trace("DIALOG echo '" + said + "' -> option " + (idx + 1));
                pick(idx + 1, pos);
            } else if (tick - closedTick > ECHO_WINDOW_TICKS) {
                resolveUnread(pos);
            }
        }

        boolean anyOpen = anyDialogueOpen();
        if (anyOpen) {
            if (!inConversation) beginConversation(pos, tick);
            lastOpenTick = tick;
        } else if (inConversation && tick - lastOpenTick > END_TICKS && closedTick < 0) {
            inConversation = false;
            muted = false;
            step = null;
            closedTick = -1;
        }
    }

    /** Game messages: a finished quest goes on the step where it was finished. True if it was one. */
    boolean onGameMessage(String message, WorldPoint pos) {
        String msg = Text.removeTags(message).trim();
        String lower = msg.toLowerCase();
        String name = null;
        if (lower.startsWith(QUEST_DONE)) name = msg.substring(QUEST_DONE.length()).trim();
        else if (lower.startsWith(MINIQUEST_DONE)) name = msg.substring(MINIQUEST_DONE.length()).trim();
        if (name == null) return false;
        Quest quest = questNamed(name);
        host.trace("QUEST done '" + name + "' -> " + quest);
        if (quest == null) return true;
        RouteStep target = step != null ? step : host.lastDraft();
        if (target == null || target.hasQuest() || !host.isNear(target, pos, 15)) {
            target = host.stepAt(pos, "Finish " + quest.getName() + LocationNames.at(pos));
        }
        target.setQuestName(quest.name());
        target.setQuestComplete(true);
        return true;
    }

    private void beginConversation(WorldPoint pos, int tick) {
        inConversation = true;
        step = null;
        if (tick - crewTick <= TALK_WINDOW_TICKS) {
            muted = true;
            host.trace("DIALOG with a crewmate, not recorded");
            return;
        }
        convNpc = tick - talkTick <= TALK_WINDOW_TICKS ? talkNpc : null;
        talkNpc = null;
        if (convNpc != null) {
            step = host.stepAt(pos, "Talk to " + convNpc + LocationNames.at(pos));
            if (step.getSkillingTargetNpc() == null) step.setSkillingTargetNpc(convNpc);
        }
        host.trace("DIALOG start npc=" + convNpc + " step=" + RouteRecorder.describeStep(step));
    }

    private void pick(int option, WorldPoint pos) {
        picked = true;
        closedTick = -1;
        if (muted) return;
        if (step == null) {
            // Options without a Talk-to first (an object, an item, a cutscene): still a step.
            step = host.stepAt(pos, "Dialogue" + LocationNames.at(pos));
        }
        String seq = step.getDialogOptions();
        step.setDialogOptions(seq == null || seq.trim().isEmpty() ? String.valueOf(option) : seq + "," + option);
        host.trace("DIALOG sequence now " + step.getDialogOptions());
    }

    /** The pick for the last menu couldn't be read: keep the sequence aligned with a blank. */
    private void resolveUnread(WorldPoint pos) {
        if (picked || menu.isEmpty()) { closedTick = -1; return; }
        host.trace("DIALOG pick for " + menu + " not readable, recorded as 0");
        pick(0, pos);
    }

    /** The line swapped for "Please wait..." if {@code now} is {@code before} with just that change, else -1. */
    private static int waitIndex(List<String> before, List<String> now) {
        if (before.size() != now.size()) return -1;
        int found = -1;
        for (int i = 0; i < now.size(); i++) {
            if (now.get(i).equals(before.get(i))) continue;
            if (found >= 0 || !now.get(i).toLowerCase().startsWith("please wait")) return -1;
            found = i;
        }
        return found;
    }

    private int indexOfSaid(String said) {
        String s = normalize(said);
        for (int i = 0; i < menu.size(); i++) {
            String o = normalize(menu.get(i));
            if (!o.isEmpty() && (s.equals(o) || s.startsWith(o) || o.startsWith(s))) return i;
        }
        return -1;
    }

    private static String normalize(String s) {
        return s.toLowerCase().replaceAll("[^a-z0-9 ]", "").replaceAll("\\s+", " ").trim();
    }

    /** What the player is saying in the chat box right now, if anything. */
    private String playerLine() {
        Widget w = client.getWidget(InterfaceID.ChatRight.TEXT);
        if (w == null || w.isHidden()) return null;
        String t = DialogOptions.clean(w.getText());
        return t.isEmpty() ? null : t;
    }

    private boolean anyDialogueOpen() {
        for (int g : DIALOGUE_GROUPS) {
            Widget w = client.getWidget(g, 0);
            if (w != null && !w.isHidden()) return true;
        }
        return false;
    }

    private static Quest questNamed(String name) {
        String n = name.replaceAll("[!.]+$", "").trim();
        for (Quest q : Quest.values()) if (q.getName().equalsIgnoreCase(n)) return q;
        return null;
    }

}

package com.routeplanner.record;

import com.routeplanner.bank.BankItemManager;
import com.routeplanner.model.RouteStep;
import com.routeplanner.util.LocationNames;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.game.ItemVariationMapping;

import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The item half of Record mode: turns inventory changes into item steps.
 *
 *  - Bank / seed vault: inventory when it opens vs when it closes. Items you end up holding
 *    more of become a BANK step; emptying your inventory becomes a DEPOSIT_ALL step.
 *  - Shop: items gained become a SHOP step, items given away a SELL step (currency ignored).
 *  - Ground items: a "Take" click followed by that item arriving becomes a PICKUP step.
 *
 * Quantities follow how each mode completes: BANK checks your inventory total, so it records
 * what you ended up holding; SHOP and PICKUP check what you gained, so they record that.
 * Read-only like the rest of the recorder: it only looks at the inventory and interfaces.
 */
class ItemRecorder {

    /** A "Take" click counts for the item that arrives within this many ticks (walking to it). */
    private static final int PICKUP_WINDOW_TICKS = 50;
    private static final int SHOP_GROUP = 300;
    private static final int SHOP_STOCK_CHILD = 16;
    /** Shop currencies: spent when buying, received when selling, never a step's item. */
    private static final Set<String> CURRENCIES = new HashSet<>(Arrays.asList(
        "coins", "tokkul", "trading sticks", "platinum token", "numulite", "golden nugget",
        "mark of grace", "stardust", "warrior guild token", "castle wars ticket"));
    private static final Pattern CHARGED = Pattern.compile("^(.+)\\((\\d+)\\)$");

    private final Client client;
    private final ItemManager itemManager;
    private final RouteRecorder host;

    private boolean bankOpen;
    private boolean shopOpen;
    /** Inventory when the current bank/shop session started (or last emptied). */
    private Inventory sessionStart;
    /** Inventory at the last change, for spotting what a pickup added. */
    private Inventory lastInv;
    /** Lowercased item name -> tick its "Take" was clicked. */
    private final Map<String, Integer> pendingTakes = new HashMap<>();
    /** Running totals for a PICKUP draft, so repeated pickups at one spot become one step. */
    private RouteStep pickupStep;
    private final Map<String, Long> pickupCounts = new LinkedHashMap<>();

    /** Inventory contents by recorded name (noted items count as their normal form). */
    private static final class Inventory {
        final Map<String, Long> qty = new LinkedHashMap<>();
        boolean isEmpty() { return qty.isEmpty(); }
        long get(String name) { return qty.getOrDefault(name, 0L); }
    }

    ItemRecorder(Client client, ItemManager itemManager, RouteRecorder host) {
        this.client = client;
        this.itemManager = itemManager;
        this.host = host;
    }

    void start() {
        bankOpen = false;
        shopOpen = false;
        sessionStart = null;
        lastInv = snapshot();
        pendingTakes.clear();
        pickupStep = null;
        pickupCounts.clear();
    }

    /** A ground item's "Take" was clicked. */
    void onTake(int itemId, int tick) {
        String name = keyOf(itemId);
        if (name != null) pendingTakes.put(name.toLowerCase(), tick);
    }

    /** Called every tick with the player's tile (null inside instances). */
    void onTick(WorldPoint pos) {
        boolean bankNow = visible(ComponentID.BANK_ITEM_CONTAINER) || visible(InterfaceID.SeedVault.OBJ_LIST);
        if (bankNow && !bankOpen) sessionStart = snapshot();
        if (bankNow && sessionStart != null && !sessionStart.isEmpty()) {
            // Emptied the inventory: that's its own step; what's withdrawn after counts from empty.
            Inventory now = snapshot();
            if (now.isEmpty()) {
                RouteStep step = host.stepAt(pos, "Deposit all" + LocationNames.at(pos));
                step.setItemMode("DEPOSIT_ALL");
                sessionStart = now;
            }
        }
        if (!bankNow && bankOpen) finishBank(pos);
        bankOpen = bankNow;

        boolean shopNow = visible(SHOP_GROUP, SHOP_STOCK_CHILD);
        if (shopNow && !shopOpen) sessionStart = snapshot();
        if (!shopNow && shopOpen) finishShop(pos);
        shopOpen = shopNow;
    }

    /** The inventory changed; outside a bank or shop, look for picked-up items. */
    void onInventoryChanged(WorldPoint pos, int tick) {
        Inventory now = snapshot();
        if (!bankOpen && !shopOpen && lastInv != null) {
            Map<String, Long> other = new LinkedHashMap<>();
            for (Map.Entry<String, Long> e : now.qty.entrySet()) {
                long gained = e.getValue() - lastInv.get(e.getKey());
                if (gained <= 0) continue;
                Integer took = pendingTakes.get(e.getKey().toLowerCase());
                if (took == null || tick - took > PICKUP_WINDOW_TICKS) other.put(e.getKey(), gained);
                else addPickup(pos, e.getKey(), gained);
            }
            if (!other.isEmpty()) host.onItemsGained(other, tick);
        }
        lastInv = now;
    }

    private void finishBank(WorldPoint pos) {
        Inventory end = snapshot();
        List<String> entries = new ArrayList<>();
        for (Map.Entry<String, Long> e : end.qty.entrySet()) {
            if (e.getValue() > sessionStart.get(e.getKey())) {
                entries.add(itemEntry(e.getKey(), e.getValue()));
            }
        }
        if (!entries.isEmpty()) {
            RouteStep step = host.stepAt(pos, "Withdraw from bank" + LocationNames.at(pos));
            step.setItemMode("BANK");
            step.setItemList(String.join(", ", entries));
        }
        sessionStart = null;
    }

    private void finishShop(WorldPoint pos) {
        Inventory end = snapshot();
        List<String> sold = new ArrayList<>();
        List<String> bought = new ArrayList<>();
        Set<String> names = new LinkedHashSet<>(sessionStart.qty.keySet());
        names.addAll(end.qty.keySet());
        for (String name : names) {
            if (CURRENCIES.contains(name.toLowerCase())) continue;
            long delta = end.get(name) - sessionStart.get(name);
            // SELL completes once none are left, so it lists names only.
            if (delta < 0) sold.add(itemEntry(name, 1));
            else if (delta > 0) bought.add(itemEntry(name, delta));
        }
        if (!sold.isEmpty()) {
            RouteStep step = host.stepAt(pos, "Sell to shop" + LocationNames.at(pos));
            step.setItemMode("SELL");
            step.setItemList(String.join(", ", sold));
        }
        if (!bought.isEmpty()) {
            RouteStep step = host.stepAt(pos, "Buy from shop" + LocationNames.at(pos));
            step.setItemMode("SHOP");
            step.setItemList(String.join(", ", bought));
        }
        sessionStart = null;
    }

    private void addPickup(WorldPoint pos, String name, long gained) {
        if (host.runningCourse(pos)) {
            // Marks of grace mid-lap: a bonus, not something the route should wait for.
            host.trace("PICKUP " + gained + " " + name + " ignored (agility lap)");
            return;
        }
        host.trace("PICKUP " + gained + " " + name);
        // Keep adding to the current pickup step while it's still the latest step nearby.
        // Loot from a kill step joins that step, so "kill and loot" stays one step.
        boolean renamable = true;
        if (pickupStep == null || host.lastDraft() != pickupStep || !host.isNear(pickupStep, pos)) {
            RouteStep last = host.lastDraft();
            if (last != null && last.getNpcKillCount() > 0 && !last.hasItems()
                && host.isNear(last, pos, 15)) {
                pickupStep = last;
            } else {
                pickupStep = host.stepAt(pos, "Pick up items" + LocationNames.at(pos));
            }
            pickupStep.setItemMode("PICKUP");
            pickupCounts.clear();
        }
        if (pickupStep.getNpcKillCount() > 0) renamable = false;
        pickupCounts.merge(name, gained, Long::sum);
        List<String> entries = new ArrayList<>();
        for (Map.Entry<String, Long> e : pickupCounts.entrySet()) {
            entries.add(itemEntry(e.getKey(), e.getValue()));
        }
        pickupStep.setItemList(String.join(", ", entries));
        if (renamable) pickupStep.setName(pickupCounts.size() == 1
            ? "Pick up " + name + LocationNames.at(pos)
            : "Pick up items" + LocationNames.at(pos));
    }

    /** One item-list entry, e.g. "28 Yew logs" or "3 Amulet of glory(*)". */
    private static String itemEntry(String name, long qty) {
        return qty > 1 ? qty + " " + name : name;
    }

    /**
     * The name an item is recorded under. Charged jewellery and gear (glory(4), games
     * necklace(8)) becomes "Amulet of glory(*)" so any charge counts and they add up; doses
     * (potions) keep their exact name, since a 1-dose potion isn't a full one.
     */
    private String keyOf(int itemId) {
        int id = itemManager.canonicalize(itemId);
        String name = nameOf(id);
        if (name == null) return null;
        Matcher m = CHARGED.matcher(name);
        if (!m.matches()) return name;
        ItemStats stats = itemManager.getItemStats(id);
        if (stats == null || !stats.isEquipable()) return name;
        int charges = 0;
        for (int v : ItemVariationMapping.getVariations(ItemVariationMapping.map(id))) {
            String n = nameOf(v);
            Matcher vm = n == null ? null : CHARGED.matcher(n);
            if (vm != null && vm.matches() && vm.group(1).equals(m.group(1))) charges++;
        }
        return charges >= 2 ? m.group(1) + BankItemManager.ANY_CHARGE : name;
    }

    private Inventory snapshot() {
        Inventory inv = new Inventory();
        ItemContainer c = client.getItemContainer(InventoryID.INVENTORY);
        if (c == null) return inv;
        for (Item it : c.getItems()) {
            if (it.getId() <= 0) continue;
            String name = keyOf(it.getId());
            if (name == null) continue;
            inv.qty.merge(name, (long) it.getQuantity(), Long::sum);
        }
        return inv;
    }

    private String nameOf(int itemId) {
        String n = itemManager.getItemComposition(itemManager.canonicalize(itemId)).getName();
        return n == null || n.isEmpty() || n.equalsIgnoreCase("null") ? null : n;
    }

    private boolean visible(int componentId) {
        Widget w = client.getWidget(componentId);
        return w != null && !w.isHidden();
    }

    private boolean visible(int group, int child) {
        Widget w = client.getWidget(group, child);
        return w != null && !w.isHidden();
    }

}

package com.routeplanner.record;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.QuickStepDialog;
import com.routeplanner.model.Route;
import com.routeplanner.model.RouteSection;
import com.routeplanner.model.RouteStep;
import com.routeplanner.util.RouteTextValidator;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;
import java.util.UUID;

/**
 * Review screen shown when a recording stops. Drafts are edited here (with the normal step
 * editor), then saved as a new section of the route the recording was started on. Nothing
 * reaches the route until Save, and closing with unsaved steps asks first.
 */
public class RecordReviewDialog extends JDialog {

    private final RoutePlannerPlugin plugin;
    private final Route route;
    private final List<RouteStep> drafts;
    private final DefaultListModel<RouteStep> model = new DefaultListModel<>();
    private final JList<RouteStep> list = new JList<>(model);

    public RecordReviewDialog(RoutePlannerPlugin plugin, Route route, List<RouteStep> drafts) {
        this.plugin = plugin;
        this.route = route;
        this.drafts = new ArrayList<>(drafts);

        setTitle("Review recording");
        setAlwaysOnTop(true);
        setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);
        addWindowListener(new WindowAdapter() {
            @Override public void windowClosing(WindowEvent e) { onDiscard(); }
        });

        JPanel root = new JPanel(new BorderLayout(0, 8));
        root.setBorder(new EmptyBorder(10, 10, 10, 10));
        root.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel header = new JLabel("<html>" + drafts.size() + " recorded steps for <b>"
            + escape(route.getName()) + "</b>. Edit or remove anything before saving.</html>");
        header.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        root.add(header, BorderLayout.NORTH);

        for (RouteStep s : this.drafts) model.addElement(s);
        list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        list.setCellRenderer(new StepRenderer());
        list.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        list.addMouseListener(new java.awt.event.MouseAdapter() {
            @Override public void mouseClicked(java.awt.event.MouseEvent e) {
                if (e.getClickCount() == 2) onEdit();
            }
        });
        if (!model.isEmpty()) list.setSelectedIndex(0);
        root.add(new JScrollPane(list), BorderLayout.CENTER);

        JPanel side = new JPanel(new GridLayout(0, 1, 0, 4));
        side.setBackground(ColorScheme.DARK_GRAY_COLOR);
        side.add(button("Edit", e -> onEdit()));
        side.add(button("Delete", e -> onDelete()));
        side.add(button("Move up", e -> move(-1)));
        side.add(button("Move down", e -> move(1)));
        JPanel sideWrap = new JPanel(new BorderLayout());
        sideWrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
        sideWrap.add(side, BorderLayout.NORTH);
        root.add(sideWrap, BorderLayout.EAST);

        JPanel bottom = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
        bottom.setBackground(ColorScheme.DARK_GRAY_COLOR);
        bottom.add(button("Discard", e -> onDiscard()));
        JButton save = button("Save to route", e -> onSave());
        save.setForeground(new Color(0, 200, 0));
        bottom.add(save);
        root.add(bottom, BorderLayout.SOUTH);

        setContentPane(root);
        setSize(520, 420);
        setLocationRelativeTo(null);
    }

    private JButton button(String text, java.awt.event.ActionListener action) {
        JButton b = new JButton(text);
        b.setFocusPainted(false);
        b.addActionListener(action);
        return b;
    }

    private void onEdit() {
        RouteStep step = list.getSelectedValue();
        if (step == null) return;
        // The editor edits the draft in place; it isn't in the route yet, so nothing is saved.
        QuickStepDialog editor = new QuickStepDialog(plugin, route, step);
        editor.setOnSaved(list::repaint);
        editor.setVisible(true);
    }

    private void onDelete() {
        int i = list.getSelectedIndex();
        if (i < 0) return;
        model.remove(i);
        if (!model.isEmpty()) list.setSelectedIndex(Math.min(i, model.size() - 1));
    }

    private void move(int delta) {
        int i = list.getSelectedIndex();
        int j = i + delta;
        if (i < 0 || j < 0 || j >= model.size()) return;
        RouteStep s = model.remove(i);
        model.add(j, s);
        list.setSelectedIndex(j);
    }

    private void onSave() {
        if (model.isEmpty()) {
            JOptionPane.showMessageDialog(this, "There are no steps left to save.");
            return;
        }
        if (!plugin.getRoutes().contains(route)) {
            JOptionPane.showMessageDialog(this, "The route \"" + route.getName()
                + "\" no longer exists, so these steps can't be saved to it.");
            return;
        }
        String defaultName = "Recording " + new SimpleDateFormat("MMM d HH:mm").format(new Date());
        String name = (String) JOptionPane.showInputDialog(this, "Section name:", "Save recording",
            JOptionPane.PLAIN_MESSAGE, null, null, defaultName);
        if (name == null || name.trim().isEmpty()) return;
        String err = RouteTextValidator.checkField("Section name", name.trim());
        if (err != null) {
            JOptionPane.showMessageDialog(this, err, "Links not allowed", JOptionPane.WARNING_MESSAGE);
            return;
        }

        plugin.getRouteHistory().push(route, "Record section \"" + name.trim() + "\"", plugin.getRouteGson());
        RouteSection section = new RouteSection(UUID.randomUUID().toString(), name.trim());
        route.getSections().add(section);
        for (int i = 0; i < model.size(); i++) route.addStepToSection(model.get(i), section.getId());
        plugin.saveRoutesPublic();
        plugin.refreshHighlights();
        dispose();
    }

    private void onDiscard() {
        if (!model.isEmpty()) {
            int choice = JOptionPane.showConfirmDialog(this,
                "Are you sure? You will lose all " + model.size() + " recorded steps.",
                "Discard recording", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
            if (choice != JOptionPane.YES_OPTION) return;
        }
        dispose();
    }

    private static String escape(String s) {
        return s == null ? "" : s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    /** One line per draft: its name plus tags for the components it carries. */
    private static class StepRenderer extends DefaultListCellRenderer {
        @Override
        public Component getListCellRendererComponent(JList<?> list, Object value, int index,
                                                      boolean selected, boolean focus) {
            super.getListCellRendererComponent(list, value, index, selected, focus);
            RouteStep s = (RouteStep) value;
            StringBuilder tags = new StringBuilder();
            if (s.getTeleportMethod() != null) tags.append(" [Teleport]");
            else if (s.getWorldPoint() != null) tags.append(" [Location]");
            if (s.getTransitionPoint() != null) tags.append(" [Stairs]");
            if (s.hasBoarding()) tags.append(" [Boat]");
            if (s.hasItems()) tags.append(" [Items]");
            if (s.hasSkillGoal()) tags.append(" [Skill]");
            if (s.hasHighlight()) tags.append(" [Highlight]");
            if (s.getDialogOptions() != null && !s.getDialogOptions().trim().isEmpty()) tags.append(" [Dialog]");
            if (s.hasQuest()) tags.append(" [Quest]");
            if (s.hasNote()) tags.append(" [Note]");
            setText((index + 1) + ". " + s.getName() + tags);
            setBorder(new EmptyBorder(4, 6, 4, 6));
            return this;
        }
    }
}

