import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;

/**
 * Record mode: watches what the player does in game and turns it into draft route steps.
 *
 * This class only READS game events and WRITES draft RouteSteps. It never sends input,
 * never calls menuAction, never touches the network, and has no way to replay anything --
 * a recording is just a guide the player still follows by hand. It doesn't store mouse
 * positions, timings or keystrokes, only what happened in game (where you went, what you
 * clicked on), and only for the local player.
 *
 * It is registered on the event bus only while recording. All state is touched on the
 * client thread; start/stop are called from the panel via ClientThread.
 */
@Slf4j
@Singleton
public class RouteRecorder {

    /** Same-plane movement beyond this in one tick is a teleport/transport, not walking. */
    private static final int JUMP_TILES = 10;
    /** A recorded stop must be at least this far from the last step to count as a new place. */
    private static final int MIN_STEP_SPACING = 5;
    /** Teleports can take a while to land (home teleport ~17 ticks, glory rub + dialog). */
    private static final int TELEPORT_WINDOW_TICKS = 40;

    private final Client client;
    private final EventBus eventBus;
    private final RoutePlannerConfig config;
    private final ItemRecorder items;
    private final ActivityRecorder activity;
    private final DialogRecorder dialog;

    @Getter private volatile boolean recording;
    /** The route the recording was started on; the review saves into this one. */
    @Getter private Route targetRoute;
    private final List<RouteStep> drafts = new ArrayList<>();

    private WorldPoint lastPos;
    private WorldPoint anchor;          // where the last step was recorded (or recording started)
    private int idleTicks;

    /** The most recent click of any kind, so a jump can be explained by what caused it. */
    private Click lastClick;
    /** The most recent click that could start a teleport (a spell cast or a teleport item). */
    private Click lastTeleportClick;
    /** Marks a nexus pick whose menu text couldn't be read; named from where you land instead. */
    private static final String NEXUS_UNREAD = "";
    /** The last Portal Nexus destination picked (menu row or right-click option), and when. */
    private String lastNexusDest;
    private int lastNexusTick;
    /** A stair/ladder climb waiting to be attached to the next location step on the new floor. */
    private WorldPoint pendingTransitionTile;
    private int pendingTransitionObjectId = -1;
    /** Whether the player was on a boat last tick, to notice them getting on one (Sailing). */
    private boolean wasAboard;
    /** The last "Board" click on an object (the gangplank); a boat-picking menu usually follows it. */
    private Click lastBoardClick;
    /** How recent the gangplank click must be for boarding to be credited to it. */
    private static final int BOARD_CLICK_TICKS = 20;
    /** How close to a dock the player must step off a boat for it to count as docking there. */
    private static final int DOCK_RADIUS = 15;
    /** The dock the player last boarded at; stopping near it is getting ready, not a destination. */
    private WorldPoint boardedAt;
    /** How far out from that dock the boat must stop for the stop to become a step. */
    private static final int BOARD_IDLE_RADIUS = 12;

    private static final class Click {
        final int tick;
        final MenuAction action;
        final String option;
        final String target;
        final int id;
        final int itemId;
        final int sceneX;
        final int sceneY;

        Click(int tick, MenuOptionClicked e) {
            this.tick = tick;
            this.action = e.getMenuAction();
            this.option = Text.removeTags(e.getMenuOption());
            this.target = Text.removeTags(e.getMenuTarget());
            this.id = e.getId();
            this.itemId = e.getItemId();
            this.sceneX = e.getParam0();
            this.sceneY = e.getParam1();
        }

        boolean isNpc() {
            switch (action) {
                case NPC_FIRST_OPTION:
                case NPC_SECOND_OPTION:
                case NPC_THIRD_OPTION:
                case NPC_FOURTH_OPTION:
                case NPC_FIFTH_OPTION:
                    return true;
                default:
                    return false;
            }
        }

        boolean isObject() {
            switch (action) {
                case GAME_OBJECT_FIRST_OPTION:
                case GAME_OBJECT_SECOND_OPTION:
                case GAME_OBJECT_THIRD_OPTION:
                case GAME_OBJECT_FOURTH_OPTION:
                case GAME_OBJECT_FIFTH_OPTION:
                    return true;
                default:
                    return false;
            }
        }

        String describe() {
            return target.isEmpty() ? option : option + " " + target;
        }
    }

    private final com.routeplanner.sailing.SailingDocks sailingDocks;

    @Inject
    public RouteRecorder(Client client, EventBus eventBus, RoutePlannerConfig config, ItemManager itemManager,
                         com.routeplanner.sailing.SailingDocks sailingDocks) {
        this.client = client;
        this.eventBus = eventBus;
        this.config = config;
        this.sailingDocks = sailingDocks;
        this.items = new ItemRecorder(client, itemManager, this);
        this.activity = new ActivityRecorder(client, this);
        this.dialog = new DialogRecorder(client, this);
    }

    /** Begin recording into {@code route}. Call on the client thread. */
    public void start(Route route) {
        if (recording) return;
        drafts.clear();
        targetRoute = route;
        lastPos = playerPos();
        anchor = lastPos;
        idleTicks = 0;
        lastClick = null;
        lastTeleportClick = null;
        lastNexusDest = null;
        pendingTransitionTile = null;
        pendingTransitionObjectId = -1;
        wasAboard = com.routeplanner.sailing.Sailing.isSailing(client);
        lastBoardClick = null;
        boardedAt = null;
        items.start();
        activity.start();
        dialog.start();
        recording = true;
        eventBus.register(this);
        log.info("Route Planner: recording started on route '{}'", route.getName());
    }

    /**
     * Stop recording and hand back the drafts. Records a final location step if the player
     * ended somewhere new. Call on the client thread.
     */
    public List<RouteStep> stop() {
        if (!recording) return new ArrayList<>();
        eventBus.unregister(this);
        recording = false;
        WorldPoint pos = playerPos();
        if (pos != null && !inInstance() && isNewPlace(pos)
            && !activity.isBusy(pos, client.getTickCount())) addLocationStep(pos);
        if (config.recordAlwaysHighlight()) {
            for (RouteStep s : drafts) if (s.hasHighlight()) s.setHighlightEnabled(true);
        }
        log.info("Route Planner: recording stopped, {} draft steps", drafts.size());
        List<RouteStep> out = new ArrayList<>(drafts);
        drafts.clear();
        return out;
    }

    /** Drop everything without producing drafts (e.g. plugin shutting down). */
    public void cancel() {
        if (recording) eventBus.unregister(this);
        recording = false;
        drafts.clear();
    }

    /**
     * Diagnostic trace (config "Diagnostic trace"): one log line per event and decision, with
     * the tick, tile, region and the step it touched, so a bad recording can be replayed on paper.
     */
    void trace(String msg) {
        if (!config.recordTrace()) return;
        WorldPoint p = playerPos();
        log.info("[RP-TRACE] t={} pos={} region={} inst={} drafts={} | {}", client.getTickCount(),
            p == null ? "?" : p.getX() + "," + p.getY() + "," + p.getPlane(),
            p == null ? "?" : p.getRegionID(), inInstance(), drafts.size(), msg);
    }

    static String describeStep(RouteStep s) {
        if (s == null) return "null";
        return "'" + s.getName() + "' wp=" + s.getWorldPoint() + " items=" + s.getItemMode() + ":" + s.getItemList()
            + " skill=" + s.getSkillingSkill() + "/" + s.getSkillingGoalValue() + " recipe=" + s.getRecipeLabel()
            + " npc=" + s.getSkillingTargetNpc() + " obj=" + s.getSkillingTargetObject()
            + " kill=" + s.getNpcHighlight() + "x" + s.getNpcKillCount() + " tele=" + s.getTeleportMethod()
            + " trans=" + s.getTransitionPoint() + " board=" + s.getBoardPoint();
    }

    /** The latest recorded step's name, for the panel's recording banner (null before the first). */
    public String getLastDraftName() {
        try {
            return drafts.isEmpty() ? null : drafts.get(drafts.size() - 1).getName();
        } catch (RuntimeException e) {
            return null; // read from the Swing thread while the client thread adds a step
        }
    }

    /** Draft steps so far, for the on-screen indicator. */
    public int getDraftCount() {
        return drafts.size();
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked e) {
        Click click = new Click(client.getTickCount(), e);
        lastClick = click;
        // "Board", "Board-previous"... on the gangplank
        if (click.isObject() && click.option.toLowerCase().startsWith("board")) lastBoardClick = click;
        trace("CLICK action=" + click.action + " option='" + click.option + "' target='" + click.target
            + "' id=" + click.id + " item=" + click.itemId + " p0=" + e.getParam0() + " p1=" + e.getParam1());
        if (click.action.name().startsWith("GROUND_ITEM_") && "Take".equalsIgnoreCase(click.option)) {
            items.onTake(click.id, click.tick);
        }
        if (matchSpell(click) != null || isTeleportItem(click.itemId)) {
            lastTeleportClick = click;
            activity.onTeleportClick(click.tick);
        }
        if ("Lower net".equalsIgnoreCase(click.option)) activity.onLowerNet(click.tick);
        // Crewmates on the boat (commanding them, chatting): not part of the route
        NPC clickedNpc = click.isNpc() ? e.getMenuEntry().getNpc() : null;
        if (clickedNpc != null && com.routeplanner.sailing.Sailing.isSailing(client)
                && clickedNpc.getWorldView() == client.getLocalPlayer().getWorldView()) {
            trace("CREW click on " + click.target + ", not recorded");
            dialog.onCrewClick(click.tick);
            return;
        }
        // A facility on the deck (the trawling net's "Collect-from" asks where the fish go): its menu
        // isn't a route step, though using it still counts for activities below
        if (click.isObject() && com.routeplanner.sailing.Sailing.isSailing(client)
                && e.getMenuEntry().getWorldViewId() == client.getLocalPlayer().getWorldView().getId()) {
            dialog.onCrewClick(click.tick);
        }
        if ((click.isNpc() || click.isObject()) && !"Examine".equalsIgnoreCase(click.option)
            && !"Walk here".equalsIgnoreCase(click.option)) {
            // An object click names the object's own tile (scene coords): exact, unlike the player's.
            WorldPoint objectTile = click.isObject() && !inInstance()
                ? WorldPoint.fromScene(client.getTopLevelWorldView(), click.sceneX, click.sceneY, client.getTopLevelWorldView().getPlane())
                : null;
            activity.onTargetClick(click.option, click.target, click.isNpc(), click.id, stepTile(), objectTile, click.tick);
        }
        if (click.isNpc()) dialog.onNpcClick(click.option, click.target, click.tick);
        dialog.onMenuClick(e.getParam1(), e.getParam0(), stepTile());
        String nexus = nexusDestination(e, click);
        if (nexus != null) {
            lastNexusDest = nexus;
            lastNexusTick = click.tick;
        }
    }

    /**
     * The destination picked at a Portal Nexus, if this click picked one: either a row in the
     * nexus teleport menu (those clicks only say "Continue", so the row's own text is read) or
     * a destination option right-clicked on the nexus itself.
     */
    private String nexusDestination(MenuOptionClicked e, Click click) {
        int widgetId = e.getParam1();
        if (widgetId >>> 16 == PortalNexus.MENU_GROUP) {
            Widget w = client.getWidget(widgetId);
            Widget row = w != null && e.getParam0() >= 0 ? w.getChild(e.getParam0()) : null;
            String text = PortalNexus.rowText(client, row != null ? row : w);
            if (text == null) {
                log.info("Route Planner: couldn't read Portal Nexus row text (widget {}, child {})",
                    widgetId, e.getParam0());
                return NEXUS_UNREAD;
            }
            return text;
        }
        if (click.isObject() && click.target.toLowerCase().startsWith("portal nexus")) {
            switch (click.option.toLowerCase()) {
                case "teleport menu": case "configuration": case "examine": case "walk here":
                    return null;
                default:
                    return click.option;
            }
        }
        return null;
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged e) {
        traceSailingContainer(e);
        if (e.getContainerId() != InventoryID.INVENTORY.getId()) return;
        items.onInventoryChanged(stepTile(), client.getTickCount());
    }

    @Subscribe
    public void onChatMessage(ChatMessage e) {
        // Trawling catches (Sailing), "You catch three giant krill." (often a spam-filtered message)
        if (e.getType() == ChatMessageType.GAMEMESSAGE || e.getType() == ChatMessageType.SPAM) {
            com.routeplanner.sailing.CatchMessages.Catch c = com.routeplanner.sailing.CatchMessages.parse(e.getMessage());
            if (e.getMessage().toLowerCase().contains("catch")) trace("CHAT '" + e.getMessage() + "' -> " + (c == null ? "not a catch" : c.count + " " + c.fish));
            // Only a trawling net's catch: on the boat with a net down (fishing elsewhere says "You catch" too)
            boolean netDown = client.getVarbitValue(net.runelite.api.gameval.VarbitID.SAILING_SIDEPANEL_BOAT_TRAWLING_NET_0_DEPTH) > 0
                || client.getVarbitValue(net.runelite.api.gameval.VarbitID.SAILING_SIDEPANEL_BOAT_TRAWLING_NET_1_DEPTH) > 0;
            if (c != null && netDown && com.routeplanner.sailing.Sailing.isSailing(client)) {
                activity.onCatch(c.fish, c.count, stepTile(), client.getTickCount());
            }
        }
        if (e.getType() != ChatMessageType.GAMEMESSAGE) return;
        if (dialog.onGameMessage(e.getMessage(), stepTile())) activity.onQuestComplete(client.getTickCount());
    }

    @Subscribe
    public void onStatChanged(StatChanged e) {
        trace("XP " + e.getSkill() + " xp=" + e.getXp());
        activity.onXp(e.getSkill(), e.getXp(), stepTile(), client.getTickCount());
    }

    @Subscribe
    public void onActorDeath(ActorDeath e) {
        if (e.getActor() instanceof NPC) trace("DEATH npc='" + e.getActor().getName() + "'");
        if (e.getActor() instanceof NPC) activity.onNpcDeath((NPC) e.getActor(), stepTile());
    }

    @Subscribe
    public void onGameTick(GameTick tick) {
        WorldPoint pos = playerPos();
        if (pos == null) return;
        items.onTick(stepTile());
        dialog.onTick(stepTile(), client.getTickCount());
        if (lastPos == null) { lastPos = pos; anchor = pos; return; }

        // Getting on or off a boat moves the player between the dock and the deck: the trip, not a jump.
        boolean aboard = com.routeplanner.sailing.Sailing.isSailing(client);
        boolean boatChanged = aboard != wasAboard;
        if (boatChanged) {
            if (aboard) onBoard(lastPos);
            else onDisembark(pos);
        }
        wasAboard = aboard;

        boolean planeChanged = pos.getPlane() != lastPos.getPlane();
        boolean jumped = planeChanged || pos.distanceTo(lastPos) > JUMP_TILES;
        if (boatChanged) {
            idleTicks = 0;
        } else if (jumped && aboard) {
            // Still on the boat after a jump: sailing through a cave mouth (Wyrmscraig Cavern). That's
            // part of the trip; where it ends gets its step on getting off or stopping.
            trace("JUMP from=" + lastPos + " to=" + pos + " = sailing through a cave mouth, part of the trip");
            idleTicks = 0;
        } else if (jumped) {
            trace("JUMP from=" + lastPos + " to=" + pos + " planeChanged=" + planeChanged
                + " lastClick=" + (lastClick == null ? "none" : lastClick.describe() + "#" + lastClick.id + "@" + lastClick.tick));
            onJump(lastPos, pos, planeChanged);
            idleTicks = 0;
        } else if (pos.equals(lastPos)) {
            // Instances (the house, many quest and boss areas) report made-up coordinates
            // that can't be walked to later, so stopping inside one never makes a step.
            // On a boat, waiting at the mooring to take the helm isn't a destination; stopping out at
            // sea is. Where the trip ends at a dock gets its step on getting off (see onDisembark).
            boolean readyingBoat = aboard && boardedAt != null && pos.distanceTo2D(boardedAt) <= BOARD_IDLE_RADIUS;
            if (++idleTicks == config.recordIdleTicks() && !inInstance() && !readyingBoat && isNewPlace(pos)
                && !activity.isBusy(pos, client.getTickCount())) {
                trace("IDLE -> location step" + (aboard ? " (stopped at sea)" : ""));
                if (aboard) addDraft(newLocationStep(pos, sailName(pos)), pos);
                else addLocationStep(pos);
            }
        } else {
            idleTicks = 0;
        }
        lastPos = pos;
    }

    /** The player moved further in one tick than walking allows: work out why. */
    private void onJump(WorldPoint from, WorldPoint to, boolean planeChanged) {
        int now = client.getTickCount();
        boolean landedInInstance = inInstance();

        // Portal Nexus: checked before objects, since its right-click teleports are object clicks.
        if (lastNexusDest != null && now - lastNexusTick <= TELEPORT_WINDOW_TICKS && !landedInInstance) {
            String dest = lastNexusDest;
            lastNexusDest = null;
            if (dest.equals(NEXUS_UNREAD)) dest = LocationNames.describe(to);
            RouteStep step = newLocationStep(to, "Teleport: Portal Nexus to " + dest);
            step.setTeleportMethod("NEXUS");
            step.setTeleportNexus(dest);
            step.setTeleportDestination(to);
            addDraft(step, to);
            return;
        }

        // Mid-lap, every jump and drop is the course, whatever was clicked last (players often
        // click ahead while an obstacle is still playing out).
        if (activity.runningCourse(from, now)) { trace("JUMP = mid agility lap, ignored"); return; }

        // Stairs, ladders, trapdoors, dungeon entrances, house portals: the last click was an object.
        if (lastClick != null && lastClick.isObject()) {
            // Agility obstacles jump and climb all the time; that's the course, not travel.
            if (activity.onAgilityCourse(from, lastClick.id, now)) { trace("JUMP = agility obstacle, ignored"); return; }
            if (landedInInstance) {
                if (isHousePortalOption(lastClick.option)) {
                    RouteStep step = newLocationStep(from, "Enter house" + LocationNames.at(from));
                    step.setSkillingTargetObject("Portal");
                    addDraft(step, from);
                }
                // Climbs inside an instance have made-up coordinates; don't carry them over.
                pendingTransitionTile = null;
                pendingTransitionObjectId = -1;
                return;
            }
            trace("JUMP = object click (instance=" + landedInInstance + ")");
            if (planeChanged) {
                // A second climb before any step on this floor: keep the first one as a step
                // at its landing so neither climb is lost.
                if (pendingTransitionTile != null) addLocationStep(from);
                pendingTransitionTile = from;
                pendingTransitionObjectId = lastClick.id;
            }
            // Same-plane object jumps (dungeon entrances, shortcuts, leaving the house by its
            // portal) need nothing: both pathfinders already know those transports.
            return;
        }

        Click tele = lastTeleportClick;
        if (tele != null && now - tele.tick <= TELEPORT_WINDOW_TICKS) {
            lastTeleportClick = null;
            if (addTeleportStep(tele, to, landedInInstance)) return;
        }

        // An instance we can't explain (quest, boss, minigame): nothing walkable to record.
        if (landedInInstance) return;

        trace("JUMP = unexplained travel");
        // Boats, NPC travel, fairy rings, anything else: keep it as a location step with a
        // note of what caused it, so nothing is silently dropped.
        RouteStep step = newLocationStep(to, LocationNames.nameOf(to) != null ? "Travel to " + LocationNames.nameOf(to) : "Travel here");
        String cause = lastClick != null ? lastClick.describe() : "unknown";
        step.setNoteText("Recorded travel (last action: " + cause + "). Edit to describe how to get here.");
        addDraft(step, to);
    }

    /**
     * The player got on a boat, standing at {@code dock} the tick before: a step that has you walk
     * to the gangplank and board, like stairs on a climb. Standing at the dock first already made a
     * plain step there; that one becomes the boarding step.
     */
    private void onBoard(WorldPoint dock) {
        boardedAt = dock;
        String hint = sailingDocks.boardingHint(dock);
        RouteStep step = stepAt(dock, hint);
        step.setWorldPoint(null);   // being on the boat is the goal, not a tile
        step.setTransitionPoint(null);
        step.setBoardPoint(dock);
        Click c = lastBoardClick;
        boolean clickedGangplank = c != null && client.getTickCount() - c.tick <= BOARD_CLICK_TICKS;
        step.setBoardObjectId(clickedGangplank ? c.id : -1);
        trace("BOARD at " + dock + " via " + (clickedGangplank ? c.describe() + "#" + c.id : "no recent Board click"));
    }

    /**
     * The player got off a boat at {@code landed}: the end of the trip, so it gets its step right
     * away ("Sail to Lunar Isle") rather than waiting to stand still. Leaving a boat away from any
     * dock (a teleport, say) is left to the jump handling.
     */
    private void onDisembark(WorldPoint landed) {
        com.routeplanner.sailing.SailingDocks.Dock dock = sailingDocks.nearest(landed, DOCK_RADIUS);
        trace("DISEMBARK at " + landed + " dock=" + (dock == null ? "none" : dock.name));
        if (dock == null) return;
        addDraft(newLocationStep(landed, "Sail to " + dock.name), landed);
    }

    /** "Sail to Lunar Isle", or for a spot out at sea the map has no name for, "Sail out to sea". */
    private static String sailName(WorldPoint pos) {
        String name = LocationNames.nameOf(pos);
        return name != null ? "Sail to " + name : "Sail out to sea";
    }

    private static boolean isHousePortalOption(String option) {
        return "Home".equalsIgnoreCase(option) || "Build mode".equalsIgnoreCase(option);
    }

    private boolean addTeleportStep(Click click, WorldPoint landed, boolean landedInInstance) {
        TeleportSpell spell = matchSpell(click);
        if (spell != null && lands(spell.getDestination(), landed, landedInInstance)) {
            RouteStep step = newTeleportStep(spell.getDestination(), spell.getName());
            step.setTeleportMethod("SPELL");
            step.setTeleportSpell(spell.getName());
            addDraft(step, landed);
            return true;
        }
        TeleportItem item = matchItem(click.itemId, landed, landedInInstance);
        if (item != null) {
            RouteStep step = newTeleportStep(item.getDestination(),
                TeleportItems.isHouse(item.getDestination()) ? item.getItemName() : item.getDisplayName());
            step.setTeleportMethod("ITEM");
            step.setTeleportItem(item.getDisplayName());
            addDraft(step, landed);
            return true;
        }
        return false;
    }

    /**
     * A teleport step shaped like one made in the step editor. A house teleport has no
     * real tile to walk to, so it gets no location; it completes once you're inside.
     */
    private RouteStep newTeleportStep(WorldPoint dest, String what) {
        boolean house = TeleportItems.isHouse(dest);
        RouteStep step = house
            ? new RouteStep("Teleport to house (" + what + ")", StepType.LOCATION, null, -1)
            : newLocationStep(dest, "Teleport: " + what);
        step.setTeleportDestination(dest);
        return step;
    }

    private static TeleportSpell matchSpell(Click click) {
        if (!"Cast".equalsIgnoreCase(click.option)) return null;
        // In-game names can carry a prefix the table doesn't, e.g. "Lumbridge Home Teleport".
        TeleportSpell best = null;
        for (TeleportSpell s : TeleportSpells.ALL) {
            String name = s.getName();
            if (click.target.equalsIgnoreCase(name)) return s;
            if (click.target.toLowerCase().endsWith(name.toLowerCase())
                && (best == null || name.length() > best.getName().length())) {
                best = s;
            }
        }
        return best;
    }

    private static boolean isTeleportItem(int itemId) {
        if (itemId <= 0) return false;
        for (TeleportItem t : TeleportItems.ALL) if (t.matchesItemId(itemId)) return true;
        return false;
    }

    /** The teleport-item destination (glory has several) closest to where the player landed. */
    private static TeleportItem matchItem(int itemId, WorldPoint landed, boolean landedInInstance) {
        TeleportItem best = null;
        int bestDist = Integer.MAX_VALUE;
        for (TeleportItem t : TeleportItems.ALL) {
            if (!t.matchesItemId(itemId) || !lands(t.getDestination(), landed, landedInInstance)) continue;
            int d = TeleportItems.isHouse(t.getDestination()) ? 0 : t.getDestination().distanceTo(landed);
            if (d < bestDist) { bestDist = d; best = t; }
        }
        return best;
    }

    /**
     * Whether landing here fits a teleport's destination. Table destinations are approximate
     * arrival tiles, so accept a landing nearby; the house is any instance.
     */
    private static boolean lands(WorldPoint dest, WorldPoint landed, boolean landedInInstance) {
        if (dest == null) return false;
        if (TeleportItems.isHouse(dest)) return landedInInstance;
        return !landedInInstance && dest.distanceTo(landed) <= 30;
    }

    private boolean isNewPlace(WorldPoint pos) {
        return anchor == null || pos.distanceTo(anchor) > MIN_STEP_SPACING;
    }

    private void addLocationStep(WorldPoint pos) {
        addDraft(newLocationStep(pos, LocationNames.nameOf(pos) != null ? "Go to " + LocationNames.nameOf(pos) : "Go to this spot"), pos);
    }

    /** A location step shaped exactly like one made in the step editor. */
    private RouteStep newLocationStep(WorldPoint pos, String name) {
        RouteStep step = new RouteStep(name, StepType.LOCATION, pos, -1);
        // A climb waiting for its destination floor: this step is where it leads.
        if (pendingTransitionTile != null && pos.getPlane() != pendingTransitionTile.getPlane()) {
            step.setTransitionPoint(pendingTransitionTile);
            step.setTransitionObjectId(pendingTransitionObjectId);
        }
        pendingTransitionTile = null;
        pendingTransitionObjectId = -1;
        return step;
    }

    /**
     * The step for something done at {@code pos}. If the latest step is a plain location step
     * right here (e.g. "Go to Varrock" from standing at the bank), it's reused and renamed, so
     * walking somewhere and then banking is one step, not two. {@code pos} is null in instances.
     */
    RouteStep stepAt(WorldPoint pos, String name) {
        return stepAt(pos, name, null);
    }

    /**
     * Like {@link #stepAt(WorldPoint, String)}, but the latest step nearby is also reused (keeping
     * its name) when {@code compatible} accepts it, e.g. kills joining the loot picked up there.
     */
    RouteStep stepAt(WorldPoint pos, String name, Predicate<RouteStep> compatible) {
        RouteStep last = lastDraft();
        if (last != null && isNear(last, pos)) {
            if (isPlainLocation(last)) {
                trace("REUSE plain step #" + drafts.size() + " as '" + name + "'");
                last.setName(name);
                return last;
            }
            if (compatible != null && compatible.test(last)) { trace("REUSE compatible step #" + drafts.size()); return last; }
        }
        RouteStep step = pos == null
            ? new RouteStep(name, StepType.LOCATION, null, -1)
            : newLocationStep(pos, name);
        addDraft(step, pos != null ? pos : anchor);
        return step;
    }

    int currentTick() {
        return client.getTickCount();
    }

    void removeDraft(RouteStep step) {
        drafts.remove(step);
        trace("REMOVED STEP " + describeStep(step));
    }

    /**
     * The "+ Note" button while recording: the note goes on the latest step if the player is
     * still there, otherwise on a new step here. Call on the client thread.
     */
    public void addNote(String text) {
        if (!recording || text == null || text.trim().isEmpty()) return;
        WorldPoint pos = stepTile();
        RouteStep last = lastDraft();
        RouteStep step = last != null && isNear(last, pos) ? last : stepAt(pos, "Note" + (pos == null ? "" : LocationNames.at(pos)));
        String old = step.getNoteText();
        step.setNoteText(old == null || old.trim().isEmpty() ? text.trim() : old.trim() + "\n" + text.trim());
        step.setNoteAutoComplete(true);
        trace("NOTE added to " + describeStep(step));
    }

    /**
     * Trace what's in the trawling net and the cargo holds when they change, to learn when the game
     * sends them (some containers only update while their window is open) before trawling is built.
     */
    private void traceSailingContainer(ItemContainerChanged e) {
        int id = e.getContainerId();
        String which = id == net.runelite.api.gameval.InventoryID.SAILING_TRAWLING_NET ? "TRAWL NET"
            : id >= net.runelite.api.gameval.InventoryID.SAILING_BOAT_1_CARGOHOLD
                && id <= net.runelite.api.gameval.InventoryID.SAILING_BOAT_5_CARGOHOLD
                ? "CARGO HOLD " + (id - net.runelite.api.gameval.InventoryID.SAILING_BOAT_1_CARGOHOLD + 1) : null;
        if (which == null || !config.recordTrace()) return;
        java.util.Map<String, Integer> counts = new java.util.LinkedHashMap<>();
        for (net.runelite.api.Item item : e.getItemContainer().getItems()) {
            if (item.getId() <= 0) continue;
            counts.merge(client.getItemDefinition(item.getId()).getName(), item.getQuantity(), Integer::sum);
        }
        trace(which + " " + counts);
    }

    /** Whether {@code step} is still one of the drafts (not removed in the meantime). */
    boolean hasDraft(RouteStep step) {
        return drafts.contains(step);
    }

    RouteStep lastDraft() {
        return drafts.isEmpty() ? null : drafts.get(drafts.size() - 1);
    }

    boolean isNear(RouteStep step, WorldPoint pos) {
        return isNear(step, pos, MIN_STEP_SPACING);
    }

    boolean isNear(RouteStep step, WorldPoint pos, int tiles) {
        WorldPoint wp = step.getWorldPoint();
        if (wp == null || pos == null) return wp == null && pos == null;
        return wp.distanceTo(pos) <= tiles;
    }

    boolean runningCourse(WorldPoint pos) {
        return activity.runningCourse(pos != null ? pos : playerPos(), client.getTickCount());
    }

    /** Items that arrived without a pickup, purchase or withdrawal: gathering, if anything. */
    void onItemsGained(java.util.Map<String, Long> gains, int tick) {
        trace("GAINED " + gains);
        activity.onItemsGained(gains, tick);
    }

    /** Only a location: nothing else recorded on it yet, so more can be added. */
    private static boolean isPlainLocation(RouteStep s) {
        return s.getTeleportMethod() == null && !s.hasItems() && !s.hasSkillGoal() && !s.hasNote()
            && !s.hasQuest() && !s.hasHighlight()
            && (s.getDialogOptions() == null || s.getDialogOptions().trim().isEmpty());
    }

    /** Where the player is, for putting on a step; null inside instances (made-up coordinates). */
    private WorldPoint stepTile() {
        return inInstance() ? null : playerPos();
    }

    private void addDraft(RouteStep step, WorldPoint playerAt) {
        drafts.add(step);
        trace("NEW STEP #" + drafts.size() + " " + describeStep(step));
        anchor = playerAt;
        idleTicks = 0;
    }

    private boolean inInstance() {
        return client.getTopLevelWorldView() != null && client.getTopLevelWorldView().isInstance();
    }

    private WorldPoint playerPos() {
        return com.routeplanner.sailing.Sailing.position(client);
    }
}

package com.routeplanner.record;

import com.routeplanner.model.RouteStep;
import com.routeplanner.sailing.CatchMessages;
import com.routeplanner.sailing.Sailing;
import com.routeplanner.sailing.ShoalRoutes;
import com.routeplanner.util.LocationNames;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Skill;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

import java.util.IdentityHashMap;
import java.util.Map;

/**
 * The Sailing half of the activity recorder: activities that pay out long after the click that
 * started them, so they run as sessions rather than a click window.
 *
 *  - Salvaging: deploying a hook by a wreck; its XP is one "Merchant salvage" step while the boat stays.
 *  - Sorting salvage at a station: its own "Sort Opulent salvage" step (no tile at sea).
 *  - Trawling: the net's catches (the player's or a crewmate's) make one "Catch 120 Marlin" step at a
 *    stop on the shoal's route; its XP belongs to it and makes no step of its own.
 *
 * Salvaging and sorting alternate (and the crew gets talked to in between), so each wreck keeps its
 * own two steps and the XP goes back to the right one. Sailing XP from travelling (wind motes, the helm,
 * the sails) isn't training; only a recent click on a wreck counts outside these sessions.
 */
final class SailingActivity {

    /** Step targets: labels, not things in the world to highlight. */
    static final String SALVAGING = "Salvaging";
    static final String SORTING = "Sorting salvage";

    /** Same session if the boat stays within this many tiles of where it began. */
    private static final int SESSION_RADIUS = 15;
    /** How long sorting XP may pause before the session is over. */
    private static final int SORTING_GAP_TICKS = 30;
    /** A shoal can sail on between stops for a while; this long without trawl XP ends the session. */
    private static final int TRAWL_GAP_TICKS = 100;
    /** How far from the boat to look for the shipwreck being salvaged. */
    private static final int WRECK_RADIUS = 15;
    /** How near the boat must be to a shoal's route for the trawl to be on it. */
    private static final int SHOAL_ROUTE_TILES = 20;
    private static final String WAIT_FOR_SHOAL = "Wait here for the shoal.";
    /** Sailing XP that is training rather than getting about, by what was clicked. */
    private static final String[] TRAINING_TARGETS = {"salvag", "shipwreck", "wreck"};

    private final Client client;
    private final RouteRecorder host;

    /** Where a salvaging hook was deployed, and the wreck beside it (e.g. "Large shipwreck"). */
    private WorldPoint salvageAt;
    private String salvageWreck;
    /** Where a salvaging station was used, when its XP last came, and what's being sorted. */
    private WorldPoint sortingAt;
    private int sortingTick = -1000;
    private String sortingItem;
    /** Whether a trawling net is in use, and when its XP last came. */
    private boolean trawling;
    private int trawlXpTick = -1000;
    /** This wreck's Salvage and Sort steps, the trawl's step, and the XP on each so far. */
    private RouteStep salvageStep, sortStep, trawlStep;
    private final Map<RouteStep, Long> sessionXp = new IdentityHashMap<>();

    SailingActivity(Client client, RouteRecorder host) {
        this.client = client;
        this.host = host;
    }

    void start() {
        salvageAt = null;
        salvageWreck = null;
        sortingAt = null;
        trawling = false;
        salvageStep = sortStep = trawlStep = null;
        sessionXp.clear();
    }

    /** An NPC or object was clicked: a salvaging hook, a trawling net or a salvaging station starts a session. */
    void onTargetClick(String option, String target, WorldPoint at, int tick) {
        String t = target == null ? "" : target.toLowerCase();
        if ("Deploy".equalsIgnoreCase(option) && t.contains("salvaging hook")) {
            // Another wreck (or the first): its own Salvage and Sort steps
            if (salvageAt == null || at == null || at.distanceTo2D(salvageAt) > SESSION_RADIUS) salvageStep = sortStep = null;
            salvageAt = at;
            salvageWreck = nearestShipwreck(at);
            host.trace("SALVAGE session started at " + at + " wreck=" + salvageWreck);
        } else if (t.endsWith("trawling net")) {
            startTrawling(tick);
        } else if (t.contains("salvaging station")) {
            sortingAt = at;
            sortingTick = tick;
            sortingItem = salvageInInventory();
            host.trace("SORTING started at " + at + " item=" + sortingItem);
        }
    }

    /** "Lower net" in the Sailing panel: trawling is on. */
    void onLowerNet(int tick) {
        startTrawling(tick);
    }

    /**
     * Whether XP of this skill belongs to the trawl (the net's Sailing XP, the catches' Fishing XP): it
     * keeps the session going but makes no step, since the catches do (see onCatch).
     */
    boolean absorbTrawlXp(Skill s, int tick) {
        if ((s != Skill.SAILING && s != Skill.FISHING) || !trawling(tick)) return false;
        trawlXpTick = tick;
        return true;
    }

    /**
     * What session this Sailing XP belongs to: SORTING or SALVAGING, or null for neither. Checking it
     * ends sessions the player has left.
     */
    String session(WorldPoint pos, int tick) {
        if (sorting(pos, tick)) return SORTING;
        if (salvaging(pos)) return SALVAGING;
        return null;
    }

    /** Whether a recent click on {@code targetOption targetName} makes Sailing XP training (a wreck). */
    static boolean trainingClick(String targetOption, String targetName) {
        String what = ((targetOption == null ? "" : targetOption) + " " + (targetName == null ? "" : targetName)).toLowerCase();
        for (String k : TRAINING_TARGETS) if (what.contains(k)) return true;
        return false;
    }

    /** Sorting on the boat can be done anywhere at sea, so that step gets no tile; at a port it does. */
    boolean anywhere(String session) {
        return SORTING.equals(session) && Sailing.isSailing(client);
    }

    /** This session's step if it already has one (still a draft), to go back to; otherwise null. */
    RouteStep sessionStep(String session) {
        RouteStep s = SALVAGING.equals(session) ? salvageStep : SORTING.equals(session) ? sortStep : null;
        return s != null && host.hasDraft(s) ? s : null;
    }

    /** The XP on a session step so far. */
    long xp(RouteStep step) {
        return sessionXp.getOrDefault(step, 0L);
    }

    /** A new step was begun for this session. */
    void began(String session, RouteStep step) {
        if (SALVAGING.equals(session)) salvageStep = step;
        if (SORTING.equals(session)) sortStep = step;
    }

    /** The step's XP has grown; kept if it's a session step, to carry on with after a switch. */
    void recordXp(RouteStep step, long xp) {
        if (step != null && (step == salvageStep || step == sortStep)) sessionXp.put(step, xp);
    }

    /** Sets up a new session step: what it highlights. */
    void setUp(String session, RouteStep step) {
        if (SALVAGING.equals(session) && salvageWreck != null) step.setSkillingTargetObject(salvageWreck);
        if (SORTING.equals(session)) step.setSkillingTargetObject("Salvaging station");
    }

    /** The name for a session step, e.g. "Merchant salvage at ..." or "Sort Opulent salvage"; null if not one. */
    String name(String session, RouteStep step, WorldPoint stepPos, WorldPoint where) {
        if (SALVAGING.equals(session)) {
            // "Merchant shipwreck" -> "Merchant salvage"
            String wreck = step.getSkillingTargetObject();
            String kind = wreck != null && wreck.toLowerCase().endsWith(" shipwreck")
                ? wreck.substring(0, wreck.length() - " shipwreck".length()) + " salvage" : "Salvage";
            return kind + LocationNames.at(where);
        }
        if (SORTING.equals(session)) {
            String what = sortingItem != null ? sortingItem : "salvage";
            return stepPos == null ? "Sort " + what : "Sort " + what + LocationNames.at(where);
        }
        return null;
    }

    /** True while trawling, so waiting for the shoal (or stopping the boat) isn't a new stop. */
    boolean isBusy(int tick) {
        return trawling && tick - trawlXpTick <= TRAWL_GAP_TICKS;
    }

    /**
     * Fish caught by the trawling net (the player's or a crewmate's): they go on this trawl's step as a
     * catch goal, "Catch 120 Giant krill". The step waits for the shoal at a stop on its route (the one
     * nearest where the trawl began), since it swims on and comes back there. A catch means trawling,
     * even if the nets were already down when recording started. Returns whether a new step was made.
     */
    boolean onCatch(String fish, int count, WorldPoint pos, int tick) {
        startTrawling(tick);
        boolean fresh = trawlStep == null || !host.hasDraft(trawlStep)
            || (trawlStep.getCatchFish() != null && !CatchMessages.sameFish(fish, trawlStep.getCatchFish()));
        if (fresh) {
            WorldPoint meet = shoalStopNear(pos);
            trawlStep = host.stepAt(meet, "Trawl" + LocationNames.at(meet), null);
            trawlStep.setNoteText(WAIT_FOR_SHOAL);
            trawlStep.setNoteAutoComplete(true);
            trawlStep.setCatchFish(fish);
            trawlStep.setCatchGoal(0);
        }
        trawlStep.setCatchGoal(trawlStep.getCatchGoal() + count);
        trawlStep.setName("Catch " + trawlStep.getCatchGoal() + " " + trawlStep.getCatchFish());
        host.trace("CATCH +" + count + " " + fish + " -> " + trawlStep.getName());
        return fresh;
    }

    private void startTrawling(int tick) {
        if (!trawling) host.trace("TRAWL session started");
        trawling = true;
        trawlXpTick = tick;
    }

    /** Whether the trawling session is still going: XP from it came recently and we're still aboard. */
    private boolean trawling(int tick) {
        if (!trawling) return false;
        if (tick - trawlXpTick <= TRAWL_GAP_TICKS && Sailing.isSailing(client)) return true;
        host.trace("TRAWL session ended");
        trawling = false;
        trawlStep = null;
        return false;
    }

    /** Whether a salvaging session is running here: a hook was deployed and the boat is still by the wreck. */
    private boolean salvaging(WorldPoint pos) {
        if (salvageAt == null) return false;
        if (pos != null && pos.distanceTo2D(salvageAt) <= SESSION_RADIUS) return true;
        host.trace("SALVAGE session ended (boat left " + salvageAt + ")");
        salvageAt = null;
        salvageStep = sortStep = null;
        return false;
    }

    /**
     * Whether salvage is being sorted: a salvaging station was used nearby and its XP keeps coming
     * (each drop extends it). Walking or sailing off, a long pause, or running out of salvage to
     * sort ends it, so a wreck's own XP doesn't keep it going.
     */
    private boolean sorting(WorldPoint pos, int tick) {
        if (sortingAt == null) return false;
        if (tick - sortingTick <= SORTING_GAP_TICKS
                && (pos == null || pos.distanceTo2D(sortingAt) <= SESSION_RADIUS)) {
            sortingTick = tick;
            // The last piece's XP can arrive after it left the inventory: count it, then stop.
            if (salvageInInventory() == null) {
                host.trace("SORTING ended (no salvage left)");
                sortingAt = null;
            }
            return true;
        }
        host.trace("SORTING ended");
        sortingAt = null;
        return false;
    }

    /** The first salvage item in the inventory, e.g. "Opulent salvage", or null. */
    private String salvageInInventory() {
        ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
        if (inv == null) return null;
        for (Item item : inv.getItems()) {
            if (item.getId() <= 0) continue;
            String name = client.getItemDefinition(item.getId()).getName();
            if (name != null && name.toLowerCase().endsWith(" salvage")) return name;
        }
        return null;
    }

    /** The name of the shipwreck object nearest {@code at} (all eight end in "shipwreck"), or null. */
    private String nearestShipwreck(WorldPoint at) {
        if (at == null) return null;
        WorldView wv = client.getTopLevelWorldView();
        LocalPoint c = wv == null ? null : LocalPoint.fromWorld(wv, at);
        if (c == null) return null;
        Tile[][] tiles = wv.getScene().getTiles()[wv.getPlane()];
        String best = null;
        int bestDist = Integer.MAX_VALUE;
        for (int x = Math.max(0, c.getSceneX() - WRECK_RADIUS); x <= Math.min(tiles.length - 1, c.getSceneX() + WRECK_RADIUS); x++) {
            for (int y = Math.max(0, c.getSceneY() - WRECK_RADIUS); y <= Math.min(tiles[x].length - 1, c.getSceneY() + WRECK_RADIUS); y++) {
                Tile t = tiles[x][y];
                if (t == null) continue;
                for (GameObject obj : t.getGameObjects()) {
                    if (obj == null) continue;
                    ObjectComposition def = client.getObjectDefinition(obj.getId());
                    if (def != null && def.getImpostorIds() != null) def = def.getImpostor();
                    String name = def == null ? null : def.getName();
                    if (name == null || !name.toLowerCase().endsWith("shipwreck")) continue;
                    int d = Math.max(Math.abs(x - c.getSceneX()), Math.abs(y - c.getSceneY()));
                    if (d < bestDist) { bestDist = d; best = name; }
                }
            }
        }
        return best;
    }

    /** The stop on the shoal's route nearest {@code pos} (where the boat is trawling), or {@code pos}. */
    private static WorldPoint shoalStopNear(WorldPoint pos) {
        if (pos == null) return null;
        ShoalRoutes.Route route = ShoalRoutes.find(-1, pos, SHOAL_ROUTE_TILES);
        if (route == null) return pos;
        WorldPoint best = pos;
        int bestDist = Integer.MAX_VALUE;
        for (WorldPoint stop : route.stops) {
            int d = stop.distanceTo2D(pos);
            if (d < bestDist) { bestDist = d; best = stop; }
        }
        return best;
    }
}

package com.routeplanner.sailing;

import net.runelite.client.util.Text;

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads deep sea trawling catches from chat (Sailing): "You catch three giant krill." for the
 * player's net and "Jobless Jim catches two giant krill." for a crewmate's. The fish land in the net,
 * not the inventory, and the game doesn't send the net's contents while fishing, so the messages
 * are the only count. Wording as read by Maewi's Deep Sea Trawling plugin.
 */
public final class CatchMessages {

    public static final class Catch {
        public final String fish;
        public final int count;

        Catch(String fish, int count) {
            this.fish = fish;
            this.count = count;
        }
    }

    private static final Pattern CATCH = Pattern.compile("^(?:You catch|.+? catches) (\\S+) (.+?)[.!]?$");
    private static final Map<String, Integer> WORDS = new HashMap<>();
    static {
        String[] words = {"zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
            "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen", "twenty"};
        for (int i = 0; i < words.length; i++) WORDS.put(words[i], i);
        WORDS.put("a", 1);
        WORDS.put("an", 1);
    }

    private CatchMessages() {}

    /** The catch in a game message, or null if it isn't one. "Trawler's trust" extras come as their own catch. */
    public static Catch parse(String message) {
        if (message == null) return null;
        String msg = Text.removeTags(message).trim();
        if (msg.contains("Trawler's trust")) return null;
        Matcher m = CATCH.matcher(msg);
        if (!m.matches()) return null;
        String amount = m.group(1).toLowerCase();
        Integer count = WORDS.get(amount);
        if (count == null) {
            try {
                count = Integer.parseInt(amount);
            } catch (NumberFormatException e) {
                return null;
            }
        }
        if (count <= 0) return null;
        String fish = m.group(2).trim();
        return fish.isEmpty() ? null : new Catch(Character.toUpperCase(fish.charAt(0)) + fish.substring(1), count);
    }

    /** Whether two fish names are the same kind ("Giant krill", "giant krill"; "Haddock", "Haddocks"). */
    public static boolean sameFish(String a, String b) {
        if (a == null || b == null) return false;
        return key(a).equals(key(b));
    }

    private static String key(String fish) {
        String k = fish.trim().toLowerCase();
        return k.endsWith("s") ? k.substring(0, k.length() - 1) : k;
    }
}

package com.routeplanner.sailing;

import com.routeplanner.RoutePlannerConfig;
import net.runelite.api.Client;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldEntityConfig;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.*;

/**
 * While trawling, lights up "Lower net" or "Raise net" in the Sailing side panel for each net in the
 * water at a different depth from the shoal (the wrong depth halves the catch). Button positions as
 * in Maewi's Deep Sea Trawling plugin.
 */
public class NetDepthOverlay extends Overlay {

    private static final int SIDEPANEL_GROUP = 937;
    private static final int FACILITIES_CHILD = 25;
    private static final int SIDEPANEL_CANVAS_CHILD = 5;
    /** Boat config ids: a skiff has one net, a sloop two. */
    private static final int SKIFF = 2, SLOOP = 3;
    /** Child indexes of the Lower and Raise buttons: a skiff's net, then a sloop's starboard and port. */
    private static final int SKIFF_LOWER = 29, SKIFF_RAISE = 30;
    private static final int STARBOARD_LOWER = 41, STARBOARD_RAISE = 42;
    private static final int PORT_LOWER = 45, PORT_RAISE = 46;

    private final Client client;
    private final RoutePlannerConfig config;

    @Inject
    public NetDepthOverlay(Client client, RoutePlannerConfig config) {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        WorldEntity boat = Sailing.boat(client);
        WorldEntityConfig boatCfg = boat == null ? null : boat.getConfig();
        if (boatCfg == null || (boatCfg.getId() != SKIFF && boatCfg.getId() != SLOOP)) return null;
        int want = Shoals.depth(Shoals.nearest(client));
        if (want <= 0) return null;

        int nets = boatCfg.getId() == SLOOP ? 2 : 1;
        for (int net = 0; net < nets; net++) {
            int now = Shoals.netDepth(client, net);
            if (now <= 0 || now == want) continue;   // raised, or already right
            boolean lower = now < want;
            int child = boatCfg.getId() == SKIFF ? (lower ? SKIFF_LOWER : SKIFF_RAISE)
                : net == 0 ? (lower ? STARBOARD_LOWER : STARBOARD_RAISE)
                : (lower ? PORT_LOWER : PORT_RAISE);
            highlight(graphics, child);
        }
        return null;
    }

    private void highlight(Graphics2D g, int child) {
        Widget parent = client.getWidget(SIDEPANEL_GROUP, FACILITIES_CHILD);
        Widget canvas = client.getWidget(SIDEPANEL_GROUP, SIDEPANEL_CANVAS_CHILD);
        Widget button = parent == null ? null : parent.getChild(child);
        if (button == null || button.isHidden() || canvas == null) return;
        Rectangle b = button.getBounds();
        // Scrolled out of the panel's view: nothing to point at
        if (b == null || b.width <= 0 || b.height <= 0 || !canvas.getBounds().intersects(b)) return;
        Color c = config.npcHighlightColor();
        g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 110));
        g.fillRoundRect(b.x, b.y, b.width, b.height, 8, 8);
        g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 230));
        g.setStroke(new BasicStroke(2));
        g.drawRoundRect(b.x, b.y, b.width, b.height, 8, 8);
    }
}

package com.routeplanner.sailing;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldEntityConfig;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/**
 * Where the player really is while sailing. On a boat the player stands in the boat's own world
 * view, so {@code getWorldLocation()} gives a tile on the boat's deck, not on the sea. The boat
 * itself is a world entity in the top-level world, and its position is the one that matters for
 * routing, arrival and drawing.
 */
public final class Sailing {

    private Sailing() {}


    /** The boat the player is on, or null when they're not on one. */
    public static WorldEntity boat(Client client) {
        Player player = client.getLocalPlayer();
        if (player == null) return null;
        WorldView wv = player.getWorldView();
        if (wv == null || wv.isTopLevel()) return null;
        WorldView top = client.getTopLevelWorldView();
        if (top == null || top.worldEntities() == null) return null;
        return top.worldEntities().byIndex(wv.getId());
    }

    public static boolean isSailing(Client client) {
        return boat(client) != null;
    }

    /** The player's tile in the top-level world: the boat's tile while sailing. Null if logged out. */
    public static WorldPoint position(Client client) {
        Player player = client.getLocalPlayer();
        if (player == null) return null;
        WorldEntity boat = boat(client);
        if (boat != null) {
            LocalPoint lp = boat.getLocalLocation();
            // Mid-hop the world view can be rebuilding; the deck tile is better than nothing.
            if (lp != null && client.getWorldView(lp.getWorldView()) != null) {
                return WorldPoint.fromLocalInstance(client, lp);
            }
        }
        return player.getWorldLocation();
    }

    /**
     * How many tiles {@code tile} is from the player's boat: 0 when the hull covers it, otherwise the
     * gap to the nearest edge of the hull. -1 when the player isn't on a boat, or its size isn't known.
     * While sailing the boat stands in for the player, and a sloop is ten tiles long, so arriving is
     * measured from the hull rather than from the boat's centre.
     */
    public static int hullDistance(Client client, WorldPoint tile) {
        WorldEntity boat = boat(client);
        if (boat == null || tile == null) return -1;
        WorldEntityConfig hull = boat.getConfig();
        LocalPoint lp = boat.getLocalLocation();
        WorldView top = client.getTopLevelWorldView();
        if (hull == null || lp == null || top == null || hull.getBoundsWidth() <= 0 || hull.getBoundsHeight() <= 0) return -1;
        if (tile.getPlane() != top.getPlane()) return Integer.MAX_VALUE;

        // From the boat's centre to the middle of the tile, in local units (128 per tile)
        int dx = tile.getX() * Perspective.LOCAL_TILE_SIZE + Perspective.LOCAL_HALF_TILE_SIZE
            - (lp.getX() + top.getBaseX() * Perspective.LOCAL_TILE_SIZE);
        int dy = tile.getY() * Perspective.LOCAL_TILE_SIZE + Perspective.LOCAL_HALF_TILE_SIZE
            - (lp.getY() + top.getBaseY() * Perspective.LOCAL_TILE_SIZE);
        // Into the boat's own frame, undoing the turn the game gives its model (see the bounds getters)
        int angle = boat.getOrientation() & 2047;
        long cos = Perspective.COSINE[angle], sin = Perspective.SINE[angle];
        long mx = (dx * cos - dy * sin) >> 16;
        long my = (dx * sin + dy * cos) >> 16;
        long outX = Math.max(0, Math.abs(mx - hull.getBoundsX()) - hull.getBoundsWidth() / 2);
        long outY = Math.max(0, Math.abs(my - hull.getBoundsY()) - hull.getBoundsHeight() / 2);
        // The tile's own half-width counts as touching
        long gap = Math.max(0, Math.max(outX, outY) - Perspective.LOCAL_HALF_TILE_SIZE);
        return (int) ((gap + Perspective.LOCAL_TILE_SIZE - 1) / Perspective.LOCAL_TILE_SIZE);
    }

    /**
     * Whether the player is within {@code tiles} of {@code tile}: from the hull while sailing,
     * otherwise from where they stand.
     */
    public static boolean isWithin(Client client, WorldPoint tile, int tiles) {
        int hull = hullDistance(client, tile);
        if (hull >= 0) return hull <= tiles;
        WorldPoint at = position(client);
        return at != null && tile != null && at.distanceTo(tile) <= tiles;
    }
}

package com.routeplanner.sailing;

import com.routeplanner.transport.Transport;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;

/**
 * Sailing mooring points as routing edges between the land and the sea. The collision map keeps
 * the open sea walkable but cut off from the land, so without these a route can never leave the
 * shore: a dock joins its gangplank tile to the sea tile beside it.
 *
 * <p>Boarding only works where one of the player's boats is moored. The game keeps each boat's port
 * in a varbit but its values aren't documented, so they are learned: when a boat's port changes while
 * the player is at a dock, that value means that dock. Until every boat's port is known, any dock
 * the player's Sailing level allows can be boarded from.
 */
@Slf4j
@Singleton
public class SailingDocks {

    public static final String BOARD = "Board your boat";
    public static final String DISEMBARK = "Disembark";

    private static final int[] BOAT_PORT_VARBITS = {
        VarbitID.SAILING_BOAT_1_PORT, VarbitID.SAILING_BOAT_2_PORT, VarbitID.SAILING_BOAT_3_PORT,
        VarbitID.SAILING_BOAT_4_PORT, VarbitID.SAILING_BOAT_5_PORT
    };
    private static final int[] BOAT_OWNED_VARBITS = {
        VarbitID.SAILING_BOAT_1_OWNED, VarbitID.SAILING_BOAT_2_OWNED, VarbitID.SAILING_BOAT_3_OWNED,
        VarbitID.SAILING_BOAT_4_OWNED, VarbitID.SAILING_BOAT_5_OWNED
    };
    /** Port values that aren't a dock: the boat is lost at sea (253), capsized (254) or bottled (255). */
    private static final int FIRST_NOT_DOCKED = 253;
    private static final String CONFIG_GROUP = "routeplanner";
    private static final String PORTS_KEY = "sailingPorts";
    /** How close to a dock the player must be for a port change to be credited to it. */
    private static final int LEARN_RADIUS = 12;

    public static final class Dock {
        public final String name;
        public final int level;
        public final WorldPoint land;
        public final WorldPoint sea;
        /** The game's id for the dock, a boat's port varbit while moored there; -1 if not known. */
        public final int portId;

        Dock(String name, int level, WorldPoint land, WorldPoint sea, int portId) {
            this.name = name;
            this.level = level;
            this.land = land;
            this.sea = sea;
            this.portId = portId;
        }
    }

    /** A precomputed sea route between two moorings: its length and the straight legs that sail it. */
    public static final class SeaRoute {
        public final WorldPoint from;
        public final WorldPoint to;
        public final int tiles;
        /** Turning points from {@code from} to {@code to}, both included. */
        public final List<WorldPoint> waypoints;

        SeaRoute(WorldPoint from, WorldPoint to, int tiles, List<WorldPoint> waypoints) {
            this.from = from;
            this.to = to;
            this.tiles = tiles;
            this.waypoints = waypoints;
        }

        SeaRoute reversed() {
            List<WorldPoint> back = new ArrayList<>(waypoints);
            Collections.reverse(back);
            return new SeaRoute(to, from, tiles, back);
        }
    }

    private final Client client;
    private final ConfigManager configManager;

    private final List<Dock> docks = new ArrayList<>();
    /** Mooring -> the sea routes leaving it. A search over open water can't find a far dock round a
     *  coast without exploring millions of tiles, so these are worked out ahead of time. */
    private final Map<String, Map<WorldPoint, List<SeaRoute>>> seaRoutesBySize = new HashMap<>();
    /** Water tile -> water tiles a boat reaches through a cave mouth or similar the map doesn't join. */
    private final Map<WorldPoint, List<WorldPoint>> seaLinks = new HashMap<>();
    /** Port varbit value -> dock name, learned in game and kept in the config. */
    private final Map<Integer, String> learnedPorts = new HashMap<>();
    private final int[] lastPorts = new int[BOAT_PORT_VARBITS.length];
    private final boolean[] owned = new boolean[BOAT_PORT_VARBITS.length];
    /** False until the ports have been read once since logging in, so the login itself isn't a change. */
    private boolean portsRead = false;
    /** Routing edges for the current level and boats: tile -> tiles one dock crossing away. */
    private volatile Map<WorldPoint, List<WorldPoint>> edges = Collections.emptyMap();
    private int edgesLevel = -1;
    private String edgesBoats = null;

    @Inject
    public SailingDocks(Client client, ConfigManager configManager) {
        this.client = client;
        this.configManager = configManager;
        load();
    }

    public List<Dock> getDocks() { return docks; }

    private void load() {
        try (InputStream is = getClass().getResourceAsStream("/com/routeplanner/sailing/docks.tsv")) {
            if (is == null) { log.warn("Route Planner: docks.tsv not found"); return; }
            BufferedReader br = new BufferedReader(new InputStreamReader(is));
            String line;
            while ((line = br.readLine()) != null) {
                if (line.isEmpty() || line.startsWith("#")) continue;
                String[] cols = line.split("\t");
                if (cols.length < 4) continue;
                WorldPoint land = parsePoint(cols[2]), sea = parsePoint(cols[3]);
                if (land == null || sea == null) continue;
                try {
                    int portId = cols.length > 4 ? Integer.parseInt(cols[4].trim()) : -1;
                    docks.add(new Dock(cols[0], Integer.parseInt(cols[1].trim()), land, sea, portId));
                } catch (NumberFormatException ignored) {}
            }
        } catch (Exception e) {
            log.warn("Route Planner: failed to load docks.tsv: {}", e.toString());
        }
        log.info("Route Planner: {} sailing docks", docks.size());
        loadSeaLinks();
    }

    private void loadSeaLinks() {
        try (InputStream is = getClass().getResourceAsStream("/com/routeplanner/sailing/sea_links.tsv")) {
            if (is == null) return;
            BufferedReader br = new BufferedReader(new InputStreamReader(is));
            String line;
            while ((line = br.readLine()) != null) {
                if (line.isEmpty() || line.startsWith("#")) continue;
                String[] cols = line.split("\t");
                if (cols.length < 2) continue;
                WorldPoint a = parsePoint(cols[0]), b = parsePoint(cols[1]);
                if (a == null || b == null) continue;
                seaLinks.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
                seaLinks.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
            }
        } catch (Exception e) {
            log.warn("Route Planner: failed to load sea_links.tsv: {}", e.toString());
        }
    }

    /** Every sea link as {from, to}, both ways round. */
    public List<WorldPoint[]> getSeaLinkPairs() {
        List<WorldPoint[]> pairs = new ArrayList<>();
        for (Map.Entry<WorldPoint, List<WorldPoint>> e : seaLinks.entrySet()) {
            for (WorldPoint to : e.getValue()) pairs.add(new WorldPoint[]{e.getKey(), to});
        }
        return pairs;
    }

    /** Water tiles a boat at {@code p} can sail straight through to (a cave mouth), or null. */
    public List<WorldPoint> seaLinksFrom(WorldPoint p) {
        return seaLinks.get(p);
    }

    /**
     * The sea route set for a boat this wide: each boat size has its own (generated with the same rules
     * as live pathing), so a sloop's routes keep out of gaps a raft can take. Loaded on first use.
     */
    private synchronized Map<WorldPoint, List<SeaRoute>> seaRoutes(int boatWidthTiles) {
        String size = boatWidthTiles >= 3 ? "sloop" : boatWidthTiles == 2 ? "skiff" : "raft";
        Map<WorldPoint, List<SeaRoute>> routes = seaRoutesBySize.get(size);
        if (routes == null) {
            routes = loadSeaRoutes("/com/routeplanner/sailing/sea_routes_" + size + ".tsv");
            seaRoutesBySize.put(size, routes);
        }
        return routes;
    }

    private Map<WorldPoint, List<SeaRoute>> loadSeaRoutes(String resource) {
        Map<WorldPoint, List<SeaRoute>> routes = new HashMap<>();
        int count = 0;
        try (InputStream is = getClass().getResourceAsStream(resource)) {
            if (is == null) { log.warn("Route Planner: {} not found", resource); return routes; }
            BufferedReader br = new BufferedReader(new InputStreamReader(is));
            String line;
            while ((line = br.readLine()) != null) {
                if (line.isEmpty() || line.startsWith("#")) continue;
                String[] cols = line.split("\t");
                if (cols.length < 4) continue;
                WorldPoint from = parsePoint(cols[0]), to = parsePoint(cols[1]);
                if (from == null || to == null) continue;
                List<WorldPoint> waypoints = new ArrayList<>();
                for (String wp : cols[3].split(";")) {
                    WorldPoint p = parsePoint(wp + " " + from.getPlane());
                    if (p != null) waypoints.add(p);
                }
                SeaRoute route;
                try {
                    route = new SeaRoute(from, to, Integer.parseInt(cols[2].trim()), waypoints);
                } catch (NumberFormatException e) {
                    continue;
                }
                routes.computeIfAbsent(from, k -> new ArrayList<>()).add(route);
                routes.computeIfAbsent(to, k -> new ArrayList<>()).add(route.reversed());
                count++;
            }
        } catch (Exception e) {
            log.warn("Route Planner: failed to load {}: {}", resource, e.toString());
        }
        log.info("Route Planner: {} sea routes from {}", count, resource);
        return routes;
    }

    /** The precomputed sea routes for a boat this wide leaving the mooring at {@code p}, or null. */
    public List<SeaRoute> seaRoutesFrom(WorldPoint p, int boatWidthTiles) {
        return seaRoutes(boatWidthTiles).get(p);
    }

    /** The precomputed sea route for a boat this wide from one mooring to another, or null. */
    public SeaRoute seaRoute(WorldPoint from, WorldPoint to, int boatWidthTiles) {
        List<SeaRoute> routes = seaRoutes(boatWidthTiles).get(from);
        if (routes == null) return null;
        for (SeaRoute r : routes) if (r.to.equals(to)) return r;
        return null;
    }

    /** Reads the learned ports back from the config; call once the config is available. */
    public void loadLearnedPorts() {
        learnedPorts.clear();
        String saved = configManager.getConfiguration(CONFIG_GROUP, PORTS_KEY);
        if (saved == null || saved.isEmpty()) return;
        for (String pair : saved.split(";")) {
            int eq = pair.indexOf('=');
            if (eq <= 0) continue;
            try {
                learnedPorts.put(Integer.parseInt(pair.substring(0, eq)), pair.substring(eq + 1));
            } catch (NumberFormatException ignored) {}
        }
        edgesBoats = null;
    }

    private void saveLearnedPorts() {
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<Integer, String> e : learnedPorts.entrySet()) {
            if (sb.length() > 0) sb.append(';');
            sb.append(e.getKey()).append('=').append(e.getValue());
        }
        configManager.setConfiguration(CONFIG_GROUP, PORTS_KEY, sb.toString());
    }

    /**
     * Once a tick: learns a boat's port when it changes next to a dock, and rebuilds the routing
     * edges when the Sailing level or the boats' ports change.
     */
    public void onGameTick() {
        WorldPoint at = Sailing.position(client);
        for (int i = 0; i < BOAT_PORT_VARBITS.length; i++) {
            int port = client.getVarbitValue(BOAT_PORT_VARBITS[i]);
            owned[i] = client.getVarbitValue(BOAT_OWNED_VARBITS[i]) != 0;
            // The bundled ids cover every known dock; only a new one is learned from where it's moored
            if (portsRead && owned[i] && port != lastPorts[i] && port < FIRST_NOT_DOCKED && dockById(port) == null && at != null) {
                Dock dock = nearest(at, LEARN_RADIUS);
                if (dock != null && !dock.name.equals(learnedPorts.get(port))) {
                    learnedPorts.put(port, dock.name);
                    saveLearnedPorts();
                    log.debug("Route Planner: sailing port {} is {}", port, dock.name);
                }
            }
            lastPorts[i] = port;
        }
        portsRead = true;

        int level = client.getRealSkillLevel(Skill.SAILING);
        String boats = Arrays.toString(lastPorts) + Arrays.toString(owned) + learnedPorts.size();
        if (level != edgesLevel || !boats.equals(edgesBoats)) {
            edgesLevel = level;
            edgesBoats = boats;
            edges = buildEdges(level);
        }
    }

    /** Forget the last-read ports, e.g. on logout, so the next login's values aren't taken as moves. */
    public void reset() {
        portsRead = false;
    }

    /** What to tell the player about boarding at {@code dock}, e.g. "Board your boat at Port Sarim". */
    public String boardingHint(WorldPoint dock) {
        Dock d = dock == null ? null : nearest(dock, 15);
        return d != null ? BOARD + " at " + d.name : BOARD;
    }

    /** The dock whose gangplank or mooring is within {@code radius} tiles of {@code p}, nearest first. */
    public Dock nearest(WorldPoint p, int radius) {
        Dock best = null;
        int bestDist = Integer.MAX_VALUE;
        for (Dock d : docks) {
            if (d.land.getPlane() != p.getPlane()) continue;
            int dist = Math.min(d.land.distanceTo2D(p), d.sea.distanceTo2D(p));
            if (dist <= radius && dist < bestDist) { best = d; bestDist = dist; }
        }
        return best;
    }

    private Map<WorldPoint, List<WorldPoint>> buildEdges(int level) {
        Set<String> moored = mooredDocks();
        Map<WorldPoint, List<WorldPoint>> map = new HashMap<>();
        for (Dock d : docks) {
            if (level > 0 && d.level > level) continue;
            // Getting off works at any dock the level allows; getting on needs a boat there.
            map.computeIfAbsent(d.sea, k -> new ArrayList<>()).add(d.land);
            if (moored == null || moored.contains(d.name)) {
                map.computeIfAbsent(d.land, k -> new ArrayList<>()).add(d.sea);
            }
        }
        return map;
    }

    /**
     * Names of the docks the player's boats are moored at, or null when any owned boat's dock isn't known
     * (then any dock can be boarded from). Lost, capsized or bottled boats aren't at a dock.
     */
    private Set<String> mooredDocks() {
        Set<String> names = new HashSet<>();
        for (int i = 0; i < lastPorts.length; i++) {
            int port = lastPorts[i];
            if (!owned[i] || port >= FIRST_NOT_DOCKED) continue;
            Dock dock = dockById(port);
            String name = dock != null ? dock.name : learnedPorts.get(port);
            if (name == null) return null;
            names.add(name);
        }
        return names.isEmpty() ? null : names;
    }

    /** The dock with the game id {@code portId}, or null. */
    private Dock dockById(int portId) {
        for (Dock d : docks) if (d.portId == portId) return d;
        return null;
    }

    /** Tiles near a mooring, where a boat has to come alongside land: packed x << 16 | y, per radius. */
    private final Map<Integer, Set<Integer>> nearMoorings = new HashMap<>();

    /** Whether (x, y) is within {@code radius} tiles of a mooring. */
    public synchronized boolean nearMooring(int x, int y, int radius) {
        Set<Integer> tiles = nearMoorings.get(radius);
        if (tiles == null) {
            tiles = new HashSet<>();
            for (Dock d : docks) {
                for (int dx = -radius; dx <= radius; dx++) {
                    for (int dy = -radius; dy <= radius; dy++) tiles.add(((d.sea.getX() + dx) << 16) | (d.sea.getY() + dy));
                }
            }
            // and both ends of each cave mouth
            for (WorldPoint p : seaLinks.keySet()) {
                for (int dx = -radius; dx <= radius; dx++) {
                    for (int dy = -radius; dy <= radius; dy++) tiles.add(((p.getX() + dx) << 16) | (p.getY() + dy));
                }
            }
            nearMoorings.put(radius, tiles);
        }
        return tiles.contains((x << 16) | y);
    }

    /** Whether {@code p} is the sea side of a dock, where the boat is left. */
    public boolean isMooring(WorldPoint p) {
        for (Dock d : docks) if (d.sea.equals(p)) return true;
        return false;
    }

    /** Tiles one dock crossing away from {@code p}, or null. */
    public List<WorldPoint> edgesFrom(WorldPoint p) {
        return edges.get(p);
    }

    /** The dock crossing from {@code a} to {@code b} as a transition to highlight, or null if it isn't one. */
    public Transport crossing(WorldPoint a, WorldPoint b) {
        List<WorldPoint> dests = edges.get(a);
        if (dests == null || !dests.contains(b)) return null;
        for (Dock d : docks) {
            if (d.land.equals(a) && d.sea.equals(b)) return new Transport(a, b, BOARD + " at " + d.name, -1);
            if (d.sea.equals(a) && d.land.equals(b)) return new Transport(a, b, DISEMBARK + " at " + d.name, -1);
        }
        return null;
    }

    private static WorldPoint parsePoint(String s) {
        String[] parts = s.trim().split("\\s+");
        if (parts.length < 3) return null;
        try {
            return new WorldPoint(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));
        } catch (NumberFormatException e) {
            return null;
        }
    }
}

package com.routeplanner.sailing;

import com.routeplanner.RoutePlannerConfig;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Perspective;
import net.runelite.api.Skill;
import net.runelite.api.Tile;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.List;

/**
 * Countdowns and the voyage time for the HUD while sailing:
 *
 *  - "Shoal moves in 0:32": a shoal that's stopped stays for a set time by its fish, counted from
 *    when it was seen to stop (as Maewi's Deep Sea Trawling plugin does).
 *  - The wrecks sunk alert: every shipwreck being salvaged (each one in hook reach, so a crewmate's hook
 *    on a second wreck counts too) has sunk, so it's time to move on. Wrecks last different times, so a
 *    sound when they're all gone beats a countdown for each.
 *  - "Arrive in 1:23": the sea route left at the boat's speed (halfway between its base speed and its
 *    speed cap), shown while it's under way.
 *
 * Each counts down second by second from when it will end, rather than jumping a tick at a time.
 */
@Singleton
public class SailingTimers {

    /** Only things this close to the boat get a countdown. */
    private static final int NEAR_TILES = 30;
    /** How near the hull a shipwreck must be for a hook to reach it, in tiles. */
    private static final int HOOK_REACH = 4;
    /** How far from the boat to look for shipwrecks. */
    private static final int WRECK_RADIUS = 12;
    /** Points further apart than this on the route are a jump (a cave mouth), not sailed. */
    private static final int MAX_STEP_TILES = 5;
    /** How quickly the measured speed follows a change: 0..1, higher is quicker. */
    private static final double SPEED_SMOOTHING = 0.25;
    /** Below this many tiles a tick the boat isn't really under way, and an arrival time would be silly. */
    private static final double MIN_SPEED = 0.3;
    /** A game tick, in milliseconds. */
    private static final long TICK_MS = 600;
    /** The arrival time is only re-estimated when it's off by more than this (or 15%). */
    private static final long ETA_SLACK_MS = 3000;

    private final Client client;
    private final RoutePlannerConfig config;

    private int shoalId = -1;
    private WorldPoint shoalLast;
    private int movingTicks, stoppedTicks;
    private boolean shoalWasMoving;
    /** When each countdown ends, in wall-clock milliseconds, so the HUD counts down second by second. */
    private long shoalMovesAt = -1;

    /** The wrecks being salvaged (in hook reach since a hook went down or salvage came in), by their tile. */
    private final java.util.Set<WorldPoint> wrecks = new java.util.LinkedHashSet<>();
    private final net.runelite.client.audio.AudioPlayer audioPlayer;
    private final net.runelite.client.Notifier notifier;

    private WorldPoint boatLast;
    private double measured;   // tiles per tick, over the last few ticks
    /** The expected arrival, in wall-clock milliseconds; re-estimated only when it's clearly off. */
    private long arrivalAt = -1;

    @Inject
    public SailingTimers(Client client, RoutePlannerConfig config, net.runelite.client.audio.AudioPlayer audioPlayer,
                         net.runelite.client.Notifier notifier) {
        this.client = client;
        this.config = config;
        this.audioPlayer = audioPlayer;
        this.notifier = notifier;
    }

    /** Once a tick, from the plugin: follows the nearest shoal, the wreck being salvaged and the boat's speed. */
    public void onGameTick() {
        if (!Sailing.isSailing(client)) {
            boatLast = null;
            measured = 0;
            arrivalAt = -1;
            return;
        }
        int tick = client.getTickCount();
        WorldPoint boat = Sailing.position(client);
        if (boat != null && boatLast != null) {
            double moved = Math.hypot(boat.getX() - boatLast.getX(), boat.getY() - boatLast.getY());
            if (moved <= MAX_STEP_TILES) measured += (moved - measured) * SPEED_SMOOTHING;
        }
        boatLast = boat;
        followShoal(tick);
        boolean sank = false;
        java.util.Iterator<WorldPoint> it = wrecks.iterator();
        while (it.hasNext()) {
            WorldPoint wreck = it.next();
            if (!activeWreckAt(wreck)) { sank = true; it.remove(); }
            else if (!near(wreck, boat)) it.remove();   // sailed off: no alert for those
        }
        // The last one being salvaged just sank, and there's nothing else in reach to salvage
        if (sank && wrecks.isEmpty() && wrecksInReach().isEmpty()) wrecksSunkAlert();
    }

    /** Every wreck being salvaged has sunk: the alert picked in the config. */
    private void wrecksSunkAlert() {
        switch (config.wreckAlert()) {
            case BOSUNS_CALL:
                int volume = config.wreckAlertVolume();
                if (volume <= 0) break;
                try {
                    // The volume setting as gain in decibels: 100 plays the sound as made, 50 about half as loud
                    float gainDb = (float) (20 * Math.log10(Math.min(100, volume) / 100.0));
                    audioPlayer.play(SailingTimers.class, "/com/routeplanner/sailing/bosun-call.wav", gainDb);
                } catch (Exception e) {
                    java.awt.Toolkit.getDefaultToolkit().beep();   // no sound device for it: at least a beep
                }
                break;
            case SYSTEM:
                java.awt.Toolkit.getDefaultToolkit().beep();
                break;
            case RUNELITE:
                notifier.notify("All wrecks have sunk");
                break;
            default:
                break;
        }
    }

    /**
     * The boat's sailing speed in tiles per tick: halfway between its base speed and its speed cap (the
     * side panel's stats, in 128ths of a tile a tick), which holds steady where the speed measured
     * tick by tick jumps about. The measured speed when the stats aren't known.
     */
    private double speed() {
        int base = client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_BASESPEED);
        int cap = client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_SPEEDCAP);
        if (base > 0 && cap > 0) return (base + cap) / 2.0 / Perspective.LOCAL_TILE_SIZE;
        if (base > 0) return base / (double) Perspective.LOCAL_TILE_SIZE;
        return measured;
    }

    /**
     * Watches the nearest shoal move and stop. Moving for two ticks then still for two is a stop; the
     * countdown starts then, from how long that shoal's fish stay (two ticks already gone).
     */
    private void followShoal(int tick) {
        WorldEntity shoal = Shoals.nearest(client);
        LocalPoint lp = shoal == null ? null : shoal.getLocalLocation();
        int id = shoal == null || shoal.getWorldView() == null ? -1 : shoal.getWorldView().getId();
        if (lp == null || id != shoalId) {
            shoalId = id;
            shoalLast = null;
            movingTicks = stoppedTicks = 0;
            shoalWasMoving = false;
            shoalMovesAt = -1;
            if (lp == null) return;
        }
        WorldPoint at = WorldPoint.fromLocalInstance(client, lp);
        if (shoalLast != null) {
            if (at.equals(shoalLast)) { stoppedTicks++; movingTicks = 0; }
            else { movingTicks++; stoppedTicks = 0; }
        }
        shoalLast = at;
        if (shoalWasMoving && stoppedTicks >= 2) {
            int stay = ShoalRoutes.stopTicks(ShoalRoutes.find(id, at, 10));
            shoalMovesAt = stay > 0 ? System.currentTimeMillis() + (stay - 2) * TICK_MS : -1;
            shoalWasMoving = false;
        } else if (movingTicks >= 2) {
            shoalWasMoving = true;
            shoalMovesAt = -1;
        }
    }

    /** Deploying a salvaging hook: watch the wrecks it can reach. */
    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked e) {
        String option = Text.removeTags(e.getMenuOption()), target = Text.removeTags(e.getMenuTarget()).toLowerCase();
        if ("Deploy".equalsIgnoreCase(option) && target.contains("salvaging hook")) trackWrecks();
    }

    /** Salvage coming in (a crewmate on the hook, say) starts it too, if it hasn't started. */
    @Subscribe
    public void onStatChanged(StatChanged e) {
        if (e.getSkill() == Skill.SAILING && Sailing.isSailing(client)) trackWrecks();
    }

    /** Watches every wreck in hook reach, to know when they've all sunk. */
    private void trackWrecks() {
        wrecks.addAll(wrecksInReach());
    }

    /** The lines to show on the HUD now, e.g. "Arrive in 1:23"; empty when there's nothing to show. */
    public List<String> hudLines(List<WorldPoint> path, SailingDocks docks) {
        List<String> lines = new ArrayList<>();
        if (!Sailing.isSailing(client)) return lines;
        long now = System.currentTimeMillis();
        WorldPoint boat = Sailing.position(client);
        // Only while actually under way, with a fair stretch still to go
        double tilesLeft = sailedTilesLeft(path, docks);
        double speed = speed();
        if (measured >= MIN_SPEED && speed > 0 && tilesLeft > 5) {
            long estimate = now + (long) (tilesLeft / speed * TICK_MS);
            // Keep counting down from the last estimate unless the new one is clearly different
            long left = arrivalAt - now;
            if (arrivalAt < 0 || Math.abs(estimate - arrivalAt) > Math.max(ETA_SLACK_MS, left * 0.15)) arrivalAt = estimate;
            lines.add("Arrive in " + clock(arrivalAt - now));
        } else {
            arrivalAt = -1;
        }
        if (shoalMovesAt > now && near(shoalLast, boat)) lines.add("Shoal moves in " + clock(shoalMovesAt - now));
        return lines;
    }

    /** How far the boat has still to sail on the route: up to where it's left at a dock, not counting jumps. */
    private static double sailedTilesLeft(List<WorldPoint> path, SailingDocks docks) {
        if (path == null) return 0;
        double tiles = 0;
        for (int i = 0; i + 1 < path.size(); i++) {
            WorldPoint a = path.get(i), b = path.get(i + 1);
            if (a.getPlane() != b.getPlane() || docks.crossing(a, b) != null) break;
            double d = Math.hypot(b.getX() - a.getX(), b.getY() - a.getY());
            if (d <= MAX_STEP_TILES) tiles += d;
        }
        return tiles;
    }

    private static boolean near(WorldPoint p, WorldPoint boat) {
        return p != null && boat != null && p.distanceTo2D(boat) <= NEAR_TILES;
    }

    /** Milliseconds as m:ss, rounded up so it reaches 0:00 as the time runs out. */
    private static String clock(long millis) {
        long seconds = Math.max(0, (millis + 999) / 1000);
        return seconds / 60 + ":" + String.format("%02d", seconds % 60);
    }

    /** The tiles of shipwrecks that can be salvaged and that a hook can reach from the hull. */
    private java.util.Set<WorldPoint> wrecksInReach() {
        java.util.Set<WorldPoint> out = new java.util.LinkedHashSet<>();
        WorldPoint boat = Sailing.position(client);
        WorldView wv = client.getTopLevelWorldView();
        LocalPoint c = boat == null || wv == null ? null : LocalPoint.fromWorld(wv, boat);
        Tile[][][] all = c == null || wv.getScene() == null ? null : wv.getScene().getTiles();
        if (all == null) return out;
        Tile[][] tiles = all[wv.getPlane()];
        for (int x = Math.max(0, c.getSceneX() - WRECK_RADIUS); x <= Math.min(tiles.length - 1, c.getSceneX() + WRECK_RADIUS); x++) {
            for (int y = Math.max(0, c.getSceneY() - WRECK_RADIUS); y <= Math.min(tiles[x].length - 1, c.getSceneY() + WRECK_RADIUS); y++) {
                Tile t = tiles[x][y];
                if (t == null) continue;
                for (GameObject obj : t.getGameObjects()) {
                    // Each wreck once (from its corner tile), if any tile it covers is within reach of the hull
                    if (obj == null || !obj.getSceneMinLocation().equals(t.getSceneLocation()) || !activeWreck(obj)) continue;
                    if (inHookReach(wv, obj)) out.add(obj.getWorldLocation());
                }
            }
        }
        return out;
    }

    private boolean inHookReach(WorldView wv, GameObject obj) {
        net.runelite.api.Point min = obj.getSceneMinLocation(), max = obj.getSceneMaxLocation();
        for (int x = min.getX(); x <= max.getX(); x++) {
            for (int y = min.getY(); y <= max.getY(); y++) {
                WorldPoint tile = new WorldPoint(wv.getBaseX() + x, wv.getBaseY() + y, wv.getPlane());
                int d = Sailing.hullDistance(client, tile);
                if (d >= 0 && d <= HOOK_REACH) return true;
            }
        }
        return false;
    }

    /** Whether there's still a shipwreck that can be salvaged at {@code at} (it sinks when it runs out). */
    private boolean activeWreckAt(WorldPoint at) {
        WorldView wv = client.getTopLevelWorldView();
        LocalPoint lp = wv == null ? null : LocalPoint.fromWorld(wv, at);
        Tile[][][] all = lp == null || wv.getScene() == null ? null : wv.getScene().getTiles();
        if (all == null) return true;   // out of view: can't tell, keep counting
        Tile t = all[wv.getPlane()][lp.getSceneX()][lp.getSceneY()];
        if (t == null) return false;
        for (GameObject obj : t.getGameObjects()) if (obj != null && activeWreck(obj)) return true;
        return false;
    }

    /** A shipwreck with its Inspect option: one that can be salvaged (a sunken one has no options). */
    private boolean activeWreck(GameObject obj) {
        ObjectComposition def = client.getObjectDefinition(obj.getId());
        if (def != null && def.getImpostorIds() != null) def = def.getImpostor();
        if (def == null || def.getName() == null || !def.getName().toLowerCase().endsWith("shipwreck")) return false;
        String[] actions = def.getActions();
        if (actions != null) for (String a : actions) if (a != null && !a.isEmpty()) return true;
        return false;
    }
}

package com.routeplanner.sailing;

import com.routeplanner.RoutePlannerConfig;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.*;
import java.awt.geom.Path2D;
import java.util.List;

/**
 * While trawling (a net lowered), draws the nearest shoal's route in the waypoint line's style, its
 * dashes flowing the way the shoal swims, marks its stops, and highlights the shoal.
 *
 */
@lombok.extern.slf4j.Slf4j
public class ShoalRouteOverlay extends Overlay {

    /** Keep showing the route this long after the nets come up (between stops, changing depth). */
    private static final int AFTER_NETS_TICKS = 100;
    /** A dot in the dotted and dash-dot patterns, in tiles (drawn as a round-capped point). */
    private static final double DOT_TILES = 0.05;
    /** One full pattern of dashes slides past every this many milliseconds. */
    private static final long DASH_CYCLE_MS = 1200;
    /** Route points further apart than this aren't joined up. */
    private static final int MAX_SEGMENT_TILES = 20;

    private final Client client;
    private final RoutePlannerConfig config;
    private int netsDownTick = -1000;
    /** The last shoal whose route match was traced, so it's logged once per shoal. */
    private int tracedShoal = -1;
    /** A shoal is on a route if the route's path passes within this many tiles of it. */
    private static final int ROUTE_MATCH_TILES = 10;

    @Inject
    public ShoalRouteOverlay(Client client, RoutePlannerConfig config) {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        WorldView top = client.getTopLevelWorldView();
        if (top == null) return null;
        boolean sailing = Sailing.isSailing(client);
        if (sailing && Shoals.netsDown(client)) netsDownTick = client.getTickCount();
        boolean trawling = sailing && client.getTickCount() - netsDownTick <= AFTER_NETS_TICKS;

        // "Always show shoal routes": every route in view, shoal or no shoal
        if (config.shoalRoutesAlways()) {
            WorldPoint at = Sailing.position(client);
            int range = Math.max(30, top.getScene().getDrawDistance());
            for (ShoalRoutes.Route r : ShoalRoutes.all()) {
                // Only routes within render distance: the rest aren't worked through at all
                if (r.path.size() > 1 && at != null && r.near(at, range)) drawRoute(graphics, top, r);
            }
        }
        if (!trawling) return null;

        WorldEntity shoal = Shoals.nearest(client);
        if (shoal == null) return null;

        LocalPoint shoalLp = shoal.getLocalLocation();
        WorldPoint shoalAt = shoalLp == null ? null : WorldPoint.fromLocalInstance(client, shoalLp);
        int id = shoal.getWorldView() == null ? -1 : shoal.getWorldView().getId();
        ShoalRoutes.Route route = shoalAt == null ? null : ShoalRoutes.find(id, shoalAt, ROUTE_MATCH_TILES);
        if (id != tracedShoal && config.recordTrace()) {
            tracedShoal = id;
            log.info("[RP-TRACE] SHOAL worldview={} at={} route={}", id, shoalAt,
                route == null ? "none" : route == ShoalRoutes.get(id) ? "by id" : "by position");
        }
        if (route != null && route.path.size() > 1 && !config.shoalRoutesAlways()) drawRoute(graphics, top, route);
        highlightShoal(graphics, shoal);
        return null;
    }

    /**
     * The whole route, fixed in place like the Deep Sea Trawling plugin draws it: the path in the order
     * the shoal swims it (the dashes flow that way) wherever it's in the scene, and a marker on each stop.
     */
    private void drawRoute(Graphics2D g, WorldView top, ShoalRoutes.Route route) {
        List<WorldPoint> path = route.path;
        int plane = top.getPlane();
        int thick = config.lineThickness();
        Color c = config.lineColor();

        Path2D.Float line = new Path2D.Float();
        boolean drawing = false;
        WorldPoint prevWp = null;
        // Back to the first point at the end when it's a loop
        boolean loop = path.get(0).distanceTo2D(path.get(path.size() - 1)) <= MAX_SEGMENT_TILES;
        for (int i = 0; i < path.size() + (loop ? 1 : 0); i++) {
            WorldPoint wp = path.get(i % path.size());
            Point p = toCanvas(top, wp, plane);
            // A gap (out of the scene, or points too far apart to be one stretch) starts a new run
            if (p == null || (prevWp != null && wp.distanceTo2D(prevWp) > MAX_SEGMENT_TILES)) drawing = false;
            prevWp = wp;
            if (p == null) continue;
            if (drawing) line.lineTo(p.getX(), p.getY());
            else line.moveTo(p.getX(), p.getY());
            drawing = true;
        }
        if (config.lineGlow()) {
            g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.min(120, c.getAlpha()) / 2));
            g.setStroke(new BasicStroke(thick + 3, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            g.draw(line);
        }
        com.routeplanner.LineStyle style = config.lineStyle();
        if (style == com.routeplanner.LineStyle.SOLID) {
            g.setColor(c);
            g.setStroke(new BasicStroke(thick, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            g.draw(line);
        } else {
            if (config.lineUseDashColor()) {
                // Faint line under the dashes when they have their own color, as on the waypoint line
                g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), (int) (c.getAlpha() * 0.45)));
                g.setStroke(new BasicStroke(thick, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
                g.draw(line);
            }
            drawWaterDashes(g, top, path, loop, style, config.lineUseDashColor() ? config.lineDashColor() : c, thick);
        }

        // Where it stops (and the nets catch most): a square on the water
        g.setStroke(new BasicStroke(2));
        for (WorldPoint stop : route.stops) {
            LocalPoint lp = LocalPoint.fromWorld(top, stop);
            Polygon poly = lp == null ? null : Perspective.getCanvasTileAreaPoly(client, lp, 3);
            if (poly == null) continue;
            g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 40));
            g.fillPolygon(poly);
            g.setColor(c);
            g.drawPolygon(poly);
        }
    }

    /**
     * Dashes laid out on the water along the route, a fixed length in tiles, sliding forward the way the
     * shoal swims. Measured on screen instead (as a dashed stroke does), they'd squash and jump while the
     * boat follows the shoal and the camera moves.
     */
    private void drawWaterDashes(Graphics2D g, WorldView top, List<WorldPoint> path, boolean loop,
                                 com.routeplanner.LineStyle style, Color color, int thick) {
        // dash, gap (and a dot and gap after it for dash-dot), in tiles
        double[] pattern;
        switch (style) {
            case DOTTED:   pattern = new double[]{DOT_TILES, 0.6}; break;
            case DASH_DOT: pattern = new double[]{1.2, 0.5, DOT_TILES, 0.5}; break;
            default:       pattern = new double[]{1.2, 0.8}; break;
        }
        double period = 0;
        for (double d : pattern) period += d;
        double shift = 0;
        if (config.lineAnimate()) shift = (System.currentTimeMillis() % DASH_CYCLE_MS) / (double) DASH_CYCLE_MS * period;

        g.setColor(color);
        g.setStroke(new BasicStroke(thick, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        int plane = top.getPlane();
        double along = 0;  // distance along the route at the start of this segment, in tiles
        int n = path.size() + (loop ? 1 : 0);
        for (int i = 0; i + 1 < n; i++) {
            WorldPoint a = path.get(i % path.size()), b = path.get((i + 1) % path.size());
            double len = Math.hypot(b.getX() - a.getX(), b.getY() - a.getY());
            if (len == 0 || len > MAX_SEGMENT_TILES) { along += len; continue; }
            // Each dash and dot of the pattern that falls on this segment, the pattern moved on by shift
            double first = Math.floor((along - shift) / period) * period + shift;
            for (double start = first; start < along + len; start += period) {
                double at = start;
                for (int k = 0; k < pattern.length; k += 2) {
                    double from = Math.max(at, along), to = Math.min(at + pattern[k], along + len);
                    if (to > from || (pattern[k] == DOT_TILES && from <= to)) {
                        drawWaterLine(g, top, plane, a, b, (from - along) / len, (to - along) / len);
                    }
                    at += pattern[k] + pattern[k + 1];
                }
            }
            along += len;
        }
    }

    /** The stretch from fraction {@code f0} to {@code f1} of the way from a to b, through tile centres. */
    private void drawWaterLine(Graphics2D g, WorldView top, int plane, WorldPoint a, WorldPoint b, double f0, double f1) {
        Point p0 = waterToCanvas(top, plane, a, b, f0), p1 = waterToCanvas(top, plane, a, b, f1);
        if (p0 != null && p1 != null) g.drawLine(p0.getX(), p0.getY(), p1.getX(), p1.getY());
    }

    private Point waterToCanvas(WorldView top, int plane, WorldPoint a, WorldPoint b, double f) {
        double x = a.getX() + (b.getX() - a.getX()) * f, y = a.getY() + (b.getY() - a.getY()) * f;
        int lx = (int) Math.round((x - top.getBaseX()) * Perspective.LOCAL_TILE_SIZE) + Perspective.LOCAL_HALF_TILE_SIZE;
        int ly = (int) Math.round((y - top.getBaseY()) * Perspective.LOCAL_TILE_SIZE) + Perspective.LOCAL_HALF_TILE_SIZE;
        int size = top.getSizeX() * Perspective.LOCAL_TILE_SIZE, sizeY = top.getSizeY() * Perspective.LOCAL_TILE_SIZE;
        if (lx < 0 || ly < 0 || lx >= size || ly >= sizeY) return null;
        return Perspective.localToCanvas(client, new LocalPoint(lx, ly, top), plane);
    }

    private Point toCanvas(WorldView top, WorldPoint wp, int plane) {
        LocalPoint lp = LocalPoint.fromWorld(top, wp);
        return lp == null ? null : Perspective.localToCanvas(client, lp, plane);
    }

    /**
     * Marks the shoal with a square on the water the size of its clickbox (the biggest object in the
     * shoal's own little world), or 3x3 where the shoal is when that isn't loaded. Its fish and
     * ripple models make an odd outline, so they aren't traced.
     */
    private void highlightShoal(Graphics2D g, WorldEntity shoal) {
        LocalPoint at = shoal.getLocalLocation();
        int size = 3;
        WorldView wv = shoal.getWorldView();
        // The shoal's scene can still be loading when it comes into view
        Tile[][][] tiles = wv == null || wv.getScene() == null ? null : wv.getScene().getTiles();
        if (tiles != null && wv.getPlane() >= 0 && wv.getPlane() < tiles.length) {
            int best = 0;
            for (Tile[] row : tiles[wv.getPlane()]) {
                if (row == null) continue;
                for (Tile t : row) {
                    if (t == null) continue;
                    for (GameObject obj : t.getGameObjects()) {
                        if (obj == null) continue;
                        net.runelite.api.ObjectComposition def = client.getObjectDefinition(obj.getId());
                        if (def == null) continue;
                        int area = def.getSizeX() * def.getSizeY();
                        if (area > best && obj.getLocalLocation() != null) {
                            best = area;
                            size = Math.max(1, Math.max(def.getSizeX(), def.getSizeY()));
                            at = obj.getLocalLocation();
                        }
                    }
                }
            }
        }
        Polygon poly = at == null ? null : Perspective.getCanvasTileAreaPoly(client, at, size);
        if (poly == null) return;
        Color base = config.npcHighlightColor();
        g.setStroke(new BasicStroke(2));
        g.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), Math.max(0, Math.min(255, base.getAlpha() / 4))));
        g.fillPolygon(poly);
        g.setColor(base);
        g.drawPolygon(poly);
    }
}

package com.routeplanner.sailing;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

import java.io.InputStream;
import java.util.*;

/**
 * The fixed routes trawling shoals swim (Sailing): each shoal's path, in the order it swims, and the
 * points it stops at, keyed by the shoal's world view id. Data from Maewi's Deep Sea Trawling plugin,
 * BSD 2-Clause (see resources/com/routeplanner/sailing/LICENSE-shoals.txt).
 */
@Slf4j
public final class ShoalRoutes {

    public static final class Route {
        /** The shoal's world view id the route was recorded under; it says what fish it is (see stopTicks). */
        public final int id;
        public final List<WorldPoint> path;
        public final List<WorldPoint> stops;
        /** The box the path and stops fit in, to skip routes nowhere near the player cheaply. */
        public final int minX, minY, maxX, maxY;

        Route(int id, List<WorldPoint> path, List<WorldPoint> stops) {
            this.id = id;
            this.path = path;
            this.stops = stops;
            int x0 = Integer.MAX_VALUE, y0 = Integer.MAX_VALUE, x1 = Integer.MIN_VALUE, y1 = Integer.MIN_VALUE;
            for (List<WorldPoint> points : java.util.Arrays.asList(path, stops)) {
                for (WorldPoint p : points) {
                    x0 = Math.min(x0, p.getX()); y0 = Math.min(y0, p.getY());
                    x1 = Math.max(x1, p.getX()); y1 = Math.max(y1, p.getY());
                }
            }
            minX = x0; minY = y0; maxX = x1; maxY = y1;
        }

        /** Whether any of the route could be within {@code range} tiles of {@code p}. */
        public boolean near(WorldPoint p, int range) {
            return p.getX() >= minX - range && p.getX() <= maxX + range
                && p.getY() >= minY - range && p.getY() <= maxY + range;
        }
    }

    private static Map<Integer, Route> routes;

    private ShoalRoutes() {}

    /** The route of the shoal whose world view has id {@code worldViewId}, or null if it isn't known. */
    public static synchronized Route get(int worldViewId) {
        if (routes == null) routes = load();
        return routes.get(worldViewId);
    }

    /**
     * How long the shoal on this route stays at each stop, in ticks, by its fish: marlin 50, bluefin 70,
     * halibut 80, yellowfin 100, haddock 120, giant krill 150 (route ids and timings as in Maewi's
     * Deep Sea Trawling plugin); 0 if not known.
     */
    public static int stopTicks(Route route) {
        if (route == null) return 0;
        int id = route.id;
        if (id >= 14 && id <= 15) return 50;
        if (id >= 16 && id <= 17) return 70;
        if (id >= 18 && id <= 19) return 80;
        if (id >= 20 && id <= 22) return 100;
        if (id >= 23 && id <= 25) return 120;
        if (id >= 26 && id <= 29) return 150;
        return 0;
    }

    /** Every known shoal route. */
    public static synchronized java.util.Collection<Route> all() {
        if (routes == null) routes = load();
        return routes.values();
    }

    /**
     * The route of a shoal now at {@code at}: the one stored under its world view id if that route runs
     * near it, otherwise whichever route passes closest, within {@code maxTiles}. World view ids are
     * handed out as shoals load, so they can differ from when the routes were recorded.
     */
    public static Route find(int worldViewId, WorldPoint at, int maxTiles) {
        Route byId = get(worldViewId);
        if (byId != null && distance(byId, at) <= maxTiles) return byId;
        Route best = null;
        int bestDist = maxTiles + 1;
        for (Route r : routes.values()) {
            int d = distance(r, at);
            if (d < bestDist) { bestDist = d; best = r; }
        }
        return best;
    }

    /** How close the route's path comes to {@code at}, in tiles. */
    private static int distance(Route r, WorldPoint at) {
        int best = Integer.MAX_VALUE;
        for (WorldPoint p : r.path) {
            if (p.getPlane() != at.getPlane()) continue;
            best = Math.min(best, p.distanceTo2D(at));
        }
        return best;
    }

    private static Map<Integer, Route> load() {
        Properties props = new Properties();
        try (InputStream in = ShoalRoutes.class.getResourceAsStream("/com/routeplanner/sailing/shoals.properties")) {
            if (in == null) { log.warn("Route Planner: shoals.properties not found"); return Collections.emptyMap(); }
            props.load(in);
        } catch (Exception e) {
            log.warn("Route Planner: failed to load shoals.properties: {}", e.toString());
            return Collections.emptyMap();
        }
        Map<Integer, List<WorldPoint>> paths = new HashMap<>(), stops = new HashMap<>();
        for (String key : props.stringPropertyNames()) {
            Map<Integer, List<WorldPoint>> into = key.startsWith("shoalpath.") ? paths
                : key.startsWith("shoalstops.") ? stops : null;
            if (into == null) continue;
            try {
                into.put(Integer.parseInt(key.substring(key.indexOf('.') + 1)), parsePoints(props.getProperty(key)));
            } catch (NumberFormatException ignored) {}
        }
        Map<Integer, Route> out = new HashMap<>();
        for (Integer id : paths.keySet()) {
            out.put(id, new Route(id, paths.get(id), stops.getOrDefault(id, Collections.emptyList())));
        }
        log.info("Route Planner: {} shoal routes", out.size());
        return out;
    }

    /** "x, y, plane|x, y, plane|..." */
    private static List<WorldPoint> parsePoints(String value) {
        List<WorldPoint> points = new ArrayList<>();
        for (String part : value.split("\\|")) {
            String[] xyz = part.trim().split("\\s*,\\s*");
            if (xyz.length < 3) continue;
            try {
                points.add(new WorldPoint(Integer.parseInt(xyz[0]), Integer.parseInt(xyz[1]), Integer.parseInt(xyz[2])));
            } catch (NumberFormatException ignored) {}
        }
        return points;
    }
}

package com.routeplanner.sailing;

import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldEntityConfig;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarbitID;

/**
 * Trawling shoals (Sailing): finding the one being fished, how deep it swims, and how deep the nets
 * are. Depths are 1 shallow, 2 medium, 3 deep (0 = a raised net, or a shoal whose depth isn't known).
 * Worked out the way Maewi's Deep Sea Trawling plugin does.
 */
public final class Shoals {

    /** World entities of this config type are trawling shoals. */
    private static final int SHOAL_ENTITY_TYPE = 4;

    private Shoals() {}

    /** The nearest shoal as of a game tick, shared by the overlays that each want it every frame. */
    private static WorldEntity nearestShoal;
    private static int nearestTick = -1;

    /** The shoal nearest the player's boat, or null; worked out once per game tick. */
    public static WorldEntity nearest(Client client) {
        int tick = client.getTickCount();
        if (tick != nearestTick) {
            nearestTick = tick;
            nearestShoal = findNearest(client);
        }
        return nearestShoal;
    }

    private static WorldEntity findNearest(Client client) {
        WorldView top = client.getTopLevelWorldView();
        WorldPoint boat = Sailing.position(client);
        if (top == null || boat == null) return null;
        WorldEntity best = null;
        int bestDist = Integer.MAX_VALUE;
        for (WorldEntity e : top.worldEntities()) {
            WorldEntityConfig cfg = e.getConfig();
            LocalPoint lp = e.getLocalLocation();
            if (cfg == null || cfg.getId() != SHOAL_ENTITY_TYPE || lp == null) continue;
            int d = WorldPoint.fromLocalInstance(client, lp).distanceTo2D(boat);
            if (d < bestDist) { bestDist = d; best = e; }
        }
        return best;
    }

    /** How deep the shoal swims right now, from its ripples' animation; 0 if that can't be told. */
    public static int depth(WorldEntity shoal) {
        WorldView wv = shoal == null ? null : shoal.getWorldView();
        if (wv == null) return 0;
        for (NPC npc : wv.npcs()) {
            if (npc == null || npc.getId() != NpcID.SAILING_SHOAL_RIPPLES) continue;
            switch (npc.getAnimation()) {
                case AnimationID.DEEP_SEA_TRAWLING_SHOAL_SHALLOW:
                case AnimationID.DEEP_SEA_TRAWLING_SHOAL_SHALLOW_NOSOUND:
                    return 1;
                case AnimationID.DEEP_SEA_TRAWLING_SHOAL_MID:
                case AnimationID.DEEP_SEA_TRAWLING_SHOAL_MID_NOSOUND:
                    return 2;
                case AnimationID.DEEP_SEA_TRAWLING_SHOAL_DEEP:
                case AnimationID.DEEP_SEA_TRAWLING_SHOAL_DEEP_NOSOUND:
                    return 3;
                default:
                    return 0;
            }
        }
        return 0;
    }

    /** How deep net {@code index} (0 = starboard, or a skiff's only net; 1 = port) is; 0 = raised. */
    public static int netDepth(Client client, int index) {
        return client.getVarbitValue(index == 0 ? VarbitID.SAILING_SIDEPANEL_BOAT_TRAWLING_NET_0_DEPTH
            : VarbitID.SAILING_SIDEPANEL_BOAT_TRAWLING_NET_1_DEPTH);
    }

    /** Whether either net is in the water. */
    public static boolean netsDown(Client client) {
        return netDepth(client, 0) > 0 || netDepth(client, 1) > 0;
    }
}

