package com.routeplanner.teleport;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;

/**
 * Walks the player through a minigame teleport, one click at a time: the magic tab, the
 * Minigame Teleport spell (in every spellbook), then the minigame in the list it opens.
 * Highlight only: never clicks.
 */
@Singleton
public class MinigameTeleportOverlay extends Overlay {
    /** The magic tab's stone in each window layout (fixed, resizable classic, resizable modern, OSM). */
    private static final int[] MAGIC_TAB_STONES = {
        InterfaceID.Toplevel.STONE6, InterfaceID.ToplevelOsrsStretch.STONE6,
        InterfaceID.ToplevelPreEoc.STONE6, InterfaceID.ToplevelOsm.STONE6,
    };
    /** The Minigame Teleport spell, one per spellbook. */
    private static final int[] MINIGAME_SPELLS = {
        InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_STANDARD, InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_ANCIENT,
        InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_LUNAR, InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_ARCEUUS,
    };

    private final Client client;
    private final RoutePlannerPlugin plugin;

    @Inject
    public MinigameTeleportOverlay(Client client, RoutePlannerPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || step.getTeleportSpell() == null) return null;
        TeleportSpell spell = TeleportSpells.getByName(step.getTeleportSpell());
        String game = TeleportSpells.minigameName(spell);
        if (game == null || alreadyThere(step, spell)) return null;

        Widget target = nextClick(game);
        if (target == null) return null;
        Rectangle b = target.getBounds();
        if (b == null) return null;

        Color outline = plugin.getConfig().npcHighlightColor();
        graphics.setColor(outline);
        graphics.setStroke(new BasicStroke(2));
        graphics.drawRect(b.x - 1, b.y - 1, b.width + 2, b.height + 2);
        graphics.setColor(com.routeplanner.util.HighlightColors.fill(outline));
        graphics.fillRect(b.x - 1, b.y - 1, b.width + 2, b.height + 2);
        return null;
    }

    /** The widget the player should click next, or null if there is nothing to show. */
    private Widget nextClick(String game) {
        Widget list = visible(InterfaceID.Minigames.MINIGAMES);
        if (list != null) {
            Widget row = findRow(list, game);
            if (row == null) return null;   // every row exists even scrolled away, so it isn't unlocked
            // Scrolled out of view (its middle isn't in the list): point at the scrollbar instead.
            Rectangle r = row.getBounds();
            if (list.getBounds().contains(r.getCenterX(), r.getCenterY())) return row;
            return visible(InterfaceID.Minigames.SCROLLBAR);
        }
        for (int id : MINIGAME_SPELLS) {
            Widget spell = visible(id);
            if (spell != null) return spell;
        }
        for (int id : MAGIC_TAB_STONES) {
            Widget stone = visible(id);
            if (stone != null) return stone;
        }
        return null;
    }

    /**
     * Whether the teleport has been taken, or isn't needed: the player is already nearer the step's
     * tile than the teleport would put them (e.g. walking from Nightmare Zone to the Dragon Inn).
     */
    private boolean alreadyThere(RouteStep step, TeleportSpell spell) {
        WorldPoint goal = step.getWorldPoint() != null ? step.getWorldPoint() : spell.getDestination();
        if (client.getLocalPlayer() == null || goal == null) return false;
        WorldPoint at = client.getLocalPlayer().getWorldLocation();
        return at.getPlane() == goal.getPlane() && at.distanceTo2D(goal) <= spell.getDestination().distanceTo2D(goal) + NEAR;
    }

    /** Tiles of slack around the teleport's landing spot. */
    private static final int NEAR = 15;

    private Widget visible(int componentId) {
        Widget w = client.getWidget(componentId);
        return w == null || w.isHidden() ? null : w;
    }

    private static boolean sameGame(String text, String game) {
        if (text == null) return false;
        // Rows read "Castle Wars<br><col=808080>West of Yanille": the name is the first line
        int br = text.indexOf("<br>");
        String t = Text.removeTags(br < 0 ? text : text.substring(0, br)).trim().replaceFirst("^\\w\\s*[:)]\\s*", "").trim();
        return t.equalsIgnoreCase(game);
    }

    /** The list row (a direct child of the list) holding the minigame's name. */
    private static Widget findRow(Widget list, String game) {
        for (Widget row : children(list)) {
            if (!row.isHidden() && mentions(row, game)) return row;
        }
        return null;
    }

    /** Whether this widget or anything under it shows the minigame's name (as text or as its name). */
    private static boolean mentions(Widget w, String game) {
        if (sameGame(w.getText(), game) || sameGame(w.getName(), game)) return true;
        for (Widget child : children(w)) {
            if (mentions(child, game)) return true;
        }
        return false;
    }

    private static java.util.List<Widget> children(Widget w) {
        java.util.List<Widget> out = new java.util.ArrayList<>();
        for (Widget[] kids : new Widget[][]{w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()}) {
            if (kids == null) continue;
            for (Widget k : kids) if (k != null) out.add(k);
        }
        return out;
    }
}

package com.routeplanner.teleport;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import com.routeplanner.util.HighlightColors;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;

/**
 * For a Portal Nexus teleport step: highlights the nexus in the player's house, then the
 * step's destination row once the nexus teleport menu is open.
 * Highlight only: the plugin never clicks the nexus or picks the destination.
 */
@Singleton
public class NexusTeleportOverlay extends Overlay {

    private static final String NEXUS_NAME = "portal nexus";

    private final Client client;
    private final RoutePlannerPlugin plugin;

    @Inject
    public NexusTeleportOverlay(Client client, RoutePlannerPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || !"NEXUS".equals(step.getTeleportMethod())) return null;
        String dest = step.getTeleportNexus();
        if (dest == null || dest.trim().isEmpty()) return null;

        Widget menu = client.getWidget(InterfaceID.TelenexusTeleport.UNIVERSE);
        if (menu != null && !menu.isHidden()) {
            highlightRow(graphics, dest.trim());
        } else {
            highlightNexus(graphics);
        }
        return null;
    }

    /** Outline the whole line (text plus its clickable background) that names the destination. */
    private void highlightRow(Graphics2D graphics, String dest) {
        Rectangle[] line = {null};
        PortalNexus.forEachText(client, w -> {
            if (dest.equalsIgnoreCase(PortalNexus.cleanText(w.getText()))) {
                line[0] = line[0] == null ? w.getBounds() : line[0].union(w.getBounds());
            }
        });
        if (line[0] == null) return;
        // Stretch to the menu list's width so it reads as a row highlight, not just the words.
        Widget rows = client.getWidget(InterfaceID.TelenexusTeleport.ROWS1);
        Rectangle b = line[0];
        if (rows != null && !rows.isHidden()) {
            Rectangle r = rows.getBounds();
            b = new Rectangle(r.x, b.y, r.width, b.height);
        }
        graphics.setColor(HighlightColors.fill(plugin.getConfig().npcHighlightColor()));
        graphics.fill(b);
        graphics.setColor(plugin.getConfig().npcHighlightColor());
        graphics.setStroke(new BasicStroke(2));
        graphics.draw(b);
    }

    private void highlightNexus(Graphics2D graphics) {
        Scene scene = client.getScene();
        if (scene == null) return;
        Tile[][][] tiles = scene.getTiles();
        int z = client.getPlane();
        if (z < 0 || z >= tiles.length) return;
        for (Tile[] row : tiles[z]) {
            if (row == null) continue;
            for (Tile tile : row) {
                if (tile == null) continue;
                GameObject[] objects = tile.getGameObjects();
                if (objects == null) continue;
                for (GameObject obj : objects) {
                    if (obj == null) continue;
                    // GameObjects span multiple tiles; only draw from the anchor tile
                    if (!obj.getSceneMinLocation().equals(tile.getSceneLocation())) continue;
                    ObjectComposition comp = client.getObjectDefinition(obj.getId());
                    if (comp == null) continue;
                    // Built furniture often uses an impostor (varbit-driven) definition.
                    if (comp.getImpostorIds() != null) {
                        ObjectComposition imp = comp.getImpostor();
                        if (imp != null) comp = imp;
                    }
                    String name = comp.getName();
                    if (name == null || !name.toLowerCase().startsWith(NEXUS_NAME)) continue;
                    Shape hull = obj.getConvexHull();
                    if (hull == null) continue;
                    graphics.setColor(HighlightColors.fill(plugin.getConfig().npcHighlightColor()));
                    graphics.fill(hull);
                    graphics.setColor(plugin.getConfig().npcHighlightColor());
                    graphics.setStroke(new BasicStroke(2));
                    graphics.draw(hull);
                }
            }
        }
    }
}

package com.routeplanner.teleport;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

import java.awt.Rectangle;
import java.util.function.Consumer;

/**
 * Reading the Portal Nexus teleport menu. Each row is a clickable background with its text
 * drawn by a separate widget on the same line, so rows are matched up by position rather than
 * by relying on the menu's internal layout.
 */
public final class PortalNexus {

    private PortalNexus() {}

    public static final int MENU_GROUP = InterfaceID.TelenexusTeleport.UNIVERSE >>> 16;

    /** Menu text looks like "<col=..>1</col> : Varrock"; keep just the destination name. */
    public static String cleanText(String raw) {
        if (raw == null) return null;
        String t = Text.removeTags(raw).trim().replaceFirst("^\\w\\s*[:)]\\s*", "").trim();
        return t.isEmpty() ? null : t;
    }

    /** The destination named on the same line as a clicked menu row, or null. */
    public static String rowText(Client client, Widget clicked) {
        if (clicked == null) return null;
        String own = cleanText(clicked.getText());
        if (own != null) return own;
        Rectangle row = clicked.getBounds();
        if (row == null || row.height <= 0) return null;
        String[] best = {null};
        forEachText(client, w -> {
            Rectangle b = w.getBounds();
            int centerY = b.y + b.height / 2;
            if (centerY < row.y || centerY > row.y + row.height) return;
            String t = cleanText(w.getText());
            // A row can also show its hotkey on its own; the longest text is the name.
            if (t != null && (best[0] == null || t.length() > best[0].length())) best[0] = t;
        });
        return best[0];
    }

    /** Every visible widget with text in the open nexus menu (nothing if it's closed). */
    public static void forEachText(Client client, Consumer<Widget> action) {
        Widget root = client.getWidget(InterfaceID.TelenexusTeleport.UNIVERSE);
        if (root != null && !root.isHidden()) visit(root, action);
    }

    private static void visit(Widget w, Consumer<Widget> action) {
        if (w == null || w.isHidden()) return;
        String text = w.getText();
        if (text != null && !text.isEmpty()) action.accept(w);
        for (Widget[] kids : new Widget[][]{w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()}) {
            if (kids == null) continue;
            for (Widget k : kids) visit(k, action);
        }
    }
}

package com.routeplanner.teleport;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;

/**
 * Highlights the teleport spell in the open spellbook for the active step,
 * when that step is a spell-teleport. Highlight only: never casts or clicks.
 * Spell is matched by its sprite id (from TeleportSpells) against spellbook widgets,
 * which is robust to spellbook child-id shifts.
 */
@Singleton
public class SpellbookOverlay extends Overlay {
    private static final int SPELLBOOK_GROUP = 218;

    private final Client client;
    private final RoutePlannerPlugin plugin;

    @Inject
    public SpellbookOverlay(Client client, RoutePlannerPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null) return null;

        String spellName = step.getTeleportSpell();
        if (spellName == null || spellName.trim().isEmpty()) return null;

        TeleportSpell spell = TeleportSpells.getByName(spellName);
        if (spell == null) return null;
        int wantSprite = spell.getSpriteId();

        // spellbook must be open
        Widget book = client.getWidget(SPELLBOOK_GROUP, 0);
        if (book == null || book.isHidden()) return null;

        Widget match = findBySprite(book, wantSprite);
        if (match == null || match.isHidden()) return null;

        Rectangle b = match.getBounds();
        if (b == null) return null;

        Color outline = plugin.getConfig().npcHighlightColor();
        graphics.setColor(outline);
        graphics.setStroke(new BasicStroke(2));
        graphics.drawRect(b.x - 1, b.y - 1, b.width + 2, b.height + 2);
        graphics.setColor(com.routeplanner.util.HighlightColors.fill(outline));
        graphics.fillRect(b.x - 1, b.y - 1, b.width + 2, b.height + 2);
        return null;
    }

    /** Depth-first search the spellbook widget tree for a child whose sprite id matches. */
    private Widget findBySprite(Widget root, int spriteId) {
        if (root == null) return null;
        if (root.getSpriteId() == spriteId && !root.isHidden()) return root;
        for (Widget child : allChildren(root)) {
            Widget found = findBySprite(child, spriteId);
            if (found != null) return found;
        }
        return null;
    }

    private Widget[] merge(Widget[] a, Widget[] b) {
        if (a == null) return b == null ? new Widget[0] : b;
        if (b == null) return a;
        Widget[] out = new Widget[a.length + b.length];
        System.arraycopy(a, 0, out, 0, a.length);
        System.arraycopy(b, 0, out, a.length, b.length);
        return out;
    }

    private Widget[] allChildren(Widget w) {
        Widget[] out = merge(w.getStaticChildren(), w.getDynamicChildren());
        out = merge(out, w.getNestedChildren());
        return out == null ? new Widget[0] : out;
    }
}

package com.routeplanner.teleport;

import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

/**
 * A jewellery/item teleport destination. Unlike spells, a single physical item
 * (e.g. Amulet of glory) has multiple charge states, any of which can teleport;
 * chargeIds lists every item id that should be highlighted in the inventory.
 * iconId is the id used to render the picker icon (highest charge, the "full" look).
 * Highlight only: the plugin never clicks or operates the item.
 */
@Getter
public class TeleportItem {
    private final String displayName;   // e.g. "Amulet of glory: Edgeville"
    private final String itemName;      // e.g. "Amulet of glory" (base item, for grouping)
    private final int[] chargeIds;      // all item ids to match in inventory (any charge)
    private final int iconId;           // item id to render as the picker icon
    private final WorldPoint destination;

    public TeleportItem(String displayName, String itemName, int[] chargeIds, int iconId, WorldPoint destination) {
        this.displayName = displayName;
        this.itemName = itemName;
        this.chargeIds = chargeIds;
        this.iconId = iconId;
        this.destination = destination;
    }

    /** True if the given inventory item id is one of this teleport's charge states. */
    public boolean matchesItemId(int id) {
        for (int c : chargeIds) if (c == id) return true;
        return false;
    }

    @Override
    public String toString() {
        return displayName;
    }
}

package com.routeplanner.teleport;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;

/**
 * Highlights a teleport item in the inventory, or in the equipment tab when it's worn (e.g. a
 * construction cape), for the active step, when that step is an item-teleport. Matches ANY
 * charge state the player is holding (e.g. glory(3) or glory(6)).
 * Highlight only: the plugin never clicks or operates the item.
 */
@Singleton
public class TeleportItemOverlay extends Overlay {
    // Inventory widget group; children carry per-slot item ids and bounds.
    private static final int INVENTORY_GROUP = 149;

    /** Equipment tab slot widgets, indexed by EquipmentInventorySlot index (gaps are unused). */
    private static final int[] WORN_SLOT_WIDGETS = new int[14];
    static {
        WORN_SLOT_WIDGETS[0] = InterfaceID.Wornitems.SLOT0;    // head
        WORN_SLOT_WIDGETS[1] = InterfaceID.Wornitems.SLOT1;    // cape
        WORN_SLOT_WIDGETS[2] = InterfaceID.Wornitems.SLOT2;    // amulet
        WORN_SLOT_WIDGETS[3] = InterfaceID.Wornitems.SLOT3;    // weapon
        WORN_SLOT_WIDGETS[4] = InterfaceID.Wornitems.SLOT4;    // body
        WORN_SLOT_WIDGETS[5] = InterfaceID.Wornitems.SLOT5;    // shield
        WORN_SLOT_WIDGETS[7] = InterfaceID.Wornitems.SLOT7;    // legs
        WORN_SLOT_WIDGETS[9] = InterfaceID.Wornitems.SLOT9;    // gloves
        WORN_SLOT_WIDGETS[10] = InterfaceID.Wornitems.SLOT10;  // boots
        WORN_SLOT_WIDGETS[12] = InterfaceID.Wornitems.SLOT12;  // ring
        WORN_SLOT_WIDGETS[13] = InterfaceID.Wornitems.SLOT13;  // ammo
    }

    private final Client client;
    private final RoutePlannerPlugin plugin;

    @Inject
    public TeleportItemOverlay(Client client, RoutePlannerPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null) return null;

        String itemTele = step.getTeleportItem();
        if (itemTele == null || itemTele.trim().isEmpty()) return null;

        TeleportItem tele = TeleportItems.getByDisplayName(itemTele);
        if (tele == null) return null;

        Widget inv = client.getWidget(INVENTORY_GROUP, 0);
        if (inv != null && !inv.isHidden()) {
            for (Widget item : inventoryItemWidgets(inv)) {
                if (item == null || item.isHidden()) continue;
                if (tele.matchesItemId(item.getItemId())) highlight(graphics, item.getBounds());
            }
        }

        // Worn items: the equipment tab's slot widgets don't carry item ids, so match the
        // worn-items container and highlight that slot's widget (only drawn while the tab is open).
        ItemContainer worn = client.getItemContainer(InventoryID.WORN);
        if (worn != null) {
            Item[] items = worn.getItems();
            for (int slot = 0; slot < items.length && slot < WORN_SLOT_WIDGETS.length; slot++) {
                if (WORN_SLOT_WIDGETS[slot] == 0 || !tele.matchesItemId(items[slot].getId())) continue;
                Widget w = client.getWidget(WORN_SLOT_WIDGETS[slot]);
                if (w != null && !w.isHidden()) highlight(graphics, w.getBounds());
            }
        }
        return null;
    }

    private void highlight(Graphics2D graphics, Rectangle b) {
        if (b == null) return;
        Color outline = plugin.getConfig().npcHighlightColor();
        graphics.setColor(outline);
        graphics.setStroke(new BasicStroke(2));
        graphics.drawRect(b.x, b.y, b.width, b.height);
        graphics.setColor(com.routeplanner.util.HighlightColors.fill(outline));
        graphics.fillRect(b.x, b.y, b.width, b.height);
    }

    /** Inventory item slots live as dynamic children of the inventory widget. */
    private Widget[] inventoryItemWidgets(Widget inv) {
        Widget[] dyn = inv.getDynamicChildren();
        if (dyn != null && dyn.length > 0) return dyn;
        Widget[] child = inv.getChildren();
        return child == null ? new Widget[0] : child;
    }
}

