package com.routeplanner.transport;

import net.runelite.api.coords.WorldPoint;

/**
 * A single plane-changing transition parsed from transports.tsv -- a staircase, ladder, or similar
 * object connecting two tiles on different planes. Distinct from the pathfinder's own
 * TransportLoader, which discards everything except origin->destination as a bare routing edge;
 * this keeps the fields needed to describe and highlight the transition to the player.
 */
public class Transport {
    public final WorldPoint origin;
    public final WorldPoint destination;
    // transports.tsv packs the action and object name into one space-joined column, e.g.
    // "Climb-up Staircase" or "Open Door" -- there is no separate delimiter between them in the
    // real data, so they are kept together rather than force-split into two fields that don't
    // actually exist independently in the source file.
    public final String actionText;   // e.g. "Climb-up Staircase", "Open Door"
    public final int objectId;        // -1 if absent/unparseable
    /** A teleport (spell, item, minigame...): nothing to click in the world, just where it goes. */
    public final boolean teleport;

    public Transport(WorldPoint origin, WorldPoint destination, String actionText, int objectId) {
        this(origin, destination, actionText, objectId, false);
    }

    public Transport(WorldPoint origin, WorldPoint destination, String actionText, int objectId, boolean teleport) {
        this.origin = origin;
        this.destination = destination;
        this.actionText = actionText;
        this.objectId = objectId;
        this.teleport = teleport;
    }

    /** A short, human-readable hint built from the row's own data, e.g. "Climb-up the Staircase". */
    public String hintText() {
        return actionText != null ? actionText : "Use the transition";
    }
}

package com.routeplanner.ui;

import net.runelite.client.game.SpriteManager;

import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;

/**
 * The plugin's icon: the game's own world map button (its globe inside the bronze minimap ring)
 * with a red route pin. The globe and ring are read from the game at runtime, so no game art is
 * stored in the plugin; until they load, the drawn stand-in (route_icon.png) is used.
 */
public final class RouteIcon {

    /** The world map orb's globe and its bronze ring (gameval SpriteID.WorldmapIcon.PLANET, MINIMAP_ORB_WORLD_MAP_FRAME). */
    private static final int GLOBE_SPRITE = 1439;
    private static final int RING_SPRITE = 1438;

    private static final int RED = 0xFFD62626, DARK_RED = 0xFF8C1212, WHITE = 0xFFFFFFFF, OUTLINE = 0xFF280E0A;

    private RouteIcon() {}

    /** Builds the icon once the game's sprites are available, then hands it over (on the client thread). */
    public static void load(SpriteManager sprites, Consumer<BufferedImage> done) {
        sprites.getSpriteAsync(RING_SPRITE, 0, ring ->
            sprites.getSpriteAsync(GLOBE_SPRITE, 0, globe -> {
                if (ring == null || globe == null) return;
                done.accept(compose(ring, globe));
            }));
    }

    /** The ring, the globe centred in it, and the pin at the top right. */
    static BufferedImage compose(BufferedImage ring, BufferedImage globe) {
        BufferedImage out = new BufferedImage(ring.getWidth(), ring.getHeight(), BufferedImage.TYPE_INT_ARGB);
        java.awt.Graphics2D g = out.createGraphics();
        g.drawImage(ring, 0, 0, null);
        g.drawImage(globe, (ring.getWidth() - globe.getWidth()) / 2, (ring.getHeight() - globe.getHeight()) / 2, null);
        g.dispose();
        drawPin(out, out.getWidth() * 2 / 3, out.getHeight() / 10, Math.max(3, out.getWidth() / 7));
        return out;
    }

    /**
     * A map pin: a round red head of radius {@code r} with a white glint, tapering to a point,
     * shaded darker on the right, with a dark one-pixel outline.
     */
    static void drawPin(BufferedImage img, int cx, int top, int r) {
        double cy = top + r;
        double tipY = cy + 2 * r + 1;
        Map<Long, Integer> shape = new HashMap<>();
        for (int y = top; y <= (int) tipY; y++) {
            for (int x = cx - r - 1; x <= cx + r + 1; x++) {
                double dx = x - cx + 0.5, dy = y - cy + 0.5;
                boolean head = dx * dx + dy * dy <= (r + 0.3) * (r + 0.3);
                double half = y >= cy ? (tipY - y) / (tipY - cy) * (r + 0.3) : -1;
                boolean tail = y >= cy && Math.abs(dx) <= half;
                if (!head && !tail) continue;
                boolean shaded = dx > r * 0.35 || y > cy + r;
                shape.put(key(x, y), shaded ? DARK_RED : RED);
            }
        }
        for (Map.Entry<Long, Integer> e : shape.entrySet()) {
            int x = (int) (e.getKey() >> 32), y = (int) (long) e.getKey();
            double dx = x - cx + 0.5, dy = y - cy + 0.5 + 0.8;
            if (dx * dx + dy * dy <= 2.2) e.setValue(WHITE);
        }
        int[][] around = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (Long k : shape.keySet()) {
            int x = (int) (k >> 32), y = (int) (long) k;
            for (int[] d : around) {
                int ox = x + d[0], oy = y + d[1];
                if (!shape.containsKey(key(ox, oy))) set(img, ox, oy, OUTLINE);
            }
        }
        for (Map.Entry<Long, Integer> e : shape.entrySet()) {
            set(img, (int) (e.getKey() >> 32), (int) (long) e.getKey(), e.getValue());
        }
    }

    private static long key(int x, int y) {
        return ((long) x << 32) | (y & 0xFFFFFFFFL);
    }

    private static void set(BufferedImage img, int x, int y, int argb) {
        if (x >= 0 && y >= 0 && x < img.getWidth() && y < img.getHeight()) img.setRGB(x, y, argb);
    }
}

package com.routeplanner.ui;

import com.routeplanner.model.RouteStep;

import javax.swing.Icon;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;

/**
 * A small drawn glyph for what a step asks of the player (talk, buy, gather, kill...), on a dark
 * tile. Drawn rather than loaded so it stays crisp at any size and needs no image resources.
 */
public final class StepIcon implements Icon {

    public enum Kind {
        TALK(new Color(143, 193, 255)), BUY(new Color(255, 211, 77)), SELL(new Color(255, 211, 77)),
        GATHER(new Color(111, 214, 196)), PICKUP(new Color(111, 214, 196)), BANK(new Color(214, 180, 120)),
        AGILITY(new Color(140, 227, 110)), SKILL(new Color(140, 227, 110)), KILL(new Color(255, 122, 107)),
        QUEST(new Color(111, 168, 255)), TELEPORT(new Color(201, 160, 255)), NOTE(new Color(216, 196, 154)),
        WALK(new Color(201, 160, 255));

        public final Color color;
        Kind(Color color) { this.color = color; }
    }

    private static final Color TILE = new Color(20, 20, 20);

    private final Kind kind;
    private final int size;
    private final boolean dim;

    public StepIcon(Kind kind, int size, boolean dim) {
        this.kind = kind;
        this.size = size;
        this.dim = dim;
    }

    /** What the step mainly asks for, in the order a player would describe it. */
    public static Kind kindOf(RouteStep s) {
        if (s.hasQuest()) return Kind.QUEST;
        if (s.getNpcKillCount() > 0) return Kind.KILL;
        boolean talk = (s.getDialogOptions() != null && !s.getDialogOptions().trim().isEmpty())
            || (s.getName() != null && s.getName().startsWith("Talk to"));
        if (talk) return Kind.TALK;
        if (s.hasItems()) {
            String mode = s.getItemMode();
            if ("SHOP".equals(mode)) return Kind.BUY;
            if ("SELL".equals(mode)) return Kind.SELL;
            if ("PICKUP".equals(mode)) {
                return s.getSkillingTargetNpc() != null || s.getSkillingTargetObject() != null ? Kind.GATHER : Kind.PICKUP;
            }
            return Kind.BANK;
        }
        if (s.hasSkillGoal()) return "AGILITY".equalsIgnoreCase(s.getSkillingSkill()) ? Kind.AGILITY : Kind.SKILL;
        if (s.getTeleportMethod() != null) return Kind.TELEPORT;
        if (s.hasNote()) return Kind.NOTE;
        return Kind.WALK;
    }

    @Override public int getIconWidth() { return size; }
    @Override public int getIconHeight() { return size; }

    @Override
    public void paintIcon(Component c, Graphics g, int x, int y) {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.translate(x, y);
        g2.setColor(TILE);
        g2.fillRoundRect(0, 0, size, size, 3, 3);
        // Glyphs are drawn on a 16-unit grid inside a small margin.
        double pad = size * 0.14;
        double s = (size - pad * 2) / 16.0;
        g2.translate(pad, pad);
        g2.scale(s, s);
        Color col = kind.color;
        if (dim) col = new Color(col.getRed(), col.getGreen(), col.getBlue(), 110);
        g2.setColor(col);
        g2.setStroke(new BasicStroke(1.7f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        draw(g2);
        g2.dispose();
    }

    private void draw(Graphics2D g) {
        Path2D p = new Path2D.Double();
        switch (kind) {
            case TALK:
                p.moveTo(2, 3); p.lineTo(14, 3); p.lineTo(14, 11); p.lineTo(7, 11); p.lineTo(4, 14); p.lineTo(4, 11); p.lineTo(2, 11); p.closePath();
                g.draw(p);
                break;
            case BUY:
            case SELL:
                g.draw(new Ellipse2D.Double(2.5, 2.5, 11, 11));
                p.moveTo(8, 5); p.lineTo(8, 11);
                p.moveTo(10, 6.5); p.lineTo(6.8, 6.5); p.curveTo(5.4, 6.5, 5.4, 8.9, 6.8, 8.9);
                p.lineTo(9.2, 8.9); p.curveTo(10.6, 8.9, 10.6, 11.3, 9.2, 11.3); p.lineTo(6, 11.3);
                g.draw(p);
                break;
            case GATHER:
                p.moveTo(1.5, 8); p.curveTo(4.5, 4, 9, 4, 11.5, 8); p.curveTo(9, 12, 4.5, 12, 1.5, 8); p.closePath();
                p.moveTo(11.5, 8); p.lineTo(14.5, 5); p.lineTo(14.5, 11); p.closePath();
                g.draw(p);
                break;
            case PICKUP:
                p.moveTo(4, 6); p.lineTo(12, 6); p.lineTo(13, 14); p.lineTo(3, 14); p.closePath();
                p.moveTo(6, 6); p.curveTo(6, 2.5, 10, 2.5, 10, 6);
                g.draw(p);
                break;
            case BANK:
                p.moveTo(2, 6); p.lineTo(8, 2.5); p.lineTo(14, 6); p.closePath();
                p.moveTo(4, 7.5); p.lineTo(4, 12); p.moveTo(8, 7.5); p.lineTo(8, 12); p.moveTo(12, 7.5); p.lineTo(12, 12);
                p.moveTo(2, 13.5); p.lineTo(14, 13.5);
                g.draw(p);
                break;
            case AGILITY:
                p.moveTo(1.5, 13.5); p.lineTo(14.5, 13.5);
                p.moveTo(4, 13.5); p.lineTo(4, 9); p.lineTo(12, 9); p.lineTo(12, 13.5);
                p.moveTo(3, 6); p.curveTo(5, 3, 11, 3, 13, 6);
                p.moveTo(11, 4.6); p.lineTo(13, 6); p.lineTo(11, 7.2);
                g.draw(p);
                break;
            case SKILL:
                p.moveTo(2, 13); p.lineTo(6, 9); p.lineTo(9, 11); p.lineTo(14, 4);
                p.moveTo(10.5, 4); p.lineTo(14, 4); p.lineTo(14, 7.5);
                g.draw(p);
                break;
            case KILL:
                p.moveTo(13.5, 2.5); p.lineTo(6, 10);
                p.moveTo(13.5, 2.5); p.lineTo(11, 2.5); p.moveTo(13.5, 2.5); p.lineTo(13.5, 5);
                p.moveTo(4, 9); p.lineTo(7, 12); p.moveTo(5.5, 10.5); p.lineTo(2.5, 13.5);
                g.draw(p);
                break;
            case QUEST:
                double[] xs = {8, 9.9, 14.2, 11.1, 11.8, 8, 4.2, 4.9, 1.8, 6.1};
                double[] ys = {1.8, 5.7, 6.3, 9.3, 13.6, 11.6, 13.6, 9.3, 6.3, 5.7};
                p.moveTo(xs[0], ys[0]);
                for (int i = 1; i < xs.length; i++) p.lineTo(xs[i], ys[i]);
                p.closePath();
                g.draw(p);
                break;
            case TELEPORT:
                g.draw(new Ellipse2D.Double(2.5, 2.5, 11, 11));
                g.draw(new Ellipse2D.Double(5.5, 5.5, 5, 5));
                break;
            case NOTE:
                p.moveTo(3, 2); p.lineTo(10, 2); p.lineTo(13, 5); p.lineTo(13, 14); p.lineTo(3, 14); p.closePath();
                p.moveTo(10, 2); p.lineTo(10, 5); p.lineTo(13, 5);
                p.moveTo(5.5, 8); p.lineTo(10.5, 8); p.moveTo(5.5, 10.5); p.lineTo(9, 10.5);
                g.draw(p);
                break;
            case WALK:
            default:
                p.moveTo(8, 14.5); p.curveTo(8, 14.5, 3.8, 10, 3.8, 6.6); p.curveTo(3.8, 1.2, 12.2, 1.2, 12.2, 6.6);
                p.curveTo(12.2, 10, 8, 14.5, 8, 14.5); p.closePath();
                g.draw(p);
                g.draw(new Ellipse2D.Double(6.5, 5.1, 3, 3));
                break;
        }
    }
}

package com.routeplanner.ui;

import com.routeplanner.bank.BankItemManager;
import com.routeplanner.model.RouteStep;

import java.util.List;

/**
 * Live progress for the active step, read on the client thread each tick and handed to the
 * side panel's step card, which only repaints when {@link #signature()} changes.
 */
public final class StepLive {

    /** Distance values that aren't a tile count. */
    public static final int NO_TARGET = -1;
    public static final int OTHER_FLOOR = -2;

    public final RouteStep step;
    public final int distance;
    public final String itemHeader;                         // "Buy", "Gather"...; null without items
    public final List<BankItemManager.ItemProgress> items;
    public final String skillLabel;                         // e.g. "Fishing XP gained"; null without a goal
    public final long skillHave;
    public final long skillNeed;
    public final int dialogDone;

    public StepLive(RouteStep step, int distance, String itemHeader, List<BankItemManager.ItemProgress> items,
                    String skillLabel, long skillHave, long skillNeed, int dialogDone) {
        this.step = step;
        this.distance = distance;
        this.itemHeader = itemHeader;
        this.items = items;
        this.skillLabel = skillLabel;
        this.skillHave = skillHave;
        this.skillNeed = skillNeed;
        this.dialogDone = dialogDone;
    }

    /** Everything shown except the distance, so the card rebuilds only when progress moves. */
    public String signature() {
        StringBuilder sb = new StringBuilder();
        sb.append(System.identityHashCode(step)).append('|').append(itemHeader).append('|');
        if (items != null) for (BankItemManager.ItemProgress i : items) sb.append(i.name).append(':').append(i.have).append('/').append(i.need).append(',');
        sb.append('|').append(skillLabel).append(':').append(skillHave).append('/').append(skillNeed);
        sb.append('|').append(step.getNpcKillProgress()).append('|').append(dialogDone);
        return sb.toString();
    }
}

package com.routeplanner.ui;

import net.runelite.client.ui.ColorScheme;

import javax.swing.JComponent;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;

/** A slim progress bar (route progress, item counts, kills). */
public class ThinBar extends JComponent {

    private double fraction;
    private Color color;

    public ThinBar(int height, Color color) {
        this.color = color;
        setPreferredSize(new Dimension(10, height));
        setMinimumSize(new Dimension(10, height));
        setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
        setAlignmentX(LEFT_ALIGNMENT);
    }

    public void setProgress(long have, long need) {
        double f = need <= 0 ? 0 : Math.max(0, Math.min(1, (double) have / need));
        if (f != fraction) { fraction = f; repaint(); }
    }

    public void setColor(Color color) {
        this.color = color;
        repaint();
    }

    @Override
    protected void paintComponent(Graphics g) {
        int w = getWidth(), h = getHeight();
        g.setColor(ColorScheme.DARKER_GRAY_COLOR.darker());
        g.fillRect(0, 0, w, h);
        g.setColor(color);
        g.fillRect(0, 0, (int) Math.round(w * fraction), h);
    }
}

