package com.routeplanner;

import com.google.gson.*;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import java.lang.reflect.Method;
import java.nio.file.*;
import java.util.List;

/**
 * Checks a route file the way a player walks it: from where each step's path ends to the next step's
 * tile, with the bundled collision map and transports. Prints steps nobody can reach (NO PATH) and
 * steps whose line stops short (CLOSE(n), n tiles off). Only runs when given a route:
 * ROUTE=path/to/route.json ./gradlew test --tests com.routeplanner.RouteTileCheck -i | grep RESULT
 * Add SHOW=<step number> to also print that step's jumps (stairs, transports).
 */
public class RouteTileCheck {
    @Test
    @SuppressWarnings("unchecked")
    public void check() throws Exception {
        org.junit.Assume.assumeTrue("set ROUTE to a route file", System.getenv("ROUTE") != null);
        SailingRouteTest.load();
        java.lang.reflect.Field f = SailingRouteTest.class.getDeclaredField("overlay"); f.setAccessible(true);
        Object overlay = f.get(null);
        Method bp = PathfinderOverlay.class.getDeclaredMethod("buildPath", WorldPoint.class, WorldPoint.class, boolean.class);
        bp.setAccessible(true);
        JsonObject route = new JsonParser().parse(new String(Files.readAllBytes(Paths.get(System.getenv("ROUTE"))))).getAsJsonObject();
        WorldPoint prev = null; int n = 0;
        for (JsonElement se : route.getAsJsonArray("sections")) {
            JsonObject sec = se.getAsJsonObject();
            for (JsonElement ste : sec.getAsJsonArray("steps")) {
                JsonObject st = ste.getAsJsonObject(); n++;
                WorldPoint from = prev;
                if (st.has("teleportDestination")) { JsonObject t = st.getAsJsonObject("teleportDestination"); from = new WorldPoint(t.get("x").getAsInt(), t.get("y").getAsInt(), t.get("plane").getAsInt()); }
                if (!st.has("worldPoint")) { if (st.has("teleportDestination")) prev = from; continue; }
                JsonObject w = st.getAsJsonObject("worldPoint");
                WorldPoint to = new WorldPoint(w.get("x").getAsInt(), w.get("y").getAsInt(), w.get("plane").getAsInt());
                if (from != null && !from.equals(to)) {
                    List<WorldPoint> p = (List<WorldPoint>) bp.invoke(overlay, from, to, false);
                    String tag = sec.get("name").getAsString() + " | " + st.get("name").getAsString() + " " + to.getX() + "," + to.getY() + "," + to.getPlane();
                    if (p.isEmpty()) { System.out.println("RESULT NO PATH   #" + n + " " + tag + " (from " + from.getX() + "," + from.getY() + "," + from.getPlane() + ")"); prev = to; continue; }
                    if (String.valueOf(n).equals(System.getenv("SHOW"))) {
                        // SHOW=<step number>: print the path's jumps (stairs, transports, teleports)
                        for (int i = 1; i < p.size(); i++) {
                            if (p.get(i - 1).distanceTo(p.get(i)) > 1) System.out.println("RESULT   jump " + p.get(i - 1) + " -> " + p.get(i));
                        }
                    }
                    int off = p.get(p.size() - 1).distanceTo(to);
                    if (off > 1) System.out.println("RESULT CLOSE(" + off + ") #" + n + " " + tag);
                    prev = p.get(p.size() - 1);   // where the player actually ends up
                    continue;
                }
                prev = to;
            }
        }
        System.out.println("RESULT checked " + n + " steps");
    }
}

package com.routeplanner;

import com.routeplanner.sailing.SailingDocks;
import com.routeplanner.transport.Transport;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import org.junit.BeforeClass;
import org.junit.Test;

import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

/**
 * Routes over the sea (a beta feature, switched on here) with the bundled collision map, docks and
 * sea routes, as a level 99 sailor whose boats' docks aren't known yet (so any dock can be boarded from).
 */
public class SailingRouteTest {

    private static SailingDocks docks;
    private static PathfinderOverlay overlay;
    private static Method buildPath;
    private static Method smoothSeaLegs;

    @BeforeClass
    public static void load() throws Exception {
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class[]{Client.class},
            (proxy, m, args) -> m.getName().equals("getRealSkillLevel") ? 99
                : m.getReturnType() == int.class ? 0 : m.getReturnType() == boolean.class ? false : null);
        RoutePlannerConfig config = (RoutePlannerConfig) Proxy.newProxyInstance(
            RoutePlannerConfig.class.getClassLoader(), new Class[]{RoutePlannerConfig.class},
            (proxy, m, args) -> m.getName().equals("useSailing") || m.getName().equals("betaFeatures") ? true : null);
        docks = new SailingDocks(client, null);
        docks.onGameTick();
        overlay = new PathfinderOverlay(client, null, config, null, docks);

        Method load = PathfinderOverlay.class.getDeclaredMethod("loadCollisionMap");
        load.setAccessible(true);
        load.invoke(overlay);
        buildPath = PathfinderOverlay.class.getDeclaredMethod("buildPath", WorldPoint.class, WorldPoint.class, boolean.class);
        buildPath.setAccessible(true);
        smoothSeaLegs = PathfinderOverlay.class.getDeclaredMethod("smoothSeaLegs", List.class, boolean.class);
        smoothSeaLegs.setAccessible(true);
    }

    @SuppressWarnings("unchecked")
    private static List<WorldPoint> route(WorldPoint from, WorldPoint to, boolean onBoat) throws Exception {
        List<WorldPoint> path = (List<WorldPoint>) buildPath.invoke(overlay, from, to, onBoat);
        return (List<WorldPoint>) smoothSeaLegs.invoke(overlay, path, onBoat);
    }

    /** The dock crossings along a path, in order, as their action texts. */
    private static List<String> crossings(List<WorldPoint> path) {
        List<String> out = new ArrayList<>();
        for (int i = 0; i + 1 < path.size(); i++) {
            Transport t = docks.crossing(path.get(i), path.get(i + 1));
            if (t != null) out.add(t.actionText);
        }
        return out;
    }

    private static void assertArrives(List<WorldPoint> path, WorldPoint target) {
        assertFalse("no path", path.isEmpty());
        assertTrue("ends at " + path.get(path.size() - 1), path.get(path.size() - 1).distanceTo(target) <= 1);
    }

    @Test
    public void walksToADockSailsAndDisembarksOnAnIsland() throws Exception {
        WorldPoint pandemonium = new WorldPoint(3069, 2987, 0);
        List<WorldPoint> path = route(new WorldPoint(3222, 3218, 0), pandemonium, false);
        assertArrives(path, pandemonium);
        List<String> c = crossings(path);
        assertEquals(c.toString(), 2, c.size());
        assertTrue(c.get(0), c.get(0).startsWith(SailingDocks.BOARD));
        assertEquals(SailingDocks.DISEMBARK + " at The Pandemonium", c.get(1));
    }

    @Test
    public void sailsAroundTheCoastFromOpenSea() throws Exception {
        WorldPoint lunarDock = new WorldPoint(2151, 3881, 0);
        List<WorldPoint> path = route(new WorldPoint(3000, 3100, 0), lunarDock, true);
        assertArrives(path, lunarDock);
        assertEquals("[" + SailingDocks.DISEMBARK + " at Lunar Isle]", crossings(path).toString());
    }

    @Test
    public void sailedLegsAreUnbrokenTileByTile() throws Exception {
        List<WorldPoint> path = route(new WorldPoint(3000, 3100, 0), new WorldPoint(2151, 3881, 0), true);
        for (int i = 0; i + 1 < path.size(); i++) {
            WorldPoint a = path.get(i), b = path.get(i + 1);
            if (docks.crossing(a, b) != null || docks.seaLinksFrom(a) != null) continue;
            assertTrue(a + " -> " + b, Math.max(Math.abs(a.getX() - b.getX()), Math.abs(a.getY() - b.getY())) <= 1);
        }
    }

    /** The fewest tiles from the shore the route comes, away from its ends and the docks, for a boat this wide. */
    @SuppressWarnings("unchecked")
    private static int closestToShore(WorldPoint from, WorldPoint to, int boatWidth) throws Exception {
        java.lang.reflect.Field width = PathfinderOverlay.class.getDeclaredField("boatWidthTiles");
        width.setAccessible(true);
        Method clearance = PathfinderOverlay.class.getDeclaredMethod("clearance", int.class, int.class, int.class);
        clearance.setAccessible(true);
        width.setInt(overlay, boatWidth);
        try {
            List<WorldPoint> path = route(from, to, true);
            assertArrives(path, to);
            int closest = Integer.MAX_VALUE;
            for (WorldPoint p : path) {
                int x = p.getX(), y = p.getY();
                if (Math.max(Math.abs(x - from.getX()), Math.abs(y - from.getY())) <= 6
                    || Math.max(Math.abs(x - to.getX()), Math.abs(y - to.getY())) <= 6
                    || docks.nearMooring(x, y, 6)) continue;
                closest = Math.min(closest, (int) clearance.invoke(overlay, x, y, 0));
            }
            return closest;
        } finally {
            width.setInt(overlay, 1);
        }
    }

    @Test
    public void aSloopKeepsWellClearOfTheShore() throws Exception {
        // East of Rellekka, where the line used to ride the coast
        assertTrue(closestToShore(new WorldPoint(2699, 4075, 0), new WorldPoint(2479, 3854, 0), 3) >= 4);
    }

    @Test
    public void aSloopGoesRoundTheNarrowChannelByEtceteria() throws Exception {
        // From Etceteria west: a 6-8 tile channel between the islands and a small island to the south.
        // A raft takes it; a sloop goes round the small island instead.
        WorldPoint from = new WorldPoint(2615, 3841, 0), to = new WorldPoint(2479, 3854, 0);
        assertTrue("raft", closestToShore(from, to, 1) < 4);
        assertTrue("sloop", closestToShore(from, to, 3) >= 4);
    }

    @Test
    public void docksAtWyrmscraig() throws Exception {
        WorldPoint inland = new WorldPoint(2580, 2296, 0);
        List<WorldPoint> path = route(new WorldPoint(3000, 3100, 0), inland, true);
        assertArrives(path, inland);
        assertEquals("[" + SailingDocks.DISEMBARK + " at Wyrmscraig]", crossings(path).toString());
    }

    @Test
    public void sailsThroughTheCaveMouthIntoWyrmscraigCavern() throws Exception {
        WorldPoint caveFloor = new WorldPoint(2585, 8606, 0);
        List<WorldPoint> path = route(new WorldPoint(3000, 3100, 0), caveFloor, true);
        assertArrives(path, caveFloor);
        assertEquals("[" + SailingDocks.DISEMBARK + " at Wyrmscraig Cavern]", crossings(path).toString());
        assertTrue("goes through the cave mouth", path.contains(new WorldPoint(2557, 2202, 0))
            && path.contains(new WorldPoint(2572, 8606, 0)));
    }

    @Test
    public void walkingRoutesDontTouchTheSea() throws Exception {
        WorldPoint varrock = new WorldPoint(3213, 3424, 0);
        List<WorldPoint> path = route(new WorldPoint(3222, 3218, 0), varrock, false);
        assertArrives(path, varrock);
        assertTrue(crossings(path).isEmpty());
    }
}

package com.routeplanner;

import com.routeplanner.sailing.SailingDocks;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import org.junit.Assume;
import org.junit.Test;

import java.io.PrintWriter;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.*;

/**
 * Makes resources/com/routeplanner/sailing/sea_routes_{raft,skiff,sloop}.tsv: the sea route between every
 * pair of moorings for each boat size, worked out by the plugin's own pathfinder (same clearance and
 * costs as live pathing). Only runs when asked, after a collision map or dock change:
 *
 *   SEA_ROUTES_OUT=src/main/resources/com/routeplanner/sailing ./gradlew test --tests com.routeplanner.SeaRouteGenerator
 */
public class SeaRouteGenerator {

    private static final String[] SIZES = {"raft", "skiff", "sloop"};

    @Test
    public void generate() throws Exception {
        String out = System.getenv("SEA_ROUTES_OUT");
        Assume.assumeTrue("set SEA_ROUTES_OUT=<dir> to generate", out != null && !out.isEmpty());
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class[]{Client.class},
            (p, m, a) -> m.getReturnType() == int.class ? 0 : m.getReturnType() == boolean.class ? false : null);
        RoutePlannerConfig config = (RoutePlannerConfig) Proxy.newProxyInstance(RoutePlannerConfig.class.getClassLoader(),
            new Class[]{RoutePlannerConfig.class}, (p, m, a) -> m.getName().equals("useSailing") || m.getName().equals("betaFeatures") ? true : null);
        SailingDocks docks = new SailingDocks(client, null);
        PathfinderOverlay overlay = new PathfinderOverlay(client, null, config, null, docks);
        Method load = PathfinderOverlay.class.getDeclaredMethod("loadCollisionMap");
        load.setAccessible(true);
        load.invoke(overlay);

        List<WorldPoint> moorings = new ArrayList<>();
        for (SailingDocks.Dock d : docks.getDocks()) moorings.add(d.sea);
        Path dir = Paths.get(out);
        Files.createDirectories(dir);
        for (int size = 0; size < SIZES.length; size++) {
            int width = size + 1;
            long started = System.currentTimeMillis();
            int routes = 0;
            try (PrintWriter w = new PrintWriter(Files.newBufferedWriter(dir.resolve("sea_routes_" + SIZES[size] + ".tsv")))) {
                w.println("# Sea routes between Sailing moorings (see docks.tsv) for a " + SIZES[size] + " (" + width
                    + " tile" + (width > 1 ? "s" : "") + " wide), made by SeaRouteGenerator (tests) with the plugin's pathfinder.");
                w.println("# From mooring\tTo mooring\tSea distance (tiles)\tTurning points");
                for (int i = 0; i < moorings.size(); i++) {
                    Set<WorldPoint> later = new LinkedHashSet<>(moorings.subList(i + 1, moorings.size()));
                    if (later.isEmpty()) break;
                    Map<WorldPoint, List<WorldPoint>> paths = overlay.seaPathsFrom(moorings.get(i), later, width);
                    for (WorldPoint to : later) {
                        List<WorldPoint> path = paths.get(to);
                        if (path == null) continue;
                        StringBuilder turns = new StringBuilder();
                        for (WorldPoint t : overlay.turningPoints(path)) {
                            if (turns.length() > 0) turns.append(';');
                            turns.append(t.getX()).append(' ').append(t.getY());
                        }
                        WorldPoint from = moorings.get(i);
                        w.println(from.getX() + " " + from.getY() + " " + from.getPlane() + "\t" + to.getX() + " " + to.getY() + " "
                            + to.getPlane() + "\t" + (path.size() - 1) + "\t" + turns);
                        routes++;
                    }
                }
            }
            System.out.println("SEA ROUTES " + SIZES[size] + ": " + routes + " in " + (System.currentTimeMillis() - started) / 1000 + "s");
        }
    }
}

package com.routeplanner;

import com.routeplanner.sailing.ShoalRoutes;
import org.junit.Test;

import static org.junit.Assert.*;

public class ShoalRoutesTest {

    @Test
    public void everyBundledShoalHasARouteAndStops() {
        for (int id = 14; id <= 29; id++) {
            ShoalRoutes.Route route = ShoalRoutes.get(id);
            assertNotNull("shoal " + id, route);
            assertTrue("shoal " + id + " path", route.path.size() > 10);
            assertFalse("shoal " + id + " stops", route.stops.isEmpty());
        }
        assertNull(ShoalRoutes.get(1));
    }

    @Test
    public void everyShoalHasAStopTime() {
        assertEquals("marlin", 50, ShoalRoutes.stopTicks(ShoalRoutes.get(14)));
        assertEquals("giant krill", 150, ShoalRoutes.stopTicks(ShoalRoutes.get(29)));
        for (int id = 14; id <= 29; id++) assertTrue("shoal " + id, ShoalRoutes.stopTicks(ShoalRoutes.get(id)) > 0);
    }

    @Test
    public void findsTheRouteByWhereTheShoalIsWhenTheIdDoesntMatch() {
        // On shoal 14's path (the marlin route east of Rellekka), under some other world view id
        net.runelite.api.coords.WorldPoint at = new net.runelite.api.coords.WorldPoint(2718, 4050, 0);
        assertSame(ShoalRoutes.get(14), ShoalRoutes.find(99, at, 10));
        assertSame(ShoalRoutes.get(14), ShoalRoutes.find(14, at, 10));
        assertNull(ShoalRoutes.find(99, new net.runelite.api.coords.WorldPoint(3222, 3218, 0), 10));
    }
}
